 SELECT p.oid,p.prosrc,p.proconfig,p.prosecdef,p.proowner,p.proacl,(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'grantable',a.is_grantable,'privilege',a.privilege_type) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a LIMIT 1) acl INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(e->>'signature') LIMIT 1;
 IF NOT FOUND OR encode(extensions.digest(actual.prosrc,'sha256'),'hex') IS DISTINCT FROM e->>'sha256'
 OR coalesce(to_jsonb(actual.proconfig),'null'::jsonb) IS DISTINCT FROM e->'config' OR actual.prosecdef IS DISTINCT FROM (e->>'secdef')::boolean
 OR pg_get_userbyid(actual.proowner) IS DISTINCT FROM e->>'owner' OR actual.acl IS DISTINCT FROM e->'acl'
 OR has_function_privilege('anon',actual.oid,'EXECUTE') OR has_function_privilege('authenticated',actual.oid,'EXECUTE')
 OR has_function_privilege('service_role',actual.oid,'EXECUTE') IS DISTINCT FROM EXISTS(SELECT 1 FROM jsonb_array_elements(e->'acl') x WHERE x->>'grantee'='service_role' LIMIT 1)
 THEN RAISE EXCEPTION 'COMPOSE frozen pin drift %',e->>'signature' USING ERRCODE='55000'; END IF;
 END LOOP;
