CREATE TEMP TABLE compose48_catalog_after ON COMMIT DROP AS
 WITH ns AS(SELECT oid FROM pg_namespace WHERE nspname !~ '^pg_(toast_)?temp_'), rels AS(SELECT oid FROM pg_class WHERE relnamespace IN(SELECT oid FROM ns))
 SELECT 'class' kind,c.oid::text key,to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'] snapshot FROM pg_class c WHERE oid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'attribute',attrelid||':'||attnum,to_jsonb(a) FROM pg_attribute a WHERE attrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'type',oid::text,to_jsonb(t) FROM pg_type t WHERE typnamespace IN(SELECT oid FROM ns)
 UNION ALL SELECT 'constraint',oid::text,to_jsonb(c) FROM pg_constraint c WHERE connamespace IN(SELECT oid FROM ns)
 UNION ALL SELECT 'trigger',oid::text,to_jsonb(t) FROM pg_trigger t WHERE tgrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'default',oid::text,to_jsonb(d) FROM pg_attrdef d WHERE adrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'policy',oid::text,to_jsonb(p) FROM pg_policy p WHERE polrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'index',indexrelid::text,to_jsonb(i) FROM pg_index i WHERE indrelid IN(SELECT oid FROM rels);
DO $catalog46witness$ DECLARE item46 record; allowed_relations oid[]; BEGIN
 SELECT array_agg(c.oid) INTO allowed_relations FROM pg_class c WHERE c.relnamespace='manutencao48'::regnamespace
 OR c.oid IN(SELECT reltoastrelid FROM pg_class WHERE relnamespace='manutencao48'::regnamespace)
 OR c.oid IN(SELECT i.indexrelid FROM pg_index i WHERE i.indrelid IN(SELECT reltoastrelid FROM pg_class WHERE relnamespace='manutencao48'::regnamespace));
 IF EXISTS(SELECT 1 FROM compose48_catalog_witness w LEFT JOIN compose48_catalog_after a ON a.kind=w.kind AND a.key=w.key
 WHERE a.snapshot IS DISTINCT FROM w.snapshot AND NOT(w.kind='constraint' AND w.snapshot->>'conname' IN('multimodal_operacoes_family_check','multimodal_fences_family_check') AND (w.snapshot->>'conrelid')::oid IN('public.multimodal_operacoes'::regclass,'public.multimodal_fences'::regclass)))
 THEN RAISE EXCEPTION '46 predecessor class/type/attribute/constraint/trigger/policy/index/default delta' USING ERRCODE='55000'; END IF;
 FOR item46 IN SELECT a.* FROM compose48_catalog_after a WHERE NOT EXISTS(SELECT 1 FROM compose48_catalog_witness w WHERE w.kind=a.kind AND w.key=a.key) LOOP
 IF NOT (CASE item46.kind
 WHEN 'class' THEN (item46.snapshot->>'oid')::oid=ANY(allowed_relations)
 WHEN 'attribute' THEN (item46.snapshot->>'attrelid')::oid=ANY(allowed_relations)
 WHEN 'type' THEN (item46.snapshot->>'typrelid')::oid=ANY(allowed_relations) OR (item46.snapshot->>'typnamespace')::oid='manutencao48'::regnamespace
 WHEN 'index' THEN (item46.snapshot->>'indexrelid')::oid=ANY(allowed_relations)
 WHEN 'constraint' THEN (item46.snapshot->>'connamespace')::oid='manutencao48'::regnamespace OR (item46.snapshot->>'conname' IN('multimodal_operacoes_family_check','multimodal_fences_family_check') AND (item46.snapshot->>'conrelid')::oid IN('public.multimodal_operacoes'::regclass,'public.multimodal_fences'::regclass))
 ELSE false END) THEN RAISE EXCEPTION '46 unexpected new catalog % %',item46.kind,item46.key USING ERRCODE='55000'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM pg_class WHERE relnamespace='manutencao48'::regnamespace AND relkind='r')<>1
 OR (SELECT count(*) FROM pg_class WHERE relnamespace='manutencao48'::regnamespace AND relkind='i')<>1
 OR (SELECT count(*) FROM pg_constraint WHERE connamespace='manutencao48'::regnamespace)<>2
 OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='manutencao48.manifesto'::regclass)
 OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='manutencao48.manifesto'::regclass)
 THEN RAISE EXCEPTION '46 new family journal shape not allowlisted' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM pg_type WHERE typnamespace='manutencao48'::regnamespace)<>2
 OR EXISTS(SELECT 1 FROM pg_type WHERE typnamespace='manutencao48'::regnamespace AND typname NOT IN('manifesto','_manifesto'))
 OR EXISTS(SELECT 1 FROM pg_class WHERE relnamespace='manutencao48'::regnamespace AND relname NOT IN('manifesto','manifesto_pkey'))
 OR (SELECT count(*) FROM pg_constraint WHERE conname IN('multimodal_operacoes_family_check','multimodal_fences_family_check') AND conrelid IN('public.multimodal_operacoes'::regclass,'public.multimodal_fences'::regclass)
 AND contype='c' AND convalidated AND NOT connoinherit
 AND pg_get_constraintdef(oid)=$exact46check$CHECK ((family = ANY (ARRAY['multimodal_criar'::text, 'multimodal_receber'::text, 'multimodal_renovar'::text, 'multimodal_calendario46'::text, 'multimodal_manutencao48'::text])))$exact46check$)<>2
 THEN RAISE EXCEPTION '46 exact CHECK family or new journal type delta rejected' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='manutencao48' AND a.grantee<>n.nspowner)
 OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a WHERE c.oid=ANY(allowed_relations) AND a.grantee<>c.relowner)
 THEN RAISE EXCEPTION '46 new journal inherited grant rejected' USING ERRCODE='55000'; END IF;
END $catalog46witness$;
DO $compose_gate$ DECLARE e jsonb; actual record; total int; fullmanaged boolean; BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('server_version_num')::int/10000<>17
 OR current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'COMPOSE PG17 owner session isolation' USING ERRCODE='55000'; END IF;
 SELECT count(*) INTO total FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname !~ '^pg_' AND ns.nspname NOT IN('information_schema','extensions') LIMIT 1;
 IF total NOT IN(291,361) THEN RAISE EXCEPTION 'COMPOSE exact count rejected %, expected 291 or 361',total USING ERRCODE='55000'; END IF;
 fullmanaged:=total=361;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='postgres' AND NOT rolsuper AND rolcanlogin LIMIT 1)
 OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role' AND NOT rolsuper AND NOT rolcanlogin LIMIT 1)
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('anon','authenticated') AND (rolsuper OR rolbypassrls OR rolcanlogin) LIMIT 1)
 OR (SELECT count(*) FROM pg_roles WHERE rolname IN('postgres','service_role','anon','authenticated') LIMIT 1)<>4
 OR (SELECT rolbypassrls FROM pg_roles WHERE rolname='postgres' LIMIT 1) IS DISTINCT FROM (SELECT rolbypassrls FROM pg_roles WHERE rolname='service_role' LIMIT 1)
 OR (fullmanaged AND NOT(SELECT rolbypassrls FROM pg_roles WHERE rolname='postgres' LIMIT 1))
 THEN RAISE EXCEPTION 'COMPOSE strict NONSUPER paired fixture or observed managed roles' USING ERRCODE='55000'; END IF;
