 FOR e IN SELECT value FROM jsonb_array_elements($extrascompose$[{"schema":"auth","name":"email","oid":16544,"args":"","argtypes":"","prosrc":"\n  select \n  coalesce(\n    nullif(current_setting('request.jwt.claim.email', true), ''),\n    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email')\n  )::text\n","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION auth.email()\n RETURNS text\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n  coalesce(\n    nullif(current_setting('request.jwt.claim.email', true), ''),\n    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email')\n  )::text\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_auth_admin","sha256":"3fec00caef3382faec0a6b4bf3da0a4fe86e31b733957b3967539d1ea1bb5c42","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_auth_admin","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"auth.email()","definition_sha256":"6964175d0bad9d5ea355d2e8c4ad9a99147348b817213e85fcb0d4122a72b621","language":"sql"},{"schema":"auth","name":"jwt","oid":16709,"args":"","argtypes":"","prosrc":"\n  select \n    coalesce(\n        nullif(current_setting('request.jwt.claim', true), ''),\n        nullif(current_setting('request.jwt.claims', true), '')\n    )::jsonb\n","probin":null,"rettype":"jsonb","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION auth.jwt()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n    coalesce(\n        nullif(current_setting('request.jwt.claim', true), ''),\n        nullif(current_setting('request.jwt.claims', true), '')\n    )::jsonb\n$function$\n","co