"}],"signature":"auth.role()","definition_sha256":"c96a9358b02089b03f3962fd85c5f83c9d64f32240481915c0efe74398dc761b","language":"sql"},{"schema":"auth","name":"uid","oid":16542,"args":"","argtypes":"","prosrc":"\n  select \n  coalesce(\n    nullif(current_setting('request.jwt.claim.sub', true), ''),\n    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')\n  )::uuid\n","probin":null,"rettype":"uuid","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION auth.uid()\n RETURNS uuid\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n  coalesce(\n    nullif(current_setting('request.jwt.claim.sub', true), ''),\n    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')\n  )::uuid\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_auth_admin","sha256":"9ab5ea099e74ec09e83b1505c51a3647791195aed7c742dcc3f257dfc7d2f300","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_auth_admin","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"auth.uid()","definition_sha256":"7c1ff2ecbe653c9358b3115a2607db9573f88a2944ae4eca9e296a89cc5186a7","language":"sql"},{"schema":"graphql_public","name":"graphql","oid":29701,"args":"\"operationName\" text, query text, variables jsonb, extensions jsonb","argtypes":"text, text, jsonb, jsonb","prosrc":"\n            DECLARE\n                server_version float;\n            BEGIN\n                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);\n\n                IF server_version >= 14 THEN\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql extension is not enabled.'\n                            )\n                        )\n                    );\n                ELSE\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'\n                            )\n                        )\n                    );\n                END IF;\n            END;\n        ","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION graphql_public.graphql(\"operationName\" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\n            DECLARE\n                server_version float;\n            BEGIN\n                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);\n\n                IF server_version >= 14 THEN\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql extension is not enabled.'\n                            )\n                        )\n                    );\n                ELSE\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'\n                            )\n                        )\n                    );\n                END IF;\n            END;\n        $function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"d2330ee1a8a4e6fbe400b0e12c15a6cff5d26a37c8c499cea45bab56a43d3bcb","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"graphql_public.graphql(text, text, jsonb, jsonb)","definition_sha256":"62b09c65abb4755df514ce62bd736c05446d2644943b584ae2513334f44dbd08","language":"plpgsql"},{"schema":"pgbouncer","name":"get_auth","oid":16391,"args":"p_usename text","argtypes":"text","prosrc":"\n  BEGIN\n      RAISE DEBUG 'PgBouncer auth request: %', p_usename;\n\n      RETURN QUERY\n      SELECT\n          rolname::text,\n          CASE WHEN rolvaliduntil < now()\n              THEN null\n              ELSE rolpassword::text\n          END\n      FROM pg_authid\n      WHERE rolname=$1 and rolcanlogin;\n  END;\n  ","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION pgbouncer.get_auth(p_usename text)\n RETURNS TABLE(username text, password text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\n  BEGIN\n      RAISE DEBUG 'PgBouncer auth request: %', p_usename;\n\n      RETURN QUERY\n      SELECT\n          rolname::text,\n          CASE WHEN rolvaliduntil < now()\n              THEN null\n              ELSE rolpassword::text\n          END\n      FROM pg_authid\n      WHERE rolname=$1 and rolcanlogin;\n  END;\n  $function$\n","config":["search_path=\"\""],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"5b36fdbb408a04bbb5f7ef269b60a548a427496fc6868b861785d86e09af2cc5","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"pgbouncer","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"pgbouncer.get_auth(text)","definition_sha256":"413884404a27edfc9314be3ecc9db38763920fd49d8f3e0ce1b5a38f1f8f30bf","language":"plpgsql"},{"schema":"public","name":"blacklist_access_guard","oid":31365,"args":"","argtypes":"","prosrc":"\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RAISE EXCEPTION 'Revogue a concessão; exclusão não permitida' USING ERRCODE='23514';\n  END IF;\n  PERFORM 1 FROM public.users WHERE id=NEW.granted_by AND role::text='admin' FOR SHARE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Concessor deve ser admin existente' USING ERRCODE='42501';\n  END IF;\n  NEW.updated_at := clock_timestamp();\n  IF TG_OP='INSERT' THEN NEW.created_at := NEW.updated_at; END IF;\n  IF TG_OP='UPDATE' AND (NEW.user_id <> OLD.user_id OR NEW.created_at <> OLD.created_at) THEN\n    RAISE EXCEPTION 'Identidade/histórico de concessão imutáveis' USING ERRCODE='23514';\n  END IF;\n  INSERT INTO public.blacklist_access_audit(user_id, actor_id, action, before_data, after_data)\n  VALUES (NEW.user_id, NEW.granted_by, TG_OP,\n          CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END, to_jsonb(NEW));\n  RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.blacklist_access_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RAISE EXCEPTION 'Revogue a concessão; exclusão não permitida' USING ERRCODE='23514';\n  END IF;\n  PERFORM 1 FROM public.users WHERE id=NEW.granted_by AND role::text='admin' FOR SHARE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Concessor deve ser admin existente' USING ERRCODE='42501';\n  END IF;\n  NEW.updated_at := clock_timestamp();\n  IF TG_OP='INSERT' THEN NEW.created_at := NEW.updated_at; END IF;\n  IF TG_OP='UPDATE' AND (NEW.user_id <> OLD.user_id OR NEW.created_at <> OLD.created_at) THEN\n    RAISE EXCEPTION 'Identidade/histórico de concessão imutáveis' USING ERRCODE='23514';\n  END IF;\n  INSERT INTO public.blacklist_access_audit(user_id, actor_id, action, before_data, after_data)\n  VALUES (NEW.user_id, NEW.granted_by, TG_OP,\n          CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END, to_jsonb(NEW));\n  RETURN NEW;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"e5e0175dcb68fcb5dc659d1435499c910c037e360ec6c128125783cacd650f11","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.blacklist_access_guard()","definition_sha256":"4790aa50ead4bc87b71fc00f340a703628dd3e45b5cd7143692ec6032c264ea5","language":"plpgsql"},{"schema":"public","name":"blacklist_delete_empty_owned","oid":31367,"args":"target_id integer, owner_id integer","argtypes":"integer, integer","prosrc":"\nBEGIN\n  PERFORM 1 FROM public.blacklist WHERE id=target_id AND cadastrado_por_user_id=owner_id FOR UPDATE;\n  IF NOT FOUND THEN RETURN false; END IF;\n  IF EXISTS(SELECT 1 FROM public.blacklist_fotos WHERE blacklist_id=target_id) THEN\n    RAISE EXCEPTION 'Remova primeiro as fotos com compensação privada' USING ERRCODE='23514';\n  END IF;\n  DELETE FROM public.blacklist WHERE id=target_id AND cadastrado_por_user_id=owner_id;\n  RETURN FOUND;\nEND;\n","probin":null,"rettype":"boolean","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.blacklist_delete_empty_owned(target_id integer, owner_id integer)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  PERFORM 1 FROM public.blacklist WHERE id=target_id AND cadastrado_por_user_id=owner_id FOR UPDATE;\n  IF NOT FOUND THEN RETURN false; END IF;\n  IF EXISTS(SELECT 1 FROM public.blacklist_fotos WHERE blacklist_id=target_id) THEN\n    RAISE EXCEPTION 'Remova primeiro as fotos com compensação privada' USING ERRCODE='23514';\n  END IF;\n  DELETE FROM public.blacklist WHERE id=target_id AND cadastrado_por_user_id=owner_id;\n  RETURN FOUND;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"65e60515ea19f3669bb51e53de8ca2abe3df7a7a07bd09ff8de9491550f9647f","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.blacklist_delete_empty_owned(integer, integer)","definition_sha256":"d33fe42c976c023fa6c71f132e8978e2b164d930f83e71f25f6a6f6f3593a549","language":"plpgsql"},{"schema":"public","name":"blacklist_fotos_guard","oid":31268,"args":"","argtypes":"","prosrc":"\nDECLARE\n  parent_id integer;\n  target_id integer;\n  previous_id integer;\nBEGIN\n  IF TG_OP <> 'DELETE' THEN target_id := NEW.blacklist_id; END IF;\n  IF TG_OP <> 'INSERT' THEN previous_id := OLD.blacklist_id; END IF;\n\n  -- Ordem estável para movimentos entre pais. DELETE CASCADE pode não encontrar\n  -- o pai, pois este já foi removido pela própria transação; isso é intencional.\n  FOR parent_id IN\n    SELECT b.id FROM public.blacklist AS b\n    WHERE b.id = target_id OR b.id = previous_id ORDER BY b.id FOR UPDATE\n  LOOP\n    -- Conflito MVCC real: em REPEATABLE READ/SERIALIZABLE um snapshot anterior\n    -- deve abortar (40001), nunca admitir a sexta foto com contagem obsoleta.\n    -- Preserva todos os valores, inclusive updatedAt (não é um timestamp hook).\n    UPDATE public.blacklist SET \"updatedAt\" = \"updatedAt\" WHERE id = parent_id;\n  END LOOP;\n\n  IF TG_OP <> 'DELETE' THEN\n    IF NOT EXISTS (SELECT 1 FROM public.blacklist WHERE id = target_id) THEN\n      RAISE EXCEPTION 'blacklist_fotos: pai inexistente' USING ERRCODE = '23503';\n    END IF;\n    IF (SELECT count(*) FROM public.blacklist_fotos AS f\n        WHERE f.blacklist_id = target_id\n          AND (TG_OP = 'INSERT' OR f.id <> OLD.id)) >= 5 THEN\n      RAISE EXCEPTION 'blacklist_fotos: limite de cinco fotos por registro'\n        USING ERRCODE = '23514', CONSTRAINT = 'blacklist_fotos_max_five';\n    END IF;\n    RETURN NEW;\n  END IF;\n  RETURN OLD;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.blacklist_fotos_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  parent_id integer;\n  target_id integer;\n  previous_id integer;\nBEGIN\n  IF TG_OP <> 'DELETE' THEN target_id := NEW.blacklist_id; END IF;\n  IF TG_OP <> 'INSERT' THEN previous_id := OLD.blacklist_id; END IF;\n\n  -- Ordem estável para movimentos entre pais. DELETE CASCADE pode não encontrar\n  -- o pai, pois este já foi removido pela própria transação; isso é intencional.\n  FOR parent_id IN\n    SELECT b.id FROM public.blacklist AS b\n    WHERE b.id = target_id OR b.id = previous_id ORDER BY b.id FOR UPDATE\n  LOOP\n    -- Conflito MVCC real: em REPEATABLE READ/SERIALIZABLE um snapshot anterior\n    -- deve abortar (40001), nunca admitir a sexta foto com contagem obsoleta.\n    -- Preserva todos os valores, inclusive updatedAt (não é um timestamp hook).\n    UPDATE public.blacklist SET \"updatedAt\" = \"updatedAt\" WHERE id = parent_id;\n  END LOOP;\n\n  IF TG_OP <> 'DELETE' THEN\n    IF NOT EXISTS (SELECT 1 FROM public.blacklist WHERE id = target_id) THEN\n      RAISE EXCEPTION 'blacklist_fotos: pai inexistente' USING ERRCODE = '23503';\n    END IF;\n    IF (SELECT count(*) FROM public.blacklist_fotos AS f\n        WHERE f.blacklist_id = target_id\n          AND (TG_OP = 'INSERT' OR f.id <> OLD.id)) >= 5 THEN\n      RAISE EXCEPTION 'blacklist_fotos: limite de cinco fotos por registro'\n        USING ERRCODE = '23514', CONSTRAINT = 'blacklist_fotos_max_five';\n    END IF;\n    RETURN NEW;\n  END IF;\n  RETURN OLD;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"c0b4f192a1b00691c1e6e258a2e1c9ee5dbea08a54748d1623e804dba5aa995c","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.blacklist_fotos_guard()","definition_sha256":"116039b8653977479c2223ffb4c0c7c895fb12a677f2fb11e4033075c1112269","language":"plpgsql"},{"schema":"public","name":"consume_password_reset_and_revoke_sessions","oid":31190,"args":"p_token_hash text, p_password_hash text","argtypes":"text, text","prosrc":"\n    DECLARE\n      v_user_id integer;\n    BEGIN\n      IF p_token_hash IS NULL OR length(p_token_hash) <> 64\n         OR p_password_hash IS NULL OR length(p_password_hash) < 20 THEN\n        RAISE EXCEPTION 'Parâmetros de recuperação inválidos' USING ERRCODE = '22023';\n      END IF;\n\n      UPDATE public.password_resets\n      SET used = true\n      WHERE token = p_token_hash\n        AND used = false\n        AND expires_at > now()\n      RETURNING password_resets.user_id INTO v_user_id;\n\n      IF v_user_id IS NULL THEN\n        RETURN;\n      END IF;\n\n      RETURN QUERY\n      UPDATE public.users\n      SET \"passwordHash\" = p_password_hash,\n          \"updatedAt\" = now()\n      WHERE id = v_user_id\n      RETURNING users.id, users.session_version;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Usuário associado ao token não encontrado' USING ERRCODE = '23503';\n      END IF;\n    END;\n    ","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.consume_password_reset_and_revoke_sessions(p_token_hash text, p_password_hash text)\n RETURNS TABLE(user_id integer, session_version integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\n    DECLARE\n      v_user_id integer;\n    BEGIN\n      IF p_token_hash IS NULL OR length(p_token_hash) <> 64\n         OR p_password_hash IS NULL OR length(p_password_hash) < 20 THEN\n        RAISE EXCEPTION 'Parâmetros de recuperação inválidos' USING ERRCODE = '22023';\n      END IF;\n\n      UPDATE public.password_resets\n      SET used = true\n      WHERE token = p_token_hash\n        AND used = false\n        AND expires_at > now()\n      RETURNING password_resets.user_id INTO v_user_id;\n\n      IF v_user_id IS NULL THEN\n        RETURN;\n      END IF;\n\n      RETURN QUERY\n      UPDATE public.users\n      SET \"passwordHash\" = p_password_hash,\n          \"updatedAt\" = now()\n      WHERE id = v_user_id\n      RETURNING users.id, users.session_version;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Usuário associado ao token não encontrado' USING ERRCODE = '23503';\n      END IF;\n    END;\n    $function$\n","config":["search_path=pg_catalog, public"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"e524e2a3ed88a98b15f7b9ec8d7425e3a9d1c7d16fafe6a03184c1a210dcea61","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.consume_password_reset_and_revoke_sessions(text, text)","definition_sha256":"a349663b9549977cc73171858a46956fc0d2b0433ad1f2d66298c00357511c3d","language":"plpgsql"},{"schema":"public","name":"kiwify_blacklist_identity","oid":31980,"args":"","argtypes":"","prosrc":"\nBEGIN\n  IF TG_OP='DELETE' THEN\n    RAISE EXCEPTION 'Assinatura Kiwify não pode ser excluída' USING ERRCODE='23514';\n  END IF;\n  IF NEW.subscription_id IS DISTINCT FROM OLD.subscription_id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.created_at IS DISTINCT FROM OLD.created_at\n     OR (OLD.financial_revoked AND NOT NEW.financial_revoked)\n     OR (OLD.review_required AND NOT NEW.review_required)\n     OR (OLD.access_until IS NOT NULL AND (NEW.access_until IS NULL OR NEW.access_until < OLD.access_until))\n     OR (OLD.latest_event_at IS NOT NULL AND (NEW.latest_event_at IS NULL OR NEW.latest_event_at < OLD.latest_event_at)) THEN\n    RAISE EXCEPTION 'Identidade/período/watermark/revogação Kiwify imutáveis ou monotônicos' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.kiwify_blacklist_identity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF TG_OP='DELETE' THEN\n    RAISE EXCEPTION 'Assinatura Kiwify não pode ser excluída' USING ERRCODE='23514';\n  END IF;\n  IF NEW.subscription_id IS DISTINCT FROM OLD.subscription_id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n     OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.created_at IS DISTINCT FROM OLD.created_at\n     OR (OLD.financial_revoked AND NOT NEW.financial_revoked)\n     OR (OLD.review_required AND NOT NEW.review_required)\n     OR (OLD.access_until IS NOT NULL AND (NEW.access_until IS NULL OR NEW.access_until < OLD.access_until))\n     OR (OLD.latest_event_at IS NOT NULL AND (NEW.latest_event_at IS NULL OR NEW.latest_event_at < OLD.latest_event_at)) THEN\n    RAISE EXCEPTION 'Identidade/período/watermark/revogação Kiwify imutáveis ou monotônicos' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"e3cf72d59b128b5a39ef91f89ae96606f187364c764d62ca362c478fa1d61b66","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.kiwify_blacklist_identity()","definition_sha256":"5b7f195dcc18cdc709ecd3f6a95efb2d699e14f663d8151ef8e9213972c2b5a4","language":"plpgsql"},{"schema":"public","name":"kiwify_blacklist_immutable","oid":31979,"args":"","argtypes":"","prosrc":"\nBEGIN\n  RAISE EXCEPTION 'Ledger Kiwify append-only: alteração/exclusão/truncate proibidos' USING ERRCODE='23514';\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.kiwify_blacklist_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  RAISE EXCEPTION 'Ledger Kiwify append-only: alteração/exclusão/truncate proibidos' USING ERRCODE='23514';\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"c904bf80dddcba0906ce18c51f00099185fc0252b6d055e1852a49fce0affcda","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.kiwify_blacklist_immutable()","definition_sha256":"14fb381b779589ac84a5f77985bda0bd2462d42f3e6d279718ca1636e8588efd","language":"plpgsql"},{"schema":"public","name":"kiwify_buyer_identity","oid":32080,"args":"","argtypes":"","prosrc":"\nBEGIN\n  IF TG_OP IN ('DELETE','TRUNCATE') THEN\n    RAISE EXCEPTION 'Vínculo Kiwify imutável' USING ERRCODE='23514';\n  END IF;\n  IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.subscription_id IS DISTINCT FROM OLD.subscription_id\n    OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n    OR NEW.email IS DISTINCT FROM OLD.email OR NEW.created_user IS DISTINCT FROM OLD.created_user\n    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Identidade de comprador imutável' USING ERRCODE='23514';\n  END IF;\n  IF NOT ((OLD.invite_state IN ('pending','retryable') AND NEW.invite_state='sending' AND NEW.token_hash IS NOT NULL\n      AND NEW.token_hash IS DISTINCT FROM OLD.token_hash)\n    OR (OLD.invite_state='sending' AND NEW.invite_state IN ('accepted','retryable','unknown','blocked')\n      AND NEW.token_hash IS NOT DISTINCT FROM OLD.token_hash)) THEN\n    RAISE EXCEPTION 'Transição de convite inválida' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.kiwify_buyer_identity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF TG_OP IN ('DELETE','TRUNCATE') THEN\n    RAISE EXCEPTION 'Vínculo Kiwify imutável' USING ERRCODE='23514';\n  END IF;\n  IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.subscription_id IS DISTINCT FROM OLD.subscription_id\n    OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n    OR NEW.email IS DISTINCT FROM OLD.email OR NEW.created_user IS DISTINCT FROM OLD.created_user\n    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'Identidade de comprador imutável' USING ERRCODE='23514';\n  END IF;\n  IF NOT ((OLD.invite_state IN ('pending','retryable') AND NEW.invite_state='sending' AND NEW.token_hash IS NOT NULL\n      AND NEW.token_hash IS DISTINCT FROM OLD.token_hash)\n    OR (OLD.invite_state='sending' AND NEW.invite_state IN ('accepted','retryable','unknown','blocked')\n      AND NEW.token_hash IS NOT DISTINCT FROM OLD.token_hash)) THEN\n    RAISE EXCEPTION 'Transição de convite inválida' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"68dd9dabba58d9dbc79afe24fb9454ce54ebef571aa18506cdc61adf18ae990b","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.kiwify_buyer_identity()","definition_sha256":"b4d97b5eecc9ea298a07a43b7362ea48a931e0f5a331997f4767e99702bd184f","language":"plpgsql"},{"schema":"public","name":"revogar_sessoes_ao_alterar_senha","oid":31188,"args":"","argtypes":"","prosrc":"\n    BEGIN\n      IF (to_jsonb(OLD) ->> 'passwordHash') IS DISTINCT FROM (to_jsonb(NEW) ->> 'passwordHash') THEN\n        NEW.session_version := OLD.session_version + 1;\n      END IF;\n      RETURN NEW;\n    END;\n    ","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.revogar_sessoes_ao_alterar_senha()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\n    BEGIN\n      IF (to_jsonb(OLD) ->> 'passwordHash') IS DISTINCT FROM (to_jsonb(NEW) ->> 'passwordHash') THEN\n        NEW.session_version := OLD.session_version + 1;\n      END IF;\n      RETURN NEW;\n    END;\n    $function$\n","config":["search_path=pg_catalog, public"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"4407ad666c206b34f22ce3ef7d818dbb30160ee165c9893b4379c95bcf5df55c","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.revogar_sessoes_ao_alterar_senha()","definition_sha256":"d3e4abb9cf44b6223d34271f014a4e3112cc6c8448ded0630387fee3236755dd","language":"plpgsql"},{"schema":"public","name":"rpc_concluir_onboarding","oid":31204,"args":"p_user_id integer, p_nome_empresa text, p_nome_conta text, p_tipo_conta text","argtypes":"integer, text, text, text","prosrc":"\nDECLARE\n  v_empresa text;\n  v_nome text;\n  v_tipo text;\n  v_completed boolean;\n  v_empresa_salva text;\n  v_conta_id integer;\n  v_nome_salvo text;\n  v_tipo_salvo text;\n  v_created boolean := false;\n  v_user_confirmado integer;\n  v_conta_confirmada integer;\n  v_trim text := E' \\t\\n\\r\\f\\013' || U&'\\00A0\\1680\\2000\\2001\\2002\\2003\\2004\\2005\\2006\\2007\\2008\\2009\\200A\\2028\\2029\\202F\\205F\\3000\\FEFF';\nBEGIN\n  v_empresa := pg_catalog.btrim(p_nome_empresa, v_trim);\n  v_nome := pg_catalog.btrim(p_nome_conta, v_trim);\n  v_tipo := pg_catalog.btrim(p_tipo_conta, v_trim);\n  IF p_user_id IS NULL OR p_user_id <= 0\n     OR v_empresa IS NULL OR pg_catalog.char_length(v_empresa) NOT BETWEEN 1 AND 255\n     OR v_nome IS NULL OR pg_catalog.char_length(v_nome) NOT BETWEEN 1 AND 255\n     OR v_tipo IS NULL OR v_tipo NOT IN ('caixa','banco','digital') THEN\n    RAISE EXCEPTION 'Dados de onboarding inválidos' USING ERRCODE='22023';\n  END IF;\n\n  -- Serializa primeira conclusão e retries. Owner vem do servidor, não do formulário.\n  SELECT u.onboarding_completo, u.nome_empresa\n    INTO v_completed, v_empresa_salva\n    FROM public.users AS u WHERE u.id = p_user_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Usuário indisponível' USING ERRCODE='42501';\n  END IF;\n  IF v_completed AND v_empresa_salva IS DISTINCT FROM v_empresa THEN\n    RAISE EXCEPTION 'Onboarding já concluído com dados diferentes' USING ERRCODE='23505';\n  END IF;\n\n  SELECT c.id, c.nome, c.tipo INTO v_conta_id, v_nome_salvo, v_tipo_salvo\n    FROM public.contas_caixa AS c\n    WHERE c.user_id = p_user_id AND c.ativo = true\n    ORDER BY c.id LIMIT 1 FOR UPDATE;\n  IF FOUND THEN\n    -- Sem tabela de intenção: o preset precisa coincidir exatamente com a conta escolhida.\n    -- Nunca renomear/ativar/alterar saldo para fazer um replay parecer válido.\n    IF v_nome_salvo IS DISTINCT FROM v_nome OR v_tipo_salvo IS DISTINCT FROM v_tipo THEN\n      RAISE EXCEPTION 'Conta ativa incompatível com a intenção de onboarding' USING ERRCODE='23505';\n    END IF;\n  ELSE\n    IF v_completed THEN\n      RAISE EXCEPTION 'Onboarding concluído sem conta ativa; exige revisão explícita' USING ERRCODE='23505';\n    END IF;\n    -- Inativas permanecem intocadas. O resultado informa explicitamente a nova conta.\n    INSERT INTO public.contas_caixa (user_id, nome, tipo, saldo, ativo)\n      VALUES (p_user_id, v_nome, v_tipo, 0, true) RETURNING id INTO v_conta_id;\n    IF v_conta_id IS NULL OR v_conta_id <= 0 THEN\n      RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n    END IF;\n    v_created := true;\n  END IF;\n\n  -- Releitura detecta INSERT suprimido ou adulterado por triggers, inclusive AFTER.\n  SELECT c.id INTO v_conta_confirmada FROM public.contas_caixa AS c\n    WHERE c.id = v_conta_id AND c.id > 0 AND c.user_id = p_user_id\n      AND c.ativo = true AND c.nome = v_nome AND c.tipo = v_tipo\n      AND (NOT v_created OR c.saldo = 0) FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n  END IF;\n\n  IF NOT v_completed THEN\n    UPDATE public.users AS u\n      SET onboarding_completo = true, nome_empresa = v_empresa, \"updatedAt\" = pg_catalog.clock_timestamp()\n      WHERE u.id = p_user_id AND u.onboarding_completo = false\n      RETURNING u.id INTO v_user_confirmado;\n    IF v_user_confirmado IS DISTINCT FROM p_user_id THEN\n      RAISE EXCEPTION 'Usuário não confirmado' USING ERRCODE='23514';\n    END IF;\n  END IF;\n  SELECT u.id INTO v_user_confirmado FROM public.users AS u\n    WHERE u.id = p_user_id AND u.onboarding_completo = true AND u.nome_empresa = v_empresa;\n  IF NOT FOUND OR v_user_confirmado IS DISTINCT FROM p_user_id THEN\n    RAISE EXCEPTION 'Usuário não confirmado' USING ERRCODE='23514';\n  END IF;\n  -- Confirma também a conta depois do UPDATE de users (triggers podem ter efeitos laterais).\n  PERFORM c.id FROM public.contas_caixa AS c\n    WHERE c.id = v_conta_confirmada AND c.user_id = p_user_id AND c.ativo = true\n      AND c.nome = v_nome AND c.tipo = v_tipo AND (NOT v_created OR c.saldo = 0);\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n  END IF;\n  RETURN pg_catalog.jsonb_build_object(\n    'success', true, 'id', v_user_confirmado, 'conta_id', v_conta_confirmada,\n    'onboardingCompleto', true, 'nomeEmpresa', v_empresa, 'nomeConta', v_nome,\n    'tipoConta', v_tipo, 'repetida', v_completed, 'contaCriada', v_created);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_concluir_onboarding(p_user_id integer, p_nome_empresa text, p_nome_conta text, p_tipo_conta text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'pg_temp'\nAS $function$\nDECLARE\n  v_empresa text;\n  v_nome text;\n  v_tipo text;\n  v_completed boolean;\n  v_empresa_salva text;\n  v_conta_id integer;\n  v_nome_salvo text;\n  v_tipo_salvo text;\n  v_created boolean := false;\n  v_user_confirmado integer;\n  v_conta_confirmada integer;\n  v_trim text := E' \\t\\n\\r\\f\\013' || U&'\\00A0\\1680\\2000\\2001\\2002\\2003\\2004\\2005\\2006\\2007\\2008\\2009\\200A\\2028\\2029\\202F\\205F\\3000\\FEFF';\nBEGIN\n  v_empresa := pg_catalog.btrim(p_nome_empresa, v_trim);\n  v_nome := pg_catalog.btrim(p_nome_conta, v_trim);\n  v_tipo := pg_catalog.btrim(p_tipo_conta, v_trim);\n  IF p_user_id IS NULL OR p_user_id <= 0\n     OR v_empresa IS NULL OR pg_catalog.char_length(v_empresa) NOT BETWEEN 1 AND 255\n     OR v_nome IS NULL OR pg_catalog.char_length(v_nome) NOT BETWEEN 1 AND 255\n     OR v_tipo IS NULL OR v_tipo NOT IN ('caixa','banco','digital') THEN\n    RAISE EXCEPTION 'Dados de onboarding inválidos' USING ERRCODE='22023';\n  END IF;\n\n  -- Serializa primeira conclusão e retries. Owner vem do servidor, não do formulário.\n  SELECT u.onboarding_completo, u.nome_empresa\n    INTO v_completed, v_empresa_salva\n    FROM public.users AS u WHERE u.id = p_user_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Usuário indisponível' USING ERRCODE='42501';\n  END IF;\n  IF v_completed AND v_empresa_salva IS DISTINCT FROM v_empresa THEN\n    RAISE EXCEPTION 'Onboarding já concluído com dados diferentes' USING ERRCODE='23505';\n  END IF;\n\n  SELECT c.id, c.nome, c.tipo INTO v_conta_id, v_nome_salvo, v_tipo_salvo\n    FROM public.contas_caixa AS c\n    WHERE c.user_id = p_user_id AND c.ativo = true\n    ORDER BY c.id LIMIT 1 FOR UPDATE;\n  IF FOUND THEN\n    -- Sem tabela de intenção: o preset precisa coincidir exatamente com a conta escolhida.\n    -- Nunca renomear/ativar/alterar saldo para fazer um replay parecer válido.\n    IF v_nome_salvo IS DISTINCT FROM v_nome OR v_tipo_salvo IS DISTINCT FROM v_tipo THEN\n      RAISE EXCEPTION 'Conta ativa incompatível com a intenção de onboarding' USING ERRCODE='23505';\n    END IF;\n  ELSE\n    IF v_completed THEN\n      RAISE EXCEPTION 'Onboarding concluído sem conta ativa; exige revisão explícita' USING ERRCODE='23505';\n    END IF;\n    -- Inativas permanecem intocadas. O resultado informa explicitamente a nova conta.\n    INSERT INTO public.contas_caixa (user_id, nome, tipo, saldo, ativo)\n      VALUES (p_user_id, v_nome, v_tipo, 0, true) RETURNING id INTO v_conta_id;\n    IF v_conta_id IS NULL OR v_conta_id <= 0 THEN\n      RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n    END IF;\n    v_created := true;\n  END IF;\n\n  -- Releitura detecta INSERT suprimido ou adulterado por triggers, inclusive AFTER.\n  SELECT c.id INTO v_conta_confirmada FROM public.contas_caixa AS c\n    WHERE c.id = v_conta_id AND c.id > 0 AND c.user_id = p_user_id\n      AND c.ativo = true AND c.nome = v_nome AND c.tipo = v_tipo\n      AND (NOT v_created OR c.saldo = 0) FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n  END IF;\n\n  IF NOT v_completed THEN\n    UPDATE public.users AS u\n      SET onboarding_completo = true, nome_empresa = v_empresa, \"updatedAt\" = pg_catalog.clock_timestamp()\n      WHERE u.id = p_user_id AND u.onboarding_completo = false\n      RETURNING u.id INTO v_user_confirmado;\n    IF v_user_confirmado IS DISTINCT FROM p_user_id THEN\n      RAISE EXCEPTION 'Usuário não confirmado' USING ERRCODE='23514';\n    END IF;\n  END IF;\n  SELECT u.id INTO v_user_confirmado FROM public.users AS u\n    WHERE u.id = p_user_id AND u.onboarding_completo = true AND u.nome_empresa = v_empresa;\n  IF NOT FOUND OR v_user_confirmado IS DISTINCT FROM p_user_id THEN\n    RAISE EXCEPTION 'Usuário não confirmado' USING ERRCODE='23514';\n  END IF;\n  -- Confirma também a conta depois do UPDATE de users (triggers podem ter efeitos laterais).\n  PERFORM c.id FROM public.contas_caixa AS c\n    WHERE c.id = v_conta_confirmada AND c.user_id = p_user_id AND c.ativo = true\n      AND c.nome = v_nome AND c.tipo = v_tipo AND (NOT v_created OR c.saldo = 0);\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Conta não confirmada' USING ERRCODE='23514';\n  END IF;\n  RETURN pg_catalog.jsonb_build_object(\n    'success', true, 'id', v_user_confirmado, 'conta_id', v_conta_confirmada,\n    'onboardingCompleto', true, 'nomeEmpresa', v_empresa, 'nomeConta', v_nome,\n    'tipoConta', v_tipo, 'repetida', v_completed, 'contaCriada', v_created);\nEND;\n$function$\n","config":["search_path=pg_catalog, pg_temp"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"c03e6dd33a495a5eb5b2491c74c9855c82a20c3b52dd2d8ceca57acd0be9aa37","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_concluir_onboarding(integer, text, text, text)","definition_sha256":"146a008d0a609ebaf676924e92ff0a85ce0dfb550929a1c7caf7908aae1efe83","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_blacklist_access","oid":31985,"args":"p_user_id integer","argtypes":"integer","prosrc":"\nDECLARE s record;\nBEGIN\n  IF p_user_id IS NULL OR p_user_id<=0 THEN\n    RAISE EXCEPTION 'Usuário inválido para gate Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Evaluate time on EVERY read. No cron, user role, manual/lifetime grant or legacy fallback.\n  SELECT k.subscription_id,k.user_id,k.product_id,k.last_paid_order_id,k.status,k.start_date,\n      k.has_access,k.active_period,k.access_until,k.financial_revoked,k.review_required INTO s\n    FROM public.kiwify_blacklist_subscriptions k\n    JOIN public.kiwify_blacklist_products p ON p.product_id=k.product_id AND p.enabled\n    JOIN public.users u ON u.id=k.user_id\n    WHERE k.user_id=p_user_id AND NOT k.financial_revoked AND NOT k.review_required\n      AND k.has_access AND k.active_period AND k.status IN ('active','canceled')\n      AND k.start_date<=clock_timestamp() AND isfinite(k.start_date) AND k.last_paid_order_id IS NOT NULL\n      AND k.access_until>clock_timestamp() AND isfinite(k.access_until)\n    ORDER BY k.access_until DESC,k.subscription_id LIMIT 1;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('eligible',false,'subscription_id',NULL,'user_id',NULL,'product_id',NULL,\n      'last_paid_order_id',NULL,'status',NULL,'start_date',NULL,'has_access',NULL,'active_period',NULL,\n      'access_until',NULL,'financial_revoked',NULL,'review_required',NULL);\n  END IF;\n  RETURN jsonb_build_object('eligible',true,'subscription_id',s.subscription_id,'user_id',s.user_id,\n    'product_id',s.product_id,'last_paid_order_id',s.last_paid_order_id,'status',s.status,\n    'start_date',to_char(s.start_date AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n    'has_access',s.has_access,'active_period',s.active_period,\n    'access_until',to_char(s.access_until AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n    'financial_revoked',s.financial_revoked,'review_required',s.review_required);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_blacklist_access(p_user_id integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE s record;\nBEGIN\n  IF p_user_id IS NULL OR p_user_id<=0 THEN\n    RAISE EXCEPTION 'Usuário inválido para gate Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Evaluate time on EVERY read. No cron, user role, manual/lifetime grant or legacy fallback.\n  SELECT k.subscription_id,k.user_id,k.product_id,k.last_paid_order_id,k.status,k.start_date,\n      k.has_access,k.active_period,k.access_until,k.financial_revoked,k.review_required INTO s\n    FROM public.kiwify_blacklist_subscriptions k\n    JOIN public.kiwify_blacklist_products p ON p.product_id=k.product_id AND p.enabled\n    JOIN public.users u ON u.id=k.user_id\n    WHERE k.user_id=p_user_id AND NOT k.financial_revoked AND NOT k.review_required\n      AND k.has_access AND k.active_period AND k.status IN ('active','canceled')\n      AND k.start_date<=clock_timestamp() AND isfinite(k.start_date) AND k.last_paid_order_id IS NOT NULL\n      AND k.access_until>clock_timestamp() AND isfinite(k.access_until)\n    ORDER BY k.access_until DESC,k.subscription_id LIMIT 1;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('eligible',false,'subscription_id',NULL,'user_id',NULL,'product_id',NULL,\n      'last_paid_order_id',NULL,'status',NULL,'start_date',NULL,'has_access',NULL,'active_period',NULL,\n      'access_until',NULL,'financial_revoked',NULL,'review_required',NULL);\n  END IF;\n  RETURN jsonb_build_object('eligible',true,'subscription_id',s.subscription_id,'user_id',s.user_id,\n    'product_id',s.product_id,'last_paid_order_id',s.last_paid_order_id,'status',s.status,\n    'start_date',to_char(s.start_date AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n    'has_access',s.has_access,'active_period',s.active_period,\n    'access_until',to_char(s.access_until AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n    'financial_revoked',s.financial_revoked,'review_required',s.review_required);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"722adf8671214f17bb526716165cc86b31529130176767905b7a208291948d6c","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_blacklist_access(integer)","definition_sha256":"079735cc956c5796e624fd6ba44f1203757702692cea611a5c8add12f54e448d","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_blacklist_consume","oid":31981,"args":"p_event jsonb","argtypes":"jsonb","prosrc":"\nDECLARE\n  v_order text; v_type text; v_fp text; v_sub text; v_user integer; v_product text; v_sale text;\n  v_status text; v_start timestamptz; v_until timestamptz; v_at timestamptz;\n  v_has boolean; v_active boolean; v_financial boolean; v_positive boolean;\n  v_now timestamptz := clock_timestamp(); v_value text; k text;\n  s public.kiwify_blacklist_subscriptions%ROWTYPE;\n  e public.kiwify_blacklist_events%ROWTYPE;\n  v_duplicate boolean := false; v_outcome text := 'observed_no_grant';\nBEGIN\n  -- Privileged DTO only: reject extra keys to avoid storing PII/secrets or frontend assertions.\n  IF jsonb_typeof(p_event) IS DISTINCT FROM 'object' OR pg_column_size(p_event)>8192\n     OR NOT p_event ?& ARRAY['event_fingerprint','order_id','event_type','subscription_id','user_id','product_id','verified_sale_status']\n     OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_event) x(key) WHERE x.key NOT IN\n       ('event_fingerprint','order_id','event_type','subscription_id','user_id','product_id','status','start_date','has_access','active_period','access_until','verified_sale_status','event_at')) THEN\n    RAISE EXCEPTION 'DTO Kiwify inválido/chaves não aprovadas' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','verified_sale_status'] LOOP\n    IF jsonb_typeof(p_event->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'Identidade Kiwify inválida' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_order:=p_event->>'order_id'; v_type:=p_event->>'event_type'; v_fp:=p_event->>'event_fingerprint';\n  v_sub:=p_event->>'subscription_id'; v_product:=p_event->>'product_id'; v_sale:=p_event->>'verified_sale_status';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_sub !~ '^[A-Za-z0-9_-]{1,128}$'\n     OR v_product !~ '^[A-Za-z0-9_-]{1,128}$' OR v_fp !~ '^[0-9a-f]{64}$'\n     OR jsonb_typeof(p_event->'user_id') IS DISTINCT FROM 'number'\n     OR (p_event->>'user_id') !~ '^[1-9][0-9]{0,9}$'\n     OR (p_event->>'user_id')::numeric > 2147483647\n     OR v_type NOT IN ('order_approved','subscription_renewed','subscription_canceled','subscription_late','order_refunded','chargeback','order_rejected','billet_created','pix_created')\n     OR v_sale NOT IN ('paid','waiting_payment','refused','refunded','chargedback') THEN\n    RAISE EXCEPTION 'Identidade/tipo/venda Kiwify inválidos' USING ERRCODE='22023';\n  END IF;\n  v_user:=(p_event->>'user_id')::integer;\n  v_financial:=v_type IN ('order_refunded','chargeback') OR v_sale IN ('refunded','chargedback');\n  -- Financial evidence MUST revoke even without/malformed customer_access or dates.\n  IF NOT v_financial THEN\n    v_status:=p_event->>'status';\n    IF v_status IS NOT NULL AND (jsonb_typeof(p_event->'status')<>'string' OR v_status NOT IN ('active','waiting_payment','canceled','ended')) THEN\n      RAISE EXCEPTION 'Status Kiwify inválido' USING ERRCODE='22023';\n    END IF;\n    FOREACH k IN ARRAY ARRAY['has_access','active_period'] LOOP\n      IF p_event ? k AND p_event->k <> 'null'::jsonb AND jsonb_typeof(p_event->k)<>'boolean' THEN\n        RAISE EXCEPTION 'Flag Kiwify inválida' USING ERRCODE='22023';\n      END IF;\n    END LOOP;\n    v_has:=(p_event->>'has_access')::boolean; v_active:=(p_event->>'active_period')::boolean;\n    FOREACH k IN ARRAY ARRAY['start_date','access_until','event_at'] LOOP\n      v_value:=p_event->>k;\n      IF v_value IS NOT NULL THEN\n        IF jsonb_typeof(p_event->k)<>'string' OR v_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z?$' THEN\n          RAISE EXCEPTION 'Data Kiwify deve ser UTC documentada' USING ERRCODE='22023';\n        END IF;\n        BEGIN\n          IF right(v_value,1)='Z' THEN v_value:=left(v_value,length(v_value)-1); END IF;\n          CASE k\n            WHEN 'start_date' THEN v_start:=v_value::timestamp AT TIME ZONE 'UTC';\n            WHEN 'access_until' THEN v_until:=v_value::timestamp AT TIME ZONE 'UTC';\n            WHEN 'event_at' THEN v_at:=v_value::timestamp AT TIME ZONE 'UTC';\n          END CASE;\n        EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN\n          RAISE EXCEPTION 'Data Kiwify inválida' USING ERRCODE='22023';\n        END;\n      END IF;\n    END LOOP;\n    IF v_at IS NULL OR NOT isfinite(v_at) OR v_at > v_now+interval '30 seconds'\n       OR (v_start IS NOT NULL AND NOT isfinite(v_start)) OR (v_until IS NOT NULL AND NOT isfinite(v_until)) THEN\n      RAISE EXCEPTION 'Timestamp do evento ausente/futuro/não finito' USING ERRCODE='22023';\n    END IF;\n  END IF;\n  -- Lock order first, subscription second: concurrent order reuse cannot cross identities.\n  PERFORM pg_advisory_xact_lock(hashtextextended('0027:order:'||v_order,27001));\n  PERFORM pg_advisory_xact_lock(hashtextextended('0027:subscription:'||v_sub,27002));\n  -- Product exists even if disabled; disabled product cannot grant, but MUST still revoke.\n  PERFORM 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Produto Kiwify não aprovado' USING ERRCODE='42501'; END IF;\n  PERFORM 1 FROM public.users WHERE id=v_user FOR KEY SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Usuário Kiwify indisponível' USING ERRCODE='42501'; END IF;\n  SELECT * INTO e FROM public.kiwify_blacklist_events WHERE order_id=v_order LIMIT 1;\n  IF FOUND AND (e.subscription_id<>v_sub OR e.user_id<>v_user OR e.product_id<>v_product) THEN\n    RAISE EXCEPTION 'Pedido Kiwify já vinculado a outra identidade' USING ERRCODE='23505';\n  END IF;\n  SELECT * INTO s FROM public.kiwify_blacklist_subscriptions WHERE subscription_id=v_sub FOR UPDATE;\n  IF FOUND AND (s.user_id<>v_user OR s.product_id<>v_product) THEN\n    RAISE EXCEPTION 'Assinatura Kiwify possui titular/produto imutáveis' USING ERRCODE='23505';\n  END IF;\n  IF NOT FOUND THEN\n    INSERT INTO public.kiwify_blacklist_subscriptions(subscription_id,user_id,product_id)\n      VALUES(v_sub,v_user,v_product) RETURNING * INTO s;\n  END IF;\n  SELECT * INTO e FROM public.kiwify_blacklist_events\n    WHERE order_id=v_order AND event_type=v_type AND event_fingerprint=v_fp;\n  v_duplicate:=FOUND;\n  v_positive:=v_type IN ('order_approved','subscription_renewed') AND v_sale='paid';\n  IF v_financial THEN\n    -- A replay whose API sale is NOW refunded must also revoke; original ledger row is never rewritten.\n    v_outcome:='financial_revoked';\n    IF NOT s.financial_revoked THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET financial_revoked=true,has_access=false,active_period=false,\n        updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  ELSIF s.financial_revoked THEN\n    v_outcome:='sticky_revocation';\n    IF v_positive AND NOT s.review_required THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET review_required=true,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  ELSIF v_duplicate THEN\n    v_outcome:=e.outcome;\n  ELSIF s.latest_event_at IS NOT NULL AND v_at<=s.latest_event_at THEN\n    v_outcome:='stale';\n  ELSE\n    -- Old paid order cannot extend again under a different event type/raw body or fabricated newer date.\n    IF v_positive AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_events\n        WHERE order_id=v_order AND outcome='paid_period') THEN\n      v_outcome:='same_paid_order';\n    ELSIF v_positive AND v_status IN ('active','canceled') AND v_has AND v_active\n        AND v_start IS NOT NULL AND v_start<=v_now AND v_until IS NOT NULL\n        AND v_until>v_now AND v_until>v_start AND v_until>v_at\n        -- Explicit safety ceiling: documented longest cycle is annual, not lifetime.\n        AND v_until<=v_at+interval '367 days'\n        AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled)\n        AND (s.access_until IS NULL OR v_until>s.access_until)\n        AND (s.start_date IS NULL OR s.start_date=v_start) THEN\n      v_outcome:='paid_period';\n      UPDATE public.kiwify_blacklist_subscriptions SET start_date=v_start,\n        access_until=CASE WHEN access_until IS NULL THEN v_until ELSE greatest(access_until,v_until) END,\n        last_paid_order_id=v_order,status=v_status,has_access=true,active_period=true,latest_event_at=v_at,\n        updated_at=v_now WHERE subscription_id=v_sub;\n    ELSE\n      -- Observation can close but NEVER reopen/extend a paid period. Canceled retains current paid flags.\n      UPDATE public.kiwify_blacklist_subscriptions SET status=coalesce(v_status,status),\n        has_access=has_access AND coalesce(v_has,true) AND coalesce(v_status NOT IN ('waiting_payment','ended'),true),\n        active_period=active_period AND coalesce(v_active,true) AND coalesce(v_status NOT IN ('waiting_payment','ended'),true),\n        latest_event_at=v_at,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n    IF v_outcome='same_paid_order' THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET latest_event_at=v_at,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  END IF;\n  IF NOT v_duplicate THEN\n    INSERT INTO public.kiwify_blacklist_events(order_id,event_type,event_fingerprint,subscription_id,user_id,product_id,\n      event_at,status,start_date,has_access,active_period,access_until,verified_sale_status,outcome)\n      VALUES(v_order,v_type,v_fp,v_sub,v_user,v_product,v_at,v_status,v_start,v_has,v_active,v_until,v_sale,v_outcome);\n  END IF;\n  SELECT * INTO STRICT s FROM public.kiwify_blacklist_subscriptions WHERE subscription_id=v_sub;\n  RETURN jsonb_build_object('accepted',true,'duplicate',v_duplicate,'outcome',v_outcome,'subscription_id',v_sub,\n    'eligible',NOT s.financial_revoked AND NOT s.review_required AND s.has_access AND s.active_period\n      AND coalesce(s.status IN ('active','canceled'),false) AND coalesce(s.access_until>clock_timestamp(),false)\n      AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled),\n    'access_until',CASE WHEN s.access_until IS NULL THEN NULL ELSE to_char(s.access_until AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"') END,\n    'financial_revoked',s.financial_revoked,'review_required',s.review_required);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_blacklist_consume(p_event jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  v_order text; v_type text; v_fp text; v_sub text; v_user integer; v_product text; v_sale text;\n  v_status text; v_start timestamptz; v_until timestamptz; v_at timestamptz;\n  v_has boolean; v_active boolean; v_financial boolean; v_positive boolean;\n  v_now timestamptz := clock_timestamp(); v_value text; k text;\n  s public.kiwify_blacklist_subscriptions%ROWTYPE;\n  e public.kiwify_blacklist_events%ROWTYPE;\n  v_duplicate boolean := false; v_outcome text := 'observed_no_grant';\nBEGIN\n  -- Privileged DTO only: reject extra keys to avoid storing PII/secrets or frontend assertions.\n  IF jsonb_typeof(p_event) IS DISTINCT FROM 'object' OR pg_column_size(p_event)>8192\n     OR NOT p_event ?& ARRAY['event_fingerprint','order_id','event_type','subscription_id','user_id','product_id','verified_sale_status']\n     OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_event) x(key) WHERE x.key NOT IN\n       ('event_fingerprint','order_id','event_type','subscription_id','user_id','product_id','status','start_date','has_access','active_period','access_until','verified_sale_status','event_at')) THEN\n    RAISE EXCEPTION 'DTO Kiwify inválido/chaves não aprovadas' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','verified_sale_status'] LOOP\n    IF jsonb_typeof(p_event->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'Identidade Kiwify inválida' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_order:=p_event->>'order_id'; v_type:=p_event->>'event_type'; v_fp:=p_event->>'event_fingerprint';\n  v_sub:=p_event->>'subscription_id'; v_product:=p_event->>'product_id'; v_sale:=p_event->>'verified_sale_status';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_sub !~ '^[A-Za-z0-9_-]{1,128}$'\n     OR v_product !~ '^[A-Za-z0-9_-]{1,128}$' OR v_fp !~ '^[0-9a-f]{64}$'\n     OR jsonb_typeof(p_event->'user_id') IS DISTINCT FROM 'number'\n     OR (p_event->>'user_id') !~ '^[1-9][0-9]{0,9}$'\n     OR (p_event->>'user_id')::numeric > 2147483647\n     OR v_type NOT IN ('order_approved','subscription_renewed','subscription_canceled','subscription_late','order_refunded','chargeback','order_rejected','billet_created','pix_created')\n     OR v_sale NOT IN ('paid','waiting_payment','refused','refunded','chargedback') THEN\n    RAISE EXCEPTION 'Identidade/tipo/venda Kiwify inválidos' USING ERRCODE='22023';\n  END IF;\n  v_user:=(p_event->>'user_id')::integer;\n  v_financial:=v_type IN ('order_refunded','chargeback') OR v_sale IN ('refunded','chargedback');\n  -- Financial evidence MUST revoke even without/malformed customer_access or dates.\n  IF NOT v_financial THEN\n    v_status:=p_event->>'status';\n    IF v_status IS NOT NULL AND (jsonb_typeof(p_event->'status')<>'string' OR v_status NOT IN ('active','waiting_payment','canceled','ended')) THEN\n      RAISE EXCEPTION 'Status Kiwify inválido' USING ERRCODE='22023';\n    END IF;\n    FOREACH k IN ARRAY ARRAY['has_access','active_period'] LOOP\n      IF p_event ? k AND p_event->k <> 'null'::jsonb AND jsonb_typeof(p_event->k)<>'boolean' THEN\n        RAISE EXCEPTION 'Flag Kiwify inválida' USING ERRCODE='22023';\n      END IF;\n    END LOOP;\n    v_has:=(p_event->>'has_access')::boolean; v_active:=(p_event->>'active_period')::boolean;\n    FOREACH k IN ARRAY ARRAY['start_date','access_until','event_at'] LOOP\n      v_value:=p_event->>k;\n      IF v_value IS NOT NULL THEN\n        IF jsonb_typeof(p_event->k)<>'string' OR v_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z?$' THEN\n          RAISE EXCEPTION 'Data Kiwify deve ser UTC documentada' USING ERRCODE='22023';\n        END IF;\n        BEGIN\n          IF right(v_value,1)='Z' THEN v_value:=left(v_value,length(v_value)-1); END IF;\n          CASE k\n            WHEN 'start_date' THEN v_start:=v_value::timestamp AT TIME ZONE 'UTC';\n            WHEN 'access_until' THEN v_until:=v_value::timestamp AT TIME ZONE 'UTC';\n            WHEN 'event_at' THEN v_at:=v_value::timestamp AT TIME ZONE 'UTC';\n          END CASE;\n        EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN\n          RAISE EXCEPTION 'Data Kiwify inválida' USING ERRCODE='22023';\n        END;\n      END IF;\n    END LOOP;\n    IF v_at IS NULL OR NOT isfinite(v_at) OR v_at > v_now+interval '30 seconds'\n       OR (v_start IS NOT NULL AND NOT isfinite(v_start)) OR (v_until IS NOT NULL AND NOT isfinite(v_until)) THEN\n      RAISE EXCEPTION 'Timestamp do evento ausente/futuro/não finito' USING ERRCODE='22023';\n    END IF;\n  END IF;\n  -- Lock order first, subscription second: concurrent order reuse cannot cross identities.\n  PERFORM pg_advisory_xact_lock(hashtextextended('0027:order:'||v_order,27001));\n  PERFORM pg_advisory_xact_lock(hashtextextended('0027:subscription:'||v_sub,27002));\n  -- Product exists even if disabled; disabled product cannot grant, but MUST still revoke.\n  PERFORM 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Produto Kiwify não aprovado' USING ERRCODE='42501'; END IF;\n  PERFORM 1 FROM public.users WHERE id=v_user FOR KEY SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Usuário Kiwify indisponível' USING ERRCODE='42501'; END IF;\n  SELECT * INTO e FROM public.kiwify_blacklist_events WHERE order_id=v_order LIMIT 1;\n  IF FOUND AND (e.subscription_id<>v_sub OR e.user_id<>v_user OR e.product_id<>v_product) THEN\n    RAISE EXCEPTION 'Pedido Kiwify já vinculado a outra identidade' USING ERRCODE='23505';\n  END IF;\n  SELECT * INTO s FROM public.kiwify_blacklist_subscriptions WHERE subscription_id=v_sub FOR UPDATE;\n  IF FOUND AND (s.user_id<>v_user OR s.product_id<>v_product) THEN\n    RAISE EXCEPTION 'Assinatura Kiwify possui titular/produto imutáveis' USING ERRCODE='23505';\n  END IF;\n  IF NOT FOUND THEN\n    INSERT INTO public.kiwify_blacklist_subscriptions(subscription_id,user_id,product_id)\n      VALUES(v_sub,v_user,v_product) RETURNING * INTO s;\n  END IF;\n  SELECT * INTO e FROM public.kiwify_blacklist_events\n    WHERE order_id=v_order AND event_type=v_type AND event_fingerprint=v_fp;\n  v_duplicate:=FOUND;\n  v_positive:=v_type IN ('order_approved','subscription_renewed') AND v_sale='paid';\n  IF v_financial THEN\n    -- A replay whose API sale is NOW refunded must also revoke; original ledger row is never rewritten.\n    v_outcome:='financial_revoked';\n    IF NOT s.financial_revoked THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET financial_revoked=true,has_access=false,active_period=false,\n        updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  ELSIF s.financial_revoked THEN\n    v_outcome:='sticky_revocation';\n    IF v_positive AND NOT s.review_required THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET review_required=true,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  ELSIF v_duplicate THEN\n    v_outcome:=e.outcome;\n  ELSIF s.latest_event_at IS NOT NULL AND v_at<=s.latest_event_at THEN\n    v_outcome:='stale';\n  ELSE\n    -- Old paid order cannot extend again under a different event type/raw body or fabricated newer date.\n    IF v_positive AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_events\n        WHERE order_id=v_order AND outcome='paid_period') THEN\n      v_outcome:='same_paid_order';\n    ELSIF v_positive AND v_status IN ('active','canceled') AND v_has AND v_active\n        AND v_start IS NOT NULL AND v_start<=v_now AND v_until IS NOT NULL\n        AND v_until>v_now AND v_until>v_start AND v_until>v_at\n        -- Explicit safety ceiling: documented longest cycle is annual, not lifetime.\n        AND v_until<=v_at+interval '367 days'\n        AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled)\n        AND (s.access_until IS NULL OR v_until>s.access_until)\n        AND (s.start_date IS NULL OR s.start_date=v_start) THEN\n      v_outcome:='paid_period';\n      UPDATE public.kiwify_blacklist_subscriptions SET start_date=v_start,\n        access_until=CASE WHEN access_until IS NULL THEN v_until ELSE greatest(access_until,v_until) END,\n        last_paid_order_id=v_order,status=v_status,has_access=true,active_period=true,latest_event_at=v_at,\n        updated_at=v_now WHERE subscription_id=v_sub;\n    ELSE\n      -- Observation can close but NEVER reopen/extend a paid period. Canceled retains current paid flags.\n      UPDATE public.kiwify_blacklist_subscriptions SET status=coalesce(v_status,status),\n        has_access=has_access AND coalesce(v_has,true) AND coalesce(v_status NOT IN ('waiting_payment','ended'),true),\n        active_period=active_period AND coalesce(v_active,true) AND coalesce(v_status NOT IN ('waiting_payment','ended'),true),\n        latest_event_at=v_at,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n    IF v_outcome='same_paid_order' THEN\n      UPDATE public.kiwify_blacklist_subscriptions SET latest_event_at=v_at,updated_at=v_now WHERE subscription_id=v_sub;\n    END IF;\n  END IF;\n  IF NOT v_duplicate THEN\n    INSERT INTO public.kiwify_blacklist_events(order_id,event_type,event_fingerprint,subscription_id,user_id,product_id,\n      event_at,status,start_date,has_access,active_period,access_until,verified_sale_status,outcome)\n      VALUES(v_order,v_type,v_fp,v_sub,v_user,v_product,v_at,v_status,v_start,v_has,v_active,v_until,v_sale,v_outcome);\n  END IF;\n  SELECT * INTO STRICT s FROM public.kiwify_blacklist_subscriptions WHERE subscription_id=v_sub;\n  RETURN jsonb_build_object('accepted',true,'duplicate',v_duplicate,'outcome',v_outcome,'subscription_id',v_sub,\n    'eligible',NOT s.financial_revoked AND NOT s.review_required AND s.has_access AND s.active_period\n      AND coalesce(s.status IN ('active','canceled'),false) AND coalesce(s.access_until>clock_timestamp(),false)\n      AND EXISTS(SELECT 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled),\n    'access_until',CASE WHEN s.access_until IS NULL THEN NULL ELSE to_char(s.access_until AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"') END,\n    'financial_revoked',s.financial_revoked,'review_required',s.review_required);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"bc3323053a8a5b8822d41e20176093079d92c00d996e17e7170dfc5f9370c2ac","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_blacklist_consume(jsonb)","definition_sha256":"9a0ee6d999aff9f85b7da3eaab9c30840bde40820d59890e4e7752872b019dc9","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_blacklist_find_users","oid":31987,"args":"p_email text","argtypes":"text","prosrc":"\nDECLARE v_email text;\nBEGIN\n  IF p_email IS NULL OR octet_length(p_email)>8192 THEN\n    RAISE EXCEPTION 'Email inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  v_email:=lower(btrim(p_email));\n  IF length(v_email) NOT BETWEEN 3 AND 320 OR v_email ~ '[[:space:][:cntrl:]]'\n     OR v_email !~ '^[^@]+@[^@.]+(\\.[^@.]+)+$' THEN\n    RAISE EXCEPTION 'Email inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Server-only users PII, not ledger. Keep two candidates: ambiguity MUST deny in backend.\n  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'email',u.email) ORDER BY u.id)\n    FROM (SELECT id,email FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u),'[]'::jsonb);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_blacklist_find_users(p_email text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE v_email text;\nBEGIN\n  IF p_email IS NULL OR octet_length(p_email)>8192 THEN\n    RAISE EXCEPTION 'Email inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  v_email:=lower(btrim(p_email));\n  IF length(v_email) NOT BETWEEN 3 AND 320 OR v_email ~ '[[:space:][:cntrl:]]'\n     OR v_email !~ '^[^@]+@[^@.]+(\\.[^@.]+)+$' THEN\n    RAISE EXCEPTION 'Email inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Server-only users PII, not ledger. Keep two candidates: ambiguity MUST deny in backend.\n  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'email',u.email) ORDER BY u.id)\n    FROM (SELECT id,email FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u),'[]'::jsonb);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"98e4f27297ed4275c9c223261a53326ab8c0d16f1ec6a545c4c2117ed8edc3fe","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_blacklist_find_users(text)","definition_sha256":"d0a8806126e40094158a22a0fa8286fb4992f63d60304e389a310f459680d94a","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_blacklist_order_binding","oid":31986,"args":"p_order_id text","argtypes":"text","prosrc":"\nDECLARE s record;\nBEGIN\n  IF p_order_id IS NULL OR p_order_id !~ '^[A-Za-z0-9_-]{1,128}$' THEN\n    RAISE EXCEPTION 'Pedido inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Existing immutable order identity only. Never infer by email/product/current eligibility.\n  SELECT e.subscription_id,e.user_id,e.product_id INTO s\n    FROM public.kiwify_blacklist_events e\n    JOIN public.kiwify_blacklist_subscriptions k ON k.subscription_id=e.subscription_id\n      AND k.user_id=e.user_id AND k.product_id=e.product_id\n    WHERE e.order_id=p_order_id AND NOT EXISTS(\n      SELECT 1 FROM public.kiwify_blacklist_events other WHERE other.order_id=e.order_id\n        AND (other.subscription_id<>e.subscription_id OR other.user_id<>e.user_id OR other.product_id<>e.product_id))\n    ORDER BY e.event_type,e.event_fingerprint LIMIT 1;\n  IF NOT FOUND THEN RETURN NULL; END IF;\n  RETURN jsonb_build_object('subscription_id',s.subscription_id,'user_id',s.user_id,'product_id',s.product_id);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_blacklist_order_binding(p_order_id text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE s record;\nBEGIN\n  IF p_order_id IS NULL OR p_order_id !~ '^[A-Za-z0-9_-]{1,128}$' THEN\n    RAISE EXCEPTION 'Pedido inválido para reader Kiwify' USING ERRCODE='22023';\n  END IF;\n  -- Existing immutable order identity only. Never infer by email/product/current eligibility.\n  SELECT e.subscription_id,e.user_id,e.product_id INTO s\n    FROM public.kiwify_blacklist_events e\n    JOIN public.kiwify_blacklist_subscriptions k ON k.subscription_id=e.subscription_id\n      AND k.user_id=e.user_id AND k.product_id=e.product_id\n    WHERE e.order_id=p_order_id AND NOT EXISTS(\n      SELECT 1 FROM public.kiwify_blacklist_events other WHERE other.order_id=e.order_id\n        AND (other.subscription_id<>e.subscription_id OR other.user_id<>e.user_id OR other.product_id<>e.product_id))\n    ORDER BY e.event_type,e.event_fingerprint LIMIT 1;\n  IF NOT FOUND THEN RETURN NULL; END IF;\n  RETURN jsonb_build_object('subscription_id',s.subscription_id,'user_id',s.user_id,'product_id',s.product_id);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"ce31a020d6dc6e65ce50bd3176b7dbd7e132bf41cd47081630a07dbccf4f1fdd","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_blacklist_order_binding(text)","definition_sha256":"85bdde3d39104a05e9e1a355dfecf9767530a7d073f99462c0cd11541a3669f5","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_buyer_invite_claim","oid":32085,"args":"p_claim jsonb","argtypes":"jsonb","prosrc":"\nDECLARE b public.kiwify_buyers%ROWTYPE; v_email text; v_order text; v_token text; matches integer[];\nBEGIN\n  IF jsonb_typeof(p_claim) IS DISTINCT FROM 'object' OR pg_column_size(p_claim)>2048\n    OR NOT p_claim ?& ARRAY['order_id','email','token_hash'] OR (SELECT count(*) FROM jsonb_object_keys(p_claim))<>3\n    OR jsonb_typeof(p_claim->'order_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_claim->'email') IS DISTINCT FROM 'string'\n    OR jsonb_typeof(p_claim->'token_hash') IS DISTINCT FROM 'string' THEN\n    RAISE EXCEPTION 'DTO claim inválido' USING ERRCODE='22023';\n  END IF;\n  v_order:=p_claim->>'order_id'; v_email:=p_claim->>'email'; v_token:=p_claim->>'token_hash';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_token !~ '^[0-9a-f]{64}$' THEN\n    RAISE EXCEPTION 'DTO claim inválido' USING ERRCODE='22023';\n  END IF;\n  PERFORM set_config('lock_timeout','5s',true);\n  LOCK TABLE public.users IN SHARE ROW EXCLUSIVE MODE;\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=v_order FOR UPDATE;\n  SELECT array_agg(id) INTO matches FROM\n    (SELECT id FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u;\n  IF b.order_id IS NULL OR b.email<>v_email OR cardinality(matches) IS DISTINCT FROM 1 OR matches[1]<>b.user_id THEN\n    RAISE EXCEPTION 'Convite/titular divergentes' USING ERRCODE='23505';\n  END IF;\n  IF b.invite_state NOT IN ('pending','retryable') OR NOT b.created_user THEN\n    RETURN jsonb_build_object('claimed',false,'user_id',b.user_id,'invite_state',b.invite_state);\n  END IF;\n  PERFORM 1 FROM public.kiwify_blacklist_subscriptions s JOIN public.kiwify_blacklist_products p ON p.product_id=s.product_id\n    WHERE s.subscription_id=b.subscription_id AND s.user_id=b.user_id AND s.product_id=b.product_id\n      AND p.enabled AND NOT s.financial_revoked AND NOT s.review_required\n      AND s.has_access AND s.active_period AND s.status IN ('active','canceled') AND s.access_until>clock_timestamp() FOR SHARE OF s,p;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Convite sem período vigente' USING ERRCODE='42501'; END IF;\n  IF v_token IS NOT DISTINCT FROM b.token_hash THEN RAISE EXCEPTION 'Token repetido' USING ERRCODE='22023'; END IF;\n  -- A known failed POST permits a NEW token, not a second user. Revoke only the\n  -- old invitation token, never another reset or the user's password/session.\n  IF b.token_hash IS NOT NULL THEN\n    UPDATE public.password_resets SET used=true WHERE user_id=b.user_id AND token=b.token_hash AND NOT used;\n  END IF;\n  INSERT INTO public.password_resets(user_id,token,expires_at,used)\n    VALUES(b.user_id,v_token,clock_timestamp()+interval '1 hour',false);\n  UPDATE public.kiwify_buyers SET invite_state='sending',token_hash=v_token,updated_at=clock_timestamp() WHERE order_id=v_order;\n  RETURN jsonb_build_object('claimed',true,'user_id',b.user_id,'invite_state','sending');\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_buyer_invite_claim(p_claim jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE b public.kiwify_buyers%ROWTYPE; v_email text; v_order text; v_token text; matches integer[];\nBEGIN\n  IF jsonb_typeof(p_claim) IS DISTINCT FROM 'object' OR pg_column_size(p_claim)>2048\n    OR NOT p_claim ?& ARRAY['order_id','email','token_hash'] OR (SELECT count(*) FROM jsonb_object_keys(p_claim))<>3\n    OR jsonb_typeof(p_claim->'order_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_claim->'email') IS DISTINCT FROM 'string'\n    OR jsonb_typeof(p_claim->'token_hash') IS DISTINCT FROM 'string' THEN\n    RAISE EXCEPTION 'DTO claim inválido' USING ERRCODE='22023';\n  END IF;\n  v_order:=p_claim->>'order_id'; v_email:=p_claim->>'email'; v_token:=p_claim->>'token_hash';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_token !~ '^[0-9a-f]{64}$' THEN\n    RAISE EXCEPTION 'DTO claim inválido' USING ERRCODE='22023';\n  END IF;\n  PERFORM set_config('lock_timeout','5s',true);\n  LOCK TABLE public.users IN SHARE ROW EXCLUSIVE MODE;\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=v_order FOR UPDATE;\n  SELECT array_agg(id) INTO matches FROM\n    (SELECT id FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u;\n  IF b.order_id IS NULL OR b.email<>v_email OR cardinality(matches) IS DISTINCT FROM 1 OR matches[1]<>b.user_id THEN\n    RAISE EXCEPTION 'Convite/titular divergentes' USING ERRCODE='23505';\n  END IF;\n  IF b.invite_state NOT IN ('pending','retryable') OR NOT b.created_user THEN\n    RETURN jsonb_build_object('claimed',false,'user_id',b.user_id,'invite_state',b.invite_state);\n  END IF;\n  PERFORM 1 FROM public.kiwify_blacklist_subscriptions s JOIN public.kiwify_blacklist_products p ON p.product_id=s.product_id\n    WHERE s.subscription_id=b.subscription_id AND s.user_id=b.user_id AND s.product_id=b.product_id\n      AND p.enabled AND NOT s.financial_revoked AND NOT s.review_required\n      AND s.has_access AND s.active_period AND s.status IN ('active','canceled') AND s.access_until>clock_timestamp() FOR SHARE OF s,p;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Convite sem período vigente' USING ERRCODE='42501'; END IF;\n  IF v_token IS NOT DISTINCT FROM b.token_hash THEN RAISE EXCEPTION 'Token repetido' USING ERRCODE='22023'; END IF;\n  -- A known failed POST permits a NEW token, not a second user. Revoke only the\n  -- old invitation token, never another reset or the user's password/session.\n  IF b.token_hash IS NOT NULL THEN\n    UPDATE public.password_resets SET used=true WHERE user_id=b.user_id AND token=b.token_hash AND NOT used;\n  END IF;\n  INSERT INTO public.password_resets(user_id,token,expires_at,used)\n    VALUES(b.user_id,v_token,clock_timestamp()+interval '1 hour',false);\n  UPDATE public.kiwify_buyers SET invite_state='sending',token_hash=v_token,updated_at=clock_timestamp() WHERE order_id=v_order;\n  RETURN jsonb_build_object('claimed',true,'user_id',b.user_id,'invite_state','sending');\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"4438d362a6cadd79b0b280355049f26b69e62d17b59008175f76696378b6e096","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_buyer_invite_claim(jsonb)","definition_sha256":"4eded20d7737a5ce3e0b8e9e2a6659eba13272809a4e9e1a78619e8aa53e53e5","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_buyer_invite_finish","oid":32086,"args":"p_result jsonb","argtypes":"jsonb","prosrc":"\nDECLARE b public.kiwify_buyers%ROWTYPE; v_state text;\nBEGIN\n  IF jsonb_typeof(p_result) IS DISTINCT FROM 'object' OR pg_column_size(p_result)>2048\n    OR NOT p_result ?& ARRAY['order_id','email','token_hash','state'] OR (SELECT count(*) FROM jsonb_object_keys(p_result))<>4\n    OR jsonb_typeof(p_result->'order_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_result->'email') IS DISTINCT FROM 'string'\n    OR jsonb_typeof(p_result->'token_hash') IS DISTINCT FROM 'string' OR jsonb_typeof(p_result->'state') IS DISTINCT FROM 'string'\n    OR (p_result->>'order_id') !~ '^[A-Za-z0-9_-]{1,128}$' OR (p_result->>'token_hash') !~ '^[0-9a-f]{64}$'\n    OR (p_result->>'state') NOT IN ('accepted','retryable','unknown','blocked') THEN\n    RAISE EXCEPTION 'DTO resultado inválido' USING ERRCODE='22023';\n  END IF;\n  v_state:=p_result->>'state';\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=p_result->>'order_id' FOR UPDATE;\n  IF b.order_id IS NULL OR b.email<>p_result->>'email' OR b.token_hash IS DISTINCT FROM p_result->>'token_hash'\n    OR NOT b.created_user THEN RAISE EXCEPTION 'Resultado/titular divergentes' USING ERRCODE='23505'; END IF;\n  IF b.invite_state='sending' THEN\n    UPDATE public.kiwify_buyers SET invite_state=v_state,updated_at=clock_timestamp() WHERE order_id=b.order_id;\n  ELSIF b.invite_state<>v_state THEN\n    RAISE EXCEPTION 'Resultado CAS divergente' USING ERRCODE='23505';\n  END IF;\n  RETURN jsonb_build_object('finished',true,'invite_state',v_state);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_buyer_invite_finish(p_result jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE b public.kiwify_buyers%ROWTYPE; v_state text;\nBEGIN\n  IF jsonb_typeof(p_result) IS DISTINCT FROM 'object' OR pg_column_size(p_result)>2048\n    OR NOT p_result ?& ARRAY['order_id','email','token_hash','state'] OR (SELECT count(*) FROM jsonb_object_keys(p_result))<>4\n    OR jsonb_typeof(p_result->'order_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_result->'email') IS DISTINCT FROM 'string'\n    OR jsonb_typeof(p_result->'token_hash') IS DISTINCT FROM 'string' OR jsonb_typeof(p_result->'state') IS DISTINCT FROM 'string'\n    OR (p_result->>'order_id') !~ '^[A-Za-z0-9_-]{1,128}$' OR (p_result->>'token_hash') !~ '^[0-9a-f]{64}$'\n    OR (p_result->>'state') NOT IN ('accepted','retryable','unknown','blocked') THEN\n    RAISE EXCEPTION 'DTO resultado inválido' USING ERRCODE='22023';\n  END IF;\n  v_state:=p_result->>'state';\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=p_result->>'order_id' FOR UPDATE;\n  IF b.order_id IS NULL OR b.email<>p_result->>'email' OR b.token_hash IS DISTINCT FROM p_result->>'token_hash'\n    OR NOT b.created_user THEN RAISE EXCEPTION 'Resultado/titular divergentes' USING ERRCODE='23505'; END IF;\n  IF b.invite_state='sending' THEN\n    UPDATE public.kiwify_buyers SET invite_state=v_state,updated_at=clock_timestamp() WHERE order_id=b.order_id;\n  ELSIF b.invite_state<>v_state THEN\n    RAISE EXCEPTION 'Resultado CAS divergente' USING ERRCODE='23505';\n  END IF;\n  RETURN jsonb_build_object('finished',true,'invite_state',v_state);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"0dbe734de60744b1d072e174b1dbe082d227ceea38294821b16a4eef37e3c3d8","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_buyer_invite_finish(jsonb)","definition_sha256":"e47cf2c9d4c5e774e0470b2e516983d21ac8f6dad07407fc7005703c29374bed","language":"plpgsql"},{"schema":"public","name":"rpc_kiwify_buyer_provision","oid":32081,"args":"p_buyer jsonb","argtypes":"jsonb","prosrc":"\nDECLARE\n  e jsonb; v_email text; v_hash text; v_open text; k text; v_order text; v_sub text; v_product text;\n  v_start timestamptz; v_until timestamptz; v_at timestamptz; v_now timestamptz := clock_timestamp();\n  v_user integer; matches integer[]; created boolean := false; b public.kiwify_buyers%ROWTYPE; receipt jsonb;\nBEGIN\n  IF jsonb_typeof(p_buyer) IS DISTINCT FROM 'object' OR pg_column_size(p_buyer)>8192\n    OR NOT p_buyer ?& ARRAY['email','password_hash','open_id','event']\n    OR (SELECT count(*) FROM jsonb_object_keys(p_buyer))<>4 THEN\n    RAISE EXCEPTION 'DTO comprador inválido' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['email','password_hash','open_id'] LOOP\n    IF jsonb_typeof(p_buyer->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'DTO comprador inválido' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_email:=lower(btrim(p_buyer->>'email')); v_hash:=p_buyer->>'password_hash'; v_open:=p_buyer->>'open_id';\n  IF length(v_email) NOT BETWEEN 3 AND 320 OR v_email ~ '[[:space:][:cntrl:]]'\n    OR v_email !~ '^[^@]+@[^@.]+(\\.[^@.]+)+$'\n    OR v_hash !~ '^\\$2[aby]\\$12\\$[./A-Za-z0-9]{53}$'\n    OR v_open !~ '^kiwify_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN\n    RAISE EXCEPTION 'Identidade/hash comprador inválidos' USING ERRCODE='22023';\n  END IF;\n  e:=p_buyer->'event';\n  IF jsonb_typeof(e) IS DISTINCT FROM 'object'\n    OR NOT e ?& ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','status','start_date','has_access','active_period','access_until','verified_sale_status','event_at']\n    OR (SELECT count(*) FROM jsonb_object_keys(e))<>12 THEN\n    RAISE EXCEPTION 'DTO paid_period inválido' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','status','start_date','access_until','verified_sale_status','event_at'] LOOP\n    IF jsonb_typeof(e->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'DTO paid_period inválido' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_order:=e->>'order_id'; v_sub:=e->>'subscription_id'; v_product:=e->>'product_id';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_sub !~ '^[A-Za-z0-9_-]{1,128}$'\n    OR v_product !~ '^[A-Za-z0-9_-]{1,128}$' OR (e->>'event_fingerprint') !~ '^[0-9a-f]{64}$'\n    OR (e->>'event_type') NOT IN ('order_approved','subscription_renewed')\n    OR (e->>'verified_sale_status')<>'paid' OR (e->>'status') NOT IN ('active','canceled')\n    OR e->'has_access' IS DISTINCT FROM 'true'::jsonb OR e->'active_period' IS DISTINCT FROM 'true'::jsonb THEN\n    RAISE EXCEPTION 'Somente paid_period pode provisionar' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['start_date','access_until','event_at'] LOOP\n    IF (e->>k) !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$' THEN\n      RAISE EXCEPTION 'Data UTC inválida' USING ERRCODE='22023';\n    END IF;\n    IF left(e->>k,19)<>to_char((e->>k)::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS')\n      OR left(e->>k,4)::integer<1970 THEN\n      RAISE EXCEPTION 'Data UTC com rollover inválida' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_start:=(e->>'start_date')::timestamptz; v_until:=(e->>'access_until')::timestamptz; v_at:=(e->>'event_at')::timestamptz;\n  IF NOT isfinite(v_start) OR NOT isfinite(v_until) OR NOT isfinite(v_at)\n    OR v_start>v_now OR v_until<=v_now OR v_until<=v_start OR v_until<=v_at\n    OR v_until>v_at+interval '367 days' OR v_at>v_now+interval '30 seconds' THEN\n    RAISE EXCEPTION 'Período pago completo inválido' USING ERRCODE='22023';\n  END IF;\n  PERFORM set_config('lock_timeout','5s',true);\n  -- Short critical section excludes concurrent REST INSERT/UPDATE/DELETE until\n  -- lookup+create+binding+ledger commit. No slow bcrypt/API/email inside SQL.\n  LOCK TABLE public.users IN SHARE ROW EXCLUSIVE MODE;\n  PERFORM 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não habilitado' USING ERRCODE='42501'; END IF;\n  SELECT array_agg(id ORDER BY id) INTO matches FROM\n    (SELECT id FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u;\n  IF coalesce(cardinality(matches),0)>1 THEN\n    RAISE EXCEPTION 'Email ambíguo' USING ERRCODE='23505';\n  END IF;\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=v_order FOR UPDATE;\n  IF FOUND THEN\n    IF b.email<>v_email OR b.subscription_id<>v_sub OR b.product_id<>v_product\n      OR cardinality(matches) IS DISTINCT FROM 1 OR matches[1]<>b.user_id THEN\n      RAISE EXCEPTION 'Pedido/titular divergentes' USING ERRCODE='23505';\n    END IF;\n    v_user:=b.user_id; created:=b.created_user;\n  ELSE\n    IF coalesce(cardinality(matches),0)=1 THEN v_user:=matches[1];\n    ELSE\n      INSERT INTO public.users(\"openId\",name,email,\"passwordHash\",\"loginMethod\",role)\n        VALUES(v_open,'Cliente CobraPro',v_email,v_hash,'kiwify','user') RETURNING id INTO v_user;\n      created:=true;\n    END IF;\n  END IF;\n  -- 0027 independently rechecks immutable subscription/order identity, sticky\n  -- refund and full period. Any failure rolls back the brand-new user too.\n  receipt:=public.rpc_kiwify_blacklist_consume(e||jsonb_build_object('user_id',v_user));\n  IF receipt->'accepted' IS DISTINCT FROM 'true'::jsonb THEN\n    RAISE EXCEPTION 'Ledger indisponível' USING ERRCODE='23514';\n  END IF;\n  IF b.order_id IS NULL THEN\n    IF created AND (receipt->>'outcome'<>'paid_period' OR receipt->'eligible' IS DISTINCT FROM 'true'::jsonb) THEN\n      RAISE EXCEPTION 'Novo comprador sem período pago aprovado' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.kiwify_buyers(order_id,subscription_id,product_id,user_id,email,created_user,invite_state)\n      VALUES(v_order,v_sub,v_product,v_user,v_email,created,CASE WHEN created THEN 'pending' ELSE 'not_needed' END)\n      RETURNING * INTO b;\n  END IF;\n  RETURN jsonb_build_object('user_id',v_user,'email',v_email,'created',created,\n    'applied',NOT (receipt->>'duplicate')::boolean OR receipt->>'outcome' IN ('financial_revoked','sticky_revocation'),\n    'invite_state',b.invite_state);\nEND;\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION public.rpc_kiwify_buyer_provision(p_buyer jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  e jsonb; v_email text; v_hash text; v_open text; k text; v_order text; v_sub text; v_product text;\n  v_start timestamptz; v_until timestamptz; v_at timestamptz; v_now timestamptz := clock_timestamp();\n  v_user integer; matches integer[]; created boolean := false; b public.kiwify_buyers%ROWTYPE; receipt jsonb;\nBEGIN\n  IF jsonb_typeof(p_buyer) IS DISTINCT FROM 'object' OR pg_column_size(p_buyer)>8192\n    OR NOT p_buyer ?& ARRAY['email','password_hash','open_id','event']\n    OR (SELECT count(*) FROM jsonb_object_keys(p_buyer))<>4 THEN\n    RAISE EXCEPTION 'DTO comprador inválido' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['email','password_hash','open_id'] LOOP\n    IF jsonb_typeof(p_buyer->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'DTO comprador inválido' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_email:=lower(btrim(p_buyer->>'email')); v_hash:=p_buyer->>'password_hash'; v_open:=p_buyer->>'open_id';\n  IF length(v_email) NOT BETWEEN 3 AND 320 OR v_email ~ '[[:space:][:cntrl:]]'\n    OR v_email !~ '^[^@]+@[^@.]+(\\.[^@.]+)+$'\n    OR v_hash !~ '^\\$2[aby]\\$12\\$[./A-Za-z0-9]{53}$'\n    OR v_open !~ '^kiwify_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN\n    RAISE EXCEPTION 'Identidade/hash comprador inválidos' USING ERRCODE='22023';\n  END IF;\n  e:=p_buyer->'event';\n  IF jsonb_typeof(e) IS DISTINCT FROM 'object'\n    OR NOT e ?& ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','status','start_date','has_access','active_period','access_until','verified_sale_status','event_at']\n    OR (SELECT count(*) FROM jsonb_object_keys(e))<>12 THEN\n    RAISE EXCEPTION 'DTO paid_period inválido' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['event_fingerprint','order_id','event_type','subscription_id','product_id','status','start_date','access_until','verified_sale_status','event_at'] LOOP\n    IF jsonb_typeof(e->k) IS DISTINCT FROM 'string' THEN\n      RAISE EXCEPTION 'DTO paid_period inválido' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_order:=e->>'order_id'; v_sub:=e->>'subscription_id'; v_product:=e->>'product_id';\n  IF v_order !~ '^[A-Za-z0-9_-]{1,128}$' OR v_sub !~ '^[A-Za-z0-9_-]{1,128}$'\n    OR v_product !~ '^[A-Za-z0-9_-]{1,128}$' OR (e->>'event_fingerprint') !~ '^[0-9a-f]{64}$'\n    OR (e->>'event_type') NOT IN ('order_approved','subscription_renewed')\n    OR (e->>'verified_sale_status')<>'paid' OR (e->>'status') NOT IN ('active','canceled')\n    OR e->'has_access' IS DISTINCT FROM 'true'::jsonb OR e->'active_period' IS DISTINCT FROM 'true'::jsonb THEN\n    RAISE EXCEPTION 'Somente paid_period pode provisionar' USING ERRCODE='22023';\n  END IF;\n  FOREACH k IN ARRAY ARRAY['start_date','access_until','event_at'] LOOP\n    IF (e->>k) !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$' THEN\n      RAISE EXCEPTION 'Data UTC inválida' USING ERRCODE='22023';\n    END IF;\n    IF left(e->>k,19)<>to_char((e->>k)::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS')\n      OR left(e->>k,4)::integer<1970 THEN\n      RAISE EXCEPTION 'Data UTC com rollover inválida' USING ERRCODE='22023';\n    END IF;\n  END LOOP;\n  v_start:=(e->>'start_date')::timestamptz; v_until:=(e->>'access_until')::timestamptz; v_at:=(e->>'event_at')::timestamptz;\n  IF NOT isfinite(v_start) OR NOT isfinite(v_until) OR NOT isfinite(v_at)\n    OR v_start>v_now OR v_until<=v_now OR v_until<=v_start OR v_until<=v_at\n    OR v_until>v_at+interval '367 days' OR v_at>v_now+interval '30 seconds' THEN\n    RAISE EXCEPTION 'Período pago completo inválido' USING ERRCODE='22023';\n  END IF;\n  PERFORM set_config('lock_timeout','5s',true);\n  -- Short critical section excludes concurrent REST INSERT/UPDATE/DELETE until\n  -- lookup+create+binding+ledger commit. No slow bcrypt/API/email inside SQL.\n  LOCK TABLE public.users IN SHARE ROW EXCLUSIVE MODE;\n  PERFORM 1 FROM public.kiwify_blacklist_products WHERE product_id=v_product AND enabled FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não habilitado' USING ERRCODE='42501'; END IF;\n  SELECT array_agg(id ORDER BY id) INTO matches FROM\n    (SELECT id FROM public.users WHERE lower(btrim(email))=v_email ORDER BY id LIMIT 2) u;\n  IF coalesce(cardinality(matches),0)>1 THEN\n    RAISE EXCEPTION 'Email ambíguo' USING ERRCODE='23505';\n  END IF;\n  SELECT * INTO b FROM public.kiwify_buyers WHERE order_id=v_order FOR UPDATE;\n  IF FOUND THEN\n    IF b.email<>v_email OR b.subscription_id<>v_sub OR b.product_id<>v_product\n      OR cardinality(matches) IS DISTINCT FROM 1 OR matches[1]<>b.user_id THEN\n      RAISE EXCEPTION 'Pedido/titular divergentes' USING ERRCODE='23505';\n    END IF;\n    v_user:=b.user_id; created:=b.created_user;\n  ELSE\n    IF coalesce(cardinality(matches),0)=1 THEN v_user:=matches[1];\n    ELSE\n      INSERT INTO public.users(\"openId\",name,email,\"passwordHash\",\"loginMethod\",role)\n        VALUES(v_open,'Cliente CobraPro',v_email,v_hash,'kiwify','user') RETURNING id INTO v_user;\n      created:=true;\n    END IF;\n  END IF;\n  -- 0027 independently rechecks immutable subscription/order identity, sticky\n  -- refund and full period. Any failure rolls back the brand-new user too.\n  receipt:=public.rpc_kiwify_blacklist_consume(e||jsonb_build_object('user_id',v_user));\n  IF receipt->'accepted' IS DISTINCT FROM 'true'::jsonb THEN\n    RAISE EXCEPTION 'Ledger indisponível' USING ERRCODE='23514';\n  END IF;\n  IF b.order_id IS NULL THEN\n    IF created AND (receipt->>'outcome'<>'paid_period' OR receipt->'eligible' IS DISTINCT FROM 'true'::jsonb) THEN\n      RAISE EXCEPTION 'Novo comprador sem período pago aprovado' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.kiwify_buyers(order_id,subscription_id,product_id,user_id,email,created_user,invite_state)\n      VALUES(v_order,v_sub,v_product,v_user,v_email,created,CASE WHEN created THEN 'pending' ELSE 'not_needed' END)\n      RETURNING * INTO b;\n  END IF;\n  RETURN jsonb_build_object('user_id',v_user,'email',v_email,'created',created,\n    'applied',NOT (receipt->>'duplicate')::boolean OR receipt->>'outcome' IN ('financial_revoked','sticky_revocation'),\n    'invite_state',b.invite_state);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"postgres","sha256":"f2653c3688cfe2175c9c9d085a055023d41c054e89243bc06f73ffe658646662","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"signature":"public.rpc_kiwify_buyer_provision(jsonb)","definition_sha256":"685efe788c82a8bad7a7dca4d3815e2e6f25dd06a51a6c4e980338cc30aa198a","language":"plpgsql"},{"schema":"realtime","name":"apply_rls","oid":17241,"args":"wal jsonb, max_record_bytes integer","argtypes":"jsonb, integer","prosrc":"\ndeclare\n    -- Regclass of the table e.g. public.notes\n    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;\n\n    -- I, U, D, T: insert, update ...\n    action realtime.action = (\n        case wal ->> 'action'\n            when 'I' then 'INSERT'\n            when 'U' then 'UPDATE'\n            when 'D' then 'DELETE'\n            else 'ERROR'\n        end\n    );\n\n    -- Is row level security enabled for the table\n    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;\n\n    subscriptions realtime.subscription[] = array_agg(subs)\n        from\n            realtime.subscription subs\n        where\n            subs.entity = entity_\n            -- Filter by action early - only get subscriptions interested in this action\n            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'\n            and (subs.action_filter = '*' or subs.action_filter = action::text);\n\n    -- Subscription vars\n    working_role regrole;\n    working_selected_columns text[];\n    claimed_role regrole;\n    claims jsonb;\n\n    subscription_id uuid;\n    subscription_has_access bool;\n    visible_to_subscription_ids uuid[] = '{}';\n\n    -- structured info for wal's columns\n    columns realtime.wal_column[];\n    -- previous identity values for update/delete\n    old_columns realtime.wal_column[];\n\n    -- the same values as wal2json sent them, which is what filters compare against\n    raw_columns realtime.wal_column[] =\n        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)\n        from jsonb_array_elements(wal -> 'columns') x;\n    raw_old_columns realtime.wal_column[] =\n        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)\n        from jsonb_array_elements(wal -> 'identity') x;\n\n    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;\n\n    -- Primary jsonb output for record\n    output jsonb;\n\n    -- Loop record for iterating unique roles (outer loop)\n    role_record record;\n    -- Loop record for iterating unique selected_columns within a role (inner loop)\n    cols_record record;\n    -- Subscription ids visible at the role level (before fanning out by selected_columns)\n    visible_role_sub_ids uuid[] = '{}';\n\nbegin\n    perform set_config('role', null, true);\n\n    columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'columns') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    old_columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'identity') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    for role_record in\n        select claims_role\n        from (select distinct claims_role from unnest(subscriptions)) t\n        order by claims_role::text\n    loop\n        working_role := role_record.claims_role;\n\n        -- Update `is_selectable` for columns and old_columns (once per role)\n        columns =\n            array_agg(\n                (\n                    c.name,\n                    c.type_name,\n                    c.type_oid,\n                    c.value,\n                    c.is_pkey,\n                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                )::realtime.wal_column\n            )\n            from\n                unnest(columns) c;\n\n        old_columns =\n                array_agg(\n                    (\n                        c.name,\n                        c.type_name,\n                        c.type_oid,\n                        c.value,\n                        c.is_pkey,\n                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                    )::realtime.wal_column\n                )\n                from\n                    unnest(old_columns) c;\n\n        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then\n            -- Fan out 400 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 400: Bad Request, no primary key']\n                )::realtime.wal_rls;\n            end loop;\n\n        -- The claims role does not have SELECT permission to the primary key of entity\n        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then\n            -- Fan out 401 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 401: Unauthorized']\n                )::realtime.wal_rls;\n            end loop;\n\n        else\n            -- Create the prepared statement (once per role)\n            if is_rls_enabled and action <> 'DELETE' then\n                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then\n                    deallocate walrus_rls_stmt;\n                end if;\n                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);\n            end if;\n\n            -- Collect all visible subscription IDs for this role (filter check + RLS check)\n            visible_role_sub_ids = '{}';\n\n            for subscription_id, claims in (\n                    select\n                        subs.subscription_id,\n                        subs.claims\n                    from\n                        unnest(subscriptions) subs\n                    where\n                        subs.entity = entity_\n                        and subs.claims_role = working_role\n                        and (\n                            realtime.is_visible_through_filters(raw_columns, subs.filters)\n                            or (\n                              action = 'DELETE'\n                              and realtime.is_visible_through_filters(raw_old_columns, subs.filters)\n                            )\n                        )\n            ) loop\n\n                if not is_rls_enabled or action = 'DELETE' then\n                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                else\n                    -- Check if RLS allows the role to see the record\n                    perform\n                        -- Trim leading and trailing quotes from working_role because set_config\n                        -- doesn't recognize the role as valid if they are included\n                        set_config('role', trim(both '\"' from working_role::text), true),\n                        set_config('request.jwt.claims', claims::text, true);\n\n                    execute 'execute walrus_rls_stmt' into subscription_has_access;\n\n                    -- Reset the role on every FOR..LOOP batch execution.\n                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)\n                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above\n                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.\n                    -- The flow is:\n                    --   1. run batch with conn role\n                    --   2. set_config working_role\n                    --   3. execute walrus\n                    --   4. reset role (revert)\n                    --   5. repeat\n                    perform set_config('role', null, true);\n\n                    if subscription_has_access then\n                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                    end if;\n                end if;\n            end loop;\n\n            perform set_config('role', null, true);\n\n            -- Inner loop: per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n\n                output = jsonb_build_object(\n                    'schema', wal ->> 'schema',\n                    'table', wal ->> 'table',\n                    'type', action,\n                    'commit_timestamp', to_char(\n                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),\n                        'YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'\n                    ),\n                    'columns', (\n                        select\n                            jsonb_agg(\n                                jsonb_build_object(\n                                    'name', pa.attname,\n                                    'type', pt.typname\n                                )\n                                order by pa.attnum asc\n                            )\n                        from\n                            pg_attribute pa\n                            join pg_type pt\n                                on pa.atttypid = pt.oid\n                            left join (\n                                select unnest(conkey) as pkey_attnum\n                                from pg_constraint\n                                where conrelid = entity_ and contype = 'p'\n                            ) pk on pk.pkey_attnum = pa.attnum\n                        where\n                            attrelid = entity_\n                            and attnum > 0\n                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')\n                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)\n                    )\n                )\n                -- Add \"record\" key for insert and update\n                || case\n                    when action in ('INSERT', 'UPDATE') then\n                        jsonb_build_object(\n                            'record',\n                            (\n                                select\n                                    jsonb_object_agg(\n                                        -- if unchanged toast, get column name and value from old record\n                                        coalesce((c).name, (oc).name),\n                                        case\n                                            when (c).name is null then (oc).value\n                                            else (c).value\n                                        end\n                                    )\n                                from\n                                    unnest(columns) c\n                                    full outer join unnest(old_columns) oc\n                                        on (c).name = (oc).name\n                                where\n                                    coalesce((c).is_selectable, (oc).is_selectable)\n                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                            )\n                        )\n                    else '{}'::jsonb\n                end\n                -- Add \"old_record\" key for update and delete\n                || case\n                    when action = 'UPDATE' then\n                        jsonb_build_object(\n                                'old_record',\n                                (\n                                    select jsonb_object_agg((c).name, (c).value)\n                                    from unnest(old_columns) c\n                                    where\n                                        (c).is_selectable\n                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                )\n                            )\n                    when action = 'DELETE' then\n                        jsonb_build_object(\n                            'old_record',\n                            (\n                                select jsonb_object_agg((c).name, (c).value)\n                                from unnest(old_columns) c\n                                where\n                                    (c).is_selectable\n                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey\n                            )\n                        )\n                    else '{}'::jsonb\n                end;\n\n                -- Filter visible_role_sub_ids to those matching the current selected_columns group\n                visible_to_subscription_ids = coalesce(\n                    (\n                        select array_agg(s.subscription_id)\n                        from unnest(subscriptions) s\n                        where s.claims_role = working_role\n                          and (s.selected_columns is not distinct from working_selected_columns)\n                          and s.subscription_id = any(visible_role_sub_ids)\n                    ),\n                    '{}'::uuid[]\n                );\n\n                return next (\n                    output,\n                    is_rls_enabled,\n                    visible_to_subscription_ids,\n                    case\n                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']\n                        else '{}'\n                    end\n                )::realtime.wal_rls;\n            end loop;\n\n        end if;\n    end loop;\n\n    perform set_config('role', null, true);\nend;\n","probin":null,"rettype":"realtime.wal_rls","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024))\n RETURNS SETOF realtime.wal_rls\n LANGUAGE plpgsql\nAS $function$\ndeclare\n    -- Regclass of the table e.g. public.notes\n    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;\n\n    -- I, U, D, T: insert, update ...\n    action realtime.action = (\n        case wal ->> 'action'\n            when 'I' then 'INSERT'\n            when 'U' then 'UPDATE'\n            when 'D' then 'DELETE'\n            else 'ERROR'\n        end\n    );\n\n    -- Is row level security enabled for the table\n    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;\n\n    subscriptions realtime.subscription[] = array_agg(subs)\n        from\n            realtime.subscription subs\n        where\n            subs.entity = entity_\n            -- Filter by action early - only get subscriptions interested in this action\n            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'\n            and (subs.action_filter = '*' or subs.action_filter = action::text);\n\n    -- Subscription vars\n    working_role regrole;\n    working_selected_columns text[];\n    claimed_role regrole;\n    claims jsonb;\n\n    subscription_id uuid;\n    subscription_has_access bool;\n    visible_to_subscription_ids uuid[] = '{}';\n\n    -- structured info for wal's columns\n    columns realtime.wal_column[];\n    -- previous identity values for update/delete\n    old_columns realtime.wal_column[];\n\n    -- the same values as wal2json sent them, which is what filters compare against\n    raw_columns realtime.wal_column[] =\n        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)\n        from jsonb_array_elements(wal -> 'columns') x;\n    raw_old_columns realtime.wal_column[] =\n        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)\n        from jsonb_array_elements(wal -> 'identity') x;\n\n    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;\n\n    -- Primary jsonb output for record\n    output jsonb;\n\n    -- Loop record for iterating unique roles (outer loop)\n    role_record record;\n    -- Loop record for iterating unique selected_columns within a role (inner loop)\n    cols_record record;\n    -- Subscription ids visible at the role level (before fanning out by selected_columns)\n    visible_role_sub_ids uuid[] = '{}';\n\nbegin\n    perform set_config('role', null, true);\n\n    columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'columns') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    old_columns =\n        array_agg(\n            (\n                x->>'name',\n                x->>'type',\n                x->>'typeoid',\n                realtime.cast(\n                    (x->'value') #>> '{}',\n                    coalesce(\n                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4\n                        (x->>'type')::regtype\n                    )\n                ),\n                (pks ->> 'name') is not null,\n                true\n            )::realtime.wal_column\n        )\n        from\n            jsonb_array_elements(wal -> 'identity') x\n            left join jsonb_array_elements(wal -> 'pk') pks\n                on (x ->> 'name') = (pks ->> 'name');\n\n    for role_record in\n        select claims_role\n        from (select distinct claims_role from unnest(subscriptions)) t\n        order by claims_role::text\n    loop\n        working_role := role_record.claims_role;\n\n        -- Update `is_selectable` for columns and old_columns (once per role)\n        columns =\n            array_agg(\n                (\n                    c.name,\n                    c.type_name,\n                    c.type_oid,\n                    c.value,\n                    c.is_pkey,\n                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                )::realtime.wal_column\n            )\n            from\n                unnest(columns) c;\n\n        old_columns =\n                array_agg(\n                    (\n                        c.name,\n                        c.type_name,\n                        c.type_oid,\n                        c.value,\n                        c.is_pkey,\n                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')\n                    )::realtime.wal_column\n                )\n                from\n                    unnest(old_columns) c;\n\n        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then\n            -- Fan out 400 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 400: Bad Request, no primary key']\n                )::realtime.wal_rls;\n            end loop;\n\n        -- The claims role does not have SELECT permission to the primary key of entity\n        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then\n            -- Fan out 401 error per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n                return next (\n                    jsonb_build_object(\n                        'schema', wal ->> 'schema',\n                        'table', wal ->> 'table',\n                        'type', action\n                    ),\n                    is_rls_enabled,\n                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),\n                    array['Error 401: Unauthorized']\n                )::realtime.wal_rls;\n            end loop;\n\n        else\n            -- Create the prepared statement (once per role)\n            if is_rls_enabled and action <> 'DELETE' then\n                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then\n                    deallocate walrus_rls_stmt;\n                end if;\n                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);\n            end if;\n\n            -- Collect all visible subscription IDs for this role (filter check + RLS check)\n            visible_role_sub_ids = '{}';\n\n            for subscription_id, claims in (\n                    select\n                        subs.subscription_id,\n                        subs.claims\n                    from\n                        unnest(subscriptions) subs\n                    where\n                        subs.entity = entity_\n                        and subs.claims_role = working_role\n                        and (\n                            realtime.is_visible_through_filters(raw_columns, subs.filters)\n                            or (\n                              action = 'DELETE'\n                              and realtime.is_visible_through_filters(raw_old_columns, subs.filters)\n                            )\n                        )\n            ) loop\n\n                if not is_rls_enabled or action = 'DELETE' then\n                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                else\n                    -- Check if RLS allows the role to see the record\n                    perform\n                        -- Trim leading and trailing quotes from working_role because set_config\n                        -- doesn't recognize the role as valid if they are included\n                        set_config('role', trim(both '\"' from working_role::text), true),\n                        set_config('request.jwt.claims', claims::text, true);\n\n                    execute 'execute walrus_rls_stmt' into subscription_has_access;\n\n                    -- Reset the role on every FOR..LOOP batch execution.\n                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)\n                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above\n                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.\n                    -- The flow is:\n                    --   1. run batch with conn role\n                    --   2. set_config working_role\n                    --   3. execute walrus\n                    --   4. reset role (revert)\n                    --   5. repeat\n                    perform set_config('role', null, true);\n\n                    if subscription_has_access then\n                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;\n                    end if;\n                end if;\n            end loop;\n\n            perform set_config('role', null, true);\n\n            -- Inner loop: per distinct selected_columns for this role\n            for cols_record in\n                select selected_columns\n                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t\n                order by coalesce(array_to_string(selected_columns, ','), '')\n            loop\n                working_selected_columns := cols_record.selected_columns;\n\n                output = jsonb_build_object(\n                    'schema', wal ->> 'schema',\n                    'table', wal ->> 'table',\n                    'type', action,\n                    'commit_timestamp', to_char(\n                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),\n                        'YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'\n                    ),\n                    'columns', (\n                        select\n                            jsonb_agg(\n                                jsonb_build_object(\n                                    'name', pa.attname,\n                                    'type', pt.typname\n                                )\n                                order by pa.attnum asc\n                            )\n                        from\n                            pg_attribute pa\n                            join pg_type pt\n                                on pa.atttypid = pt.oid\n                            left join (\n                                select unnest(conkey) as pkey_attnum\n                                from pg_constraint\n                                where conrelid = entity_ and contype = 'p'\n                            ) pk on pk.pkey_attnum = pa.attnum\n                        where\n                            attrelid = entity_\n                            and attnum > 0\n                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')\n                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)\n                    )\n                )\n                -- Add \"record\" key for insert and update\n                || case\n                    when action in ('INSERT', 'UPDATE') then\n                        jsonb_build_object(\n                            'record',\n                            (\n                                select\n                                    jsonb_object_agg(\n                                        -- if unchanged toast, get column name and value from old record\n                                        coalesce((c).name, (oc).name),\n                                        case\n                                            when (c).name is null then (oc).value\n                                            else (c).value\n                                        end\n                                    )\n                                from\n                                    unnest(columns) c\n                                    full outer join unnest(old_columns) oc\n                                        on (c).name = (oc).name\n                                where\n                                    coalesce((c).is_selectable, (oc).is_selectable)\n                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                            )\n                        )\n                    else '{}'::jsonb\n                end\n                -- Add \"old_record\" key for update and delete\n                || case\n                    when action = 'UPDATE' then\n                        jsonb_build_object(\n                                'old_record',\n                                (\n                                    select jsonb_object_agg((c).name, (c).value)\n                                    from unnest(old_columns) c\n                                    where\n                                        (c).is_selectable\n                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                )\n                            )\n                    when action = 'DELETE' then\n                        jsonb_build_object(\n                            'old_record',\n                            (\n                                select jsonb_object_agg((c).name, (c).value)\n                                from unnest(old_columns) c\n                                where\n                                    (c).is_selectable\n                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)\n                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))\n                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey\n                            )\n                        )\n                    else '{}'::jsonb\n                end;\n\n                -- Filter visible_role_sub_ids to those matching the current selected_columns group\n                visible_to_subscription_ids = coalesce(\n                    (\n                        select array_agg(s.subscription_id)\n                        from unnest(subscriptions) s\n                        where s.claims_role = working_role\n                          and (s.selected_columns is not distinct from working_selected_columns)\n                          and s.subscription_id = any(visible_role_sub_ids)\n                    ),\n                    '{}'::uuid[]\n                );\n\n                return next (\n                    output,\n                    is_rls_enabled,\n                    visible_to_subscription_ids,\n                    case\n                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']\n                        else '{}'\n                    end\n                )::realtime.wal_rls;\n            end loop;\n\n        end if;\n    end loop;\n\n    perform set_config('role', null, true);\nend;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"c0d066e616c051710c40bf0d98fd593b80b9aa51fcb631b14c6dd4e9b0773d18","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.apply_rls(jsonb, integer)","definition_sha256":"2610dd547b35386f803098c27d1511f2ea9bfbd78262d232e6c51c18a53029f1","language":"plpgsql"},{"schema":"realtime","name":"authorize","oid":31085,"args":"role_name text, topic_name text, claims text, sub text, headers text, read_extensions text[], write_extensions text[], OUT read_allowed boolean[], OUT write_allowed boolean[]","argtypes":"text, text, text, text, text, text[], text[]","prosrc":"\ndeclare\n  probe_ids uuid[];\n  probe_inserted_at timestamp := now() at time zone 'utc';\n  visible_ids uuid[];\n  ext text;\n  allowed boolean;\nbegin\n  -- The probe inserts are rolled back, but they still give the transaction an xid, so it ends\n  -- in a commit. Nothing durable was written, so skip waiting on the WAL flush and sync standbys.\n  -- Set outside the block below, whose rollback would undo it.\n  perform set_config('synchronous_commit', 'off', true);\n\n  -- The RAISE at the end of this block rolls back everything in it.\n  begin\n    probe_ids := array(select gen_random_uuid() from unnest(read_extensions));\n\n    insert into realtime.messages (id, topic, extension, inserted_at, updated_at)\n    select p.id, topic_name, p.extension, probe_inserted_at, probe_inserted_at\n    from unnest(probe_ids, read_extensions) as p(id, extension);\n\n    perform set_config('role', role_name, true),\n            set_config('realtime.topic', topic_name, true),\n            set_config('request.jwt.claims', claims, true),\n            set_config('request.jwt.claim.sub', sub, true),\n            set_config('request.jwt.claim.role', role_name, true),\n            set_config('request.headers', headers, true);\n\n    -- One lookup for every probe, by the full primary key. Skipped without probes, so the\n    -- SELECT policies are not planned for a write.\n    if cardinality(probe_ids) > 0 then\n      visible_ids := array(\n        select m.id\n        from realtime.messages m\n        where m.inserted_at = probe_inserted_at\n          and m.id = any(probe_ids));\n    end if;\n\n    read_allowed := array(\n      select p.id = any(visible_ids)\n      from unnest(probe_ids) with ordinality as p(id, n)\n      order by p.n);\n\n    write_allowed := '{}';\n\n    foreach ext in array write_extensions loop\n      begin\n        insert into realtime.messages (topic, extension, inserted_at, updated_at)\n        values (topic_name, ext, now() at time zone 'utc', now() at time zone 'utc');\n\n        allowed := true;\n      exception when insufficient_privilege then\n        allowed := false;\n      end;\n\n      write_allowed := write_allowed || allowed;\n    end loop;\n\n    raise sqlstate 'RTA01';\n  exception when sqlstate 'RTA01' then\n    null;\n  end;\nend;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.authorize(role_name text, topic_name text, claims text, sub text, headers text, read_extensions text[], write_extensions text[], OUT read_allowed boolean[], OUT write_allowed boolean[])\n RETURNS record\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  probe_ids uuid[];\n  probe_inserted_at timestamp := now() at time zone 'utc';\n  visible_ids uuid[];\n  ext text;\n  allowed boolean;\nbegin\n  -- The probe inserts are rolled back, but they still give the transaction an xid, so it ends\n  -- in a commit. Nothing durable was written, so skip waiting on the WAL flush and sync standbys.\n  -- Set outside the block below, whose rollback would undo it.\n  perform set_config('synchronous_commit', 'off', true);\n\n  -- The RAISE at the end of this block rolls back everything in it.\n  begin\n    probe_ids := array(select gen_random_uuid() from unnest(read_extensions));\n\n    insert into realtime.messages (id, topic, extension, inserted_at, updated_at)\n    select p.id, topic_name, p.extension, probe_inserted_at, probe_inserted_at\n    from unnest(probe_ids, read_extensions) as p(id, extension);\n\n    perform set_config('role', role_name, true),\n            set_config('realtime.topic', topic_name, true),\n            set_config('request.jwt.claims', claims, true),\n            set_config('request.jwt.claim.sub', sub, true),\n            set_config('request.jwt.claim.role', role_name, true),\n            set_config('request.headers', headers, true);\n\n    -- One lookup for every probe, by the full primary key. Skipped without probes, so the\n    -- SELECT policies are not planned for a write.\n    if cardinality(probe_ids) > 0 then\n      visible_ids := array(\n        select m.id\n        from realtime.messages m\n        where m.inserted_at = probe_inserted_at\n          and m.id = any(probe_ids));\n    end if;\n\n    read_allowed := array(\n      select p.id = any(visible_ids)\n      from unnest(probe_ids) with ordinality as p(id, n)\n      order by p.n);\n\n    write_allowed := '{}';\n\n    foreach ext in array write_extensions loop\n      begin\n        insert into realtime.messages (topic, extension, inserted_at, updated_at)\n        values (topic_name, ext, now() at time zone 'utc', now() at time zone 'utc');\n\n        allowed := true;\n      exception when insufficient_privilege then\n        allowed := false;\n      end;\n\n      write_allowed := write_allowed || allowed;\n    end loop;\n\n    raise sqlstate 'RTA01';\n  exception when sqlstate 'RTA01' then\n    null;\n  end;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"f870da644db3cdd1545d2d8174dbb2bf957d2987c629508410ea13d96a0d8cf0","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.authorize(text, text, text, text, text, text[], text[])","definition_sha256":"5fec94cda6c5cb1d4f48e9e2ca271b7edbd61bb38582bc55bedb4106a0f6b294","language":"plpgsql"},{"schema":"realtime","name":"broadcast_changes","oid":17320,"args":"topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text","argtypes":"text, text, text, text, text, record, record, text","prosrc":"\nDECLARE\n    -- Declare a variable to hold the JSONB representation of the row\n    row_data jsonb := '{}'::jsonb;\nBEGIN\n    IF level = 'STATEMENT' THEN\n        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';\n    END IF;\n    -- Check the operation type and handle accordingly\n    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN\n        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);\n        PERFORM realtime.send (row_data, event_name, topic_name);\n    ELSE\n        RAISE EXCEPTION 'Unexpected operation type: %', operation;\n    END IF;\nEXCEPTION\n    WHEN OTHERS THEN\n        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;\nEND;\n\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    -- Declare a variable to hold the JSONB representation of the row\n    row_data jsonb := '{}'::jsonb;\nBEGIN\n    IF level = 'STATEMENT' THEN\n        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';\n    END IF;\n    -- Check the operation type and handle accordingly\n    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN\n        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);\n        PERFORM realtime.send (row_data, event_name, topic_name);\n    ELSE\n        RAISE EXCEPTION 'Unexpected operation type: %', operation;\n    END IF;\nEXCEPTION\n    WHEN OTHERS THEN\n        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;\nEND;\n\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"34bede627747febd30b84b13c3dab171c4a64f631f85f91e528d075d174b7b35","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.broadcast_changes(text, text, text, text, text, record, record, text)","definition_sha256":"8a79db74092ebe9363317a96e97cd5e558be40ba83497214867e80ec0ac0f340","language":"plpgsql"},{"schema":"realtime","name":"build_prepared_statement_sql","oid":17253,"args":"prepared_statement_name text, entity regclass, columns realtime.wal_column[]","argtypes":"text, regclass, realtime.wal_column[]","prosrc":"\n      /*\n      Builds a sql string that, if executed, creates a prepared statement to\n      tests retrive a row from *entity* by its primary key columns.\n      Example\n          select realtime.build_prepared_statement_sql('public.notes', '{\"id\"}'::text[], '{\"bigint\"}'::text[])\n      */\n          select\n      'prepare ' || prepared_statement_name || ' as\n          select\n              exists(\n                  select\n                      1\n                  from\n                      ' || entity || '\n                  where\n                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '\n              )'\n          from\n              unnest(columns) pkc\n          where\n              pkc.is_pkey\n          group by\n              entity\n      ","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[])\n RETURNS text\n LANGUAGE sql\nAS $function$\n      /*\n      Builds a sql string that, if executed, creates a prepared statement to\n      tests retrive a row from *entity* by its primary key columns.\n      Example\n          select realtime.build_prepared_statement_sql('public.notes', '{\"id\"}'::text[], '{\"bigint\"}'::text[])\n      */\n          select\n      'prepare ' || prepared_statement_name || ' as\n          select\n              exists(\n                  select\n                      1\n                  from\n                      ' || entity || '\n                  where\n                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '\n              )'\n          from\n              unnest(columns) pkc\n          where\n              pkc.is_pkey\n          group by\n              entity\n      $function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"54e0b108e79b1375ca9e07d5e5f2556a8957f88873a43c96dee185d28f553446","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.build_prepared_statement_sql(text, regclass, realtime.wal_column[])","definition_sha256":"46923b06f4d06e66bed424b6da25bd00d5f70472ff398d35d2ae50f3634359ba","language":"sql"},{"schema":"realtime","name":"cast","oid":17203,"args":"val text, type_ regtype","argtypes":"text, regtype","prosrc":"\ndeclare\n  res jsonb;\nbegin\n  if type_::text = 'bytea' then\n    return to_jsonb(val);\n  end if;\n  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;\n  return res;\nend\n","probin":null,"rettype":"jsonb","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.\"cast\"(val text, type_ regtype)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\ndeclare\n  res jsonb;\nbegin\n  if type_::text = 'bytea' then\n    return to_jsonb(val);\n  end if;\n  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;\n  return res;\nend\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"95c1a91449e4ec2e0d7951e0396ca2b298166a78f8dc0c61a2136580e7f92379","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.cast(text, regtype)","definition_sha256":"66045bb2d0564fbee8ce156ddd29bf5ff554614c755f9a66902dbff131721993","language":"plpgsql"},{"schema":"realtime","name":"check_equality_op","oid":17198,"args":"op realtime.equality_op, type_ regtype, val_1 text, val_2 text","argtypes":"realtime.equality_op, regtype, text, text","prosrc":"\n/*\nCasts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness\n*/\ndeclare\n    op_symbol text = (\n        case\n            when op = 'eq' then '='\n            when op = 'neq' then '!='\n            when op = 'lt' then '<'\n            when op = 'lte' then '<='\n            when op = 'gt' then '>'\n            when op = 'gte' then '>='\n            when op = 'in' then '= any'\n            else 'UNKNOWN OP'\n        end\n    );\n    res boolean;\nbegin\n    execute format(\n        'select %L::'|| type_::text || ' ' || op_symbol\n        || ' ( %L::'\n        || (\n            case\n                when op = 'in' then type_::text || '[]'\n                else type_::text end\n        )\n        || ')', val_1, val_2) into res;\n    return res;\nend;\n","probin":null,"rettype":"boolean","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\n/*\nCasts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness\n*/\ndeclare\n    op_symbol text = (\n        case\n            when op = 'eq' then '='\n            when op = 'neq' then '!='\n            when op = 'lt' then '<'\n            when op = 'lte' then '<='\n            when op = 'gt' then '>'\n            when op = 'gte' then '>='\n            when op = 'in' then '= any'\n            else 'UNKNOWN OP'\n        end\n    );\n    res boolean;\nbegin\n    execute format(\n        'select %L::'|| type_::text || ' ' || op_symbol\n        || ' ( %L::'\n        || (\n            case\n                when op = 'in' then type_::text || '[]'\n                else type_::text end\n        )\n        || ')', val_1, val_2) into res;\n    return res;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"5be2aba7d4eff0d57170acd18a11ae342f163aa5de6e9ee372659cb1698689fa","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.check_equality_op(realtime.equality_op, regtype, text, text)","definition_sha256":"bc47685b70704c535aa1f7ae9b36e1a2d7a379499ee70462f4fa4f06e6bef98b","language":"plpgsql"},{"schema":"realtime","name":"check_equality_op","oid":30190,"args":"op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean","argtypes":"realtime.equality_op, regtype, text, text, boolean","prosrc":"\ndeclare\n    op_symbol text;\n    res boolean;\nbegin\n    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals\n    if op = 'isdistinct' then\n        execute format(\n            'select %L::%s %s %L::%s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,\n            val_2,\n            type_::text\n        ) into res;\n        return res;\n    end if;\n\n    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal\n    if op = 'is' then\n        if val_2 not in ('null', 'true', 'false', 'unknown') then\n            raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n        end if;\n        execute format(\n            'select %L::%s %s %s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT' else 'IS' end,\n            upper(val_2)\n        ) into res;\n        return res;\n    end if;\n\n    op_symbol = case\n        when op = 'eq'    then '='\n        when op = 'neq'   then '!='\n        when op = 'lt'    then '<'\n        when op = 'lte'   then '<='\n        when op = 'gt'    then '>'\n        when op = 'gte'   then '>='\n        when op = 'in'    then '= any'\n        when op = 'like'   then 'LIKE'\n        when op = 'ilike'  then 'ILIKE'\n        when op = 'match'  then '~'\n        when op = 'imatch' then '~*'\n        else null\n    end;\n\n    if op_symbol is null then\n        raise exception 'unsupported equality operator: %', op::text;\n    end if;\n\n    execute format(\n        'select %L::%s %s (%L::%s)',\n        val_1,\n        type_::text,\n        op_symbol,\n        val_2,\n        case when op = 'in' then type_::text || '[]' else type_::text end\n    ) into res;\n\n    return case when negate then not res else res end;\nend;\n","probin":null,"rettype":"boolean","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE\nAS $function$\ndeclare\n    op_symbol text;\n    res boolean;\nbegin\n    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals\n    if op = 'isdistinct' then\n        execute format(\n            'select %L::%s %s %L::%s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,\n            val_2,\n            type_::text\n        ) into res;\n        return res;\n    end if;\n\n    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal\n    if op = 'is' then\n        if val_2 not in ('null', 'true', 'false', 'unknown') then\n            raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n        end if;\n        execute format(\n            'select %L::%s %s %s',\n            val_1,\n            type_::text,\n            case when negate then 'IS NOT' else 'IS' end,\n            upper(val_2)\n        ) into res;\n        return res;\n    end if;\n\n    op_symbol = case\n        when op = 'eq'    then '='\n        when op = 'neq'   then '!='\n        when op = 'lt'    then '<'\n        when op = 'lte'   then '<='\n        when op = 'gt'    then '>'\n        when op = 'gte'   then '>='\n        when op = 'in'    then '= any'\n        when op = 'like'   then 'LIKE'\n        when op = 'ilike'  then 'ILIKE'\n        when op = 'match'  then '~'\n        when op = 'imatch' then '~*'\n        else null\n    end;\n\n    if op_symbol is null then\n        raise exception 'unsupported equality operator: %', op::text;\n    end if;\n\n    execute format(\n        'select %L::%s %s (%L::%s)',\n        val_1,\n        type_::text,\n        op_symbol,\n        val_2,\n        case when op = 'in' then type_::text || '[]' else type_::text end\n    ) into res;\n\n    return case when negate then not res else res end;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"4a3fe1e33d6b3434a85e3af7555dc3d3d63c7e59b7d7e3593728a7624b0eafa4","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.check_equality_op(realtime.equality_op, regtype, text, text, boolean)","definition_sha256":"4579e8273553e43f102fb70a03872ff3dab25408895af3184907e76a04cf06f9","language":"plpgsql"},{"schema":"realtime","name":"filters_hash","oid":31815,"args":"filters realtime.user_defined_filter[]","argtypes":"realtime.user_defined_filter[]","prosrc":"\n  select pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 0))\n      || pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 1))\n","probin":null,"rettype":"bytea","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.filters_hash(filters realtime.user_defined_filter[])\n RETURNS bytea\n LANGUAGE sql\n IMMUTABLE PARALLEL SAFE STRICT\nAS $function$\n  select pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 0))\n      || pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 1))\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":true,"parallel":"s","kind":"f","owner":"supabase_realtime_admin","sha256":"09e71c01ef27dd79d9a6e2edc63f16b4ecc0f59c1cc02dc347b7c6332d01aba5","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.filters_hash(realtime.user_defined_filter[])","definition_sha256":"d471cc424fa24ddbcef752616573c66dca57a4d8254710b743f0993f7865e293","language":"sql"},{"schema":"realtime","name":"is_visible_through_filters","oid":17249,"args":"columns realtime.wal_column[], filters realtime.user_defined_filter[]","argtypes":"realtime.wal_column[], realtime.user_defined_filter[]","prosrc":"\n    select\n        filters is null\n        or array_length(filters, 1) is null\n        or coalesce(\n            count(col.name) = count(1)\n            and sum(\n                realtime.check_equality_op(\n                    op:=f.op,\n                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),\n                    val_1:=col.value #>> '{}',\n                    val_2:=f.value,\n                    negate:=coalesce(f.negate, false)\n                )::int\n            ) filter (where col.name is not null) = count(col.name),\n            false\n        )\n    from\n        unnest(filters) f\n        left join unnest(columns) col\n            on f.column_name = col.name;\n","probin":null,"rettype":"boolean","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[])\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n    select\n        filters is null\n        or array_length(filters, 1) is null\n        or coalesce(\n            count(col.name) = count(1)\n            and sum(\n                realtime.check_equality_op(\n                    op:=f.op,\n                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),\n                    val_1:=col.value #>> '{}',\n                    val_2:=f.value,\n                    negate:=coalesce(f.negate, false)\n                )::int\n            ) filter (where col.name is not null) = count(col.name),\n            false\n        )\n    from\n        unnest(filters) f\n        left join unnest(columns) col\n            on f.column_name = col.name;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"68c38444aca4bd9c798fd84a2e7154055420e27e37b35a974d6cce640752f79e","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[])","definition_sha256":"4583a3c4c0425a65597a33472f7efab296765665db5c2cef5b309f84adafc1b5","language":"sql"},{"schema":"realtime","name":"list_changes","oid":30093,"args":"publication name, slot_name name, max_changes integer, max_record_bytes integer","argtypes":"name, name, integer, integer","prosrc":"\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once\n  w2j AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         pg_logical_slot_get_changes(\n           slot_name, null, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM w2j\n    WHERE w2j.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM w2j,\n         realtime.apply_rls(\n           wal := w2j.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE w2j.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n","probin":null,"rettype":"record","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer)\n RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)\n LANGUAGE sql\n SET log_min_messages TO 'fatal'\nAS $function$\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once\n  w2j AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         pg_logical_slot_get_changes(\n           slot_name, null, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM w2j\n    WHERE w2j.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM w2j,\n         realtime.apply_rls(\n           wal := w2j.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE w2j.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n$function$\n","config":["log_min_messages=fatal"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"233b2400d3b4aebd6cec36eb19c82b3f20ea7f9359eeb17c6f50fb1ad36cfb92","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.list_changes(name, name, integer, integer)","definition_sha256":"6ecaa7b9145a223931a3e5d6a0275750fc663fe90d56bbb353a2963eb2b935eb","language":"sql"},{"schema":"realtime","name":"list_changes_sync","oid":31083,"args":"publication name, slot_name name, max_changes integer, max_record_bytes integer","argtypes":"name, name, integer, integer","prosrc":"\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures the slot is read exactly once.\n  consumed AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         realtime.settled_changes(\n           slot_name, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM consumed\n    WHERE consumed.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM consumed,\n         realtime.apply_rls(\n           wal := consumed.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE consumed.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n","probin":null,"rettype":"record","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.list_changes_sync(publication name, slot_name name, max_changes integer, max_record_bytes integer)\n RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)\n LANGUAGE sql\n SET log_min_messages TO 'fatal'\nAS $function$\n  WITH pub AS (\n    SELECT\n      concat_ws(\n        ',',\n        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,\n        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,\n        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END\n      ) AS w2j_actions,\n      coalesce(\n        string_agg(\n          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),\n          ','\n        ) filter (WHERE ppt.tablename IS NOT NULL),\n        ''\n      ) AS w2j_add_tables\n    FROM pg_publication pp\n    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname\n    WHERE pp.pubname = publication\n    GROUP BY pp.pubname\n    LIMIT 1\n  ),\n  -- MATERIALIZED ensures the slot is read exactly once.\n  consumed AS MATERIALIZED (\n    SELECT x.*, pub.w2j_add_tables\n    FROM pub,\n         realtime.settled_changes(\n           slot_name, max_changes,\n           'include-pk', 'true',\n           'include-transaction', 'false',\n           'include-timestamp', 'true',\n           'include-type-oids', 'true',\n           'format-version', '2',\n           'actions', pub.w2j_actions,\n           'add-tables', pub.w2j_add_tables\n         ) x\n  ),\n  slot_count AS (\n    SELECT count(*)::bigint AS cnt\n    FROM consumed\n    WHERE consumed.w2j_add_tables <> ''\n  ),\n  rls_filtered AS (\n    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors\n    FROM consumed,\n         realtime.apply_rls(\n           wal := consumed.data::jsonb,\n           max_record_bytes := max_record_bytes\n         ) xyz(wal, is_rls_enabled, subscription_ids, errors)\n    WHERE consumed.w2j_add_tables <> ''\n      AND xyz.subscription_ids[1] IS NOT NULL\n  )\n  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt\n  FROM rls_filtered rf, slot_count sc\n\n  UNION ALL\n\n  SELECT null, null, null, null, sc.cnt\n  FROM slot_count sc\n  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)\n$function$\n","config":["log_min_messages=fatal"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"708e8ebf818bd7b19ffb562d1ffde5a67ee131060e46204bc88725fd8a88d889","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.list_changes_sync(name, name, integer, integer)","definition_sha256":"75a28ea0ba366ba7ac8dfce61c207a75b344f187fe01c42975a108ac90528a37","language":"sql"},{"schema":"realtime","name":"quote_wal2json","oid":17197,"args":"entity regclass","argtypes":"regclass","prosrc":"\n  SELECT\n    realtime.wal2json_escape_identifier(nsp.nspname::text)\n    || '.'\n    || realtime.wal2json_escape_identifier(pc.relname::text)\n  FROM pg_class pc\n  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid\n  WHERE pc.oid = entity\n","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.quote_wal2json(entity regclass)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\nAS $function$\n  SELECT\n    realtime.wal2json_escape_identifier(nsp.nspname::text)\n    || '.'\n    || realtime.wal2json_escape_identifier(pc.relname::text)\n  FROM pg_class pc\n  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid\n  WHERE pc.oid = entity\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":true,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"50d3193d837105430fbbb66d70618ba2b0dcf45489c3a4e54357edaf036d4fa2","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.quote_wal2json(regclass)","definition_sha256":"3217b2be7b664a0a6c2efd2438c59c430962a7c2b302816c928467b30d491cc0","language":"sql"},{"schema":"realtime","name":"send","oid":17319,"args":"payload jsonb, event text, topic text, private boolean","argtypes":"jsonb, text, text, boolean","prosrc":"\nDECLARE\n  generated_id uuid;\n  final_payload jsonb;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    -- Check if payload has an 'id' key, if not, add the generated UUID\n    IF payload ? 'id' THEN\n      final_payload := payload;\n    ELSE\n      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));\n    END IF;\n\n    -- Set the topic configuration\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)\n    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  generated_id uuid;\n  final_payload jsonb;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    -- Check if payload has an 'id' key, if not, add the generated UUID\n    IF payload ? 'id' THEN\n      final_payload := payload;\n    ELSE\n      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));\n    END IF;\n\n    -- Set the topic configuration\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)\n    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"d65250d0c0f8e9ec5c283744d0272626ca0f1e13a034ee07b2d0c92fc6d4557a","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.send(jsonb, text, text, boolean)","definition_sha256":"a59ff7fd7608eb6b987fbeb20e49aacb0b29f7ee75dbf5046e10bc5f1d058f33","language":"plpgsql"},{"schema":"realtime","name":"send_binary","oid":30094,"args":"payload bytea, event text, topic text, private boolean","argtypes":"bytea, text, text, boolean","prosrc":"\nDECLARE\n  generated_id uuid;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)\n    VALUES (generated_id, payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.send_binary(payload bytea, event text, topic text, private boolean DEFAULT true)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  generated_id uuid;\nBEGIN\n  BEGIN\n    generated_id := gen_random_uuid();\n\n    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);\n\n    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)\n    VALUES (generated_id, payload, event, topic, private, 'broadcast');\n  EXCEPTION\n    WHEN OTHERS THEN\n      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;\n  END;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"6e36ccd8f9994dc41155d95643488608974557aed2c114ab7d9bf0ff11c149ef","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.send_binary(bytea, text, text, boolean)","definition_sha256":"73a170d9b813d8e1835c1484bc46c9e06ab9038c8910e5b5789d994146d373b9","language":"plpgsql"},{"schema":"realtime","name":"settled_changes","oid":31081,"args":"slot_name name, max_changes integer, VARIADIC opts text[]","argtypes":"name, integer, text[]","prosrc":"\ndeclare\n  upto pg_lsn;\n  total bigint;\n  xids xid[];\n  starts bigint[];\n  snapshot pg_snapshot;\n  running_xids xid[];\n  xmax_age int;\n  cut bigint;\nbegin\n  -- Each statement in a volatile function takes its own snapshot, which is what lets the\n  -- check below see a writer that was still in flight when the peek ran. Under REPEATABLE\n  -- READ the snapshot never advances, so a deferred change would never be released.\n  if current_setting('transaction_isolation') <> 'read committed' then\n    raise exception 'realtime.settled_changes requires READ COMMITTED';\n  end if;\n\n  -- The peek and the read below cover the same WAL, so the read cannot reach a commit the\n  -- check never saw.\n  upto := pg_current_wal_flush_lsn();\n\n  -- One entry per transaction, in commit order: its xid and the position of its first\n  -- change. The peek uses the caller's own options, so max_changes counts exactly what the\n  -- read counts. A non-transactional logical message is emitted as soon as it is decoded,\n  -- tagged with the xid of whatever transaction wrote it, so it does not mark where that\n  -- transaction starts.\n  select coalesce(sum(g.n), 0),\n         array_agg(g.x order by g.first) filter (where g.first is not null),\n         array_agg(g.first order by g.first) filter (where g.first is not null)\n    into total, xids, starts\n    from (\n      select p.xid as x, count(*) as n,\n             min(p.ord) filter (where not case\n               when starts_with(p.data, '{\"action\":\"M\"') then (p.data::jsonb->>'transactional')::boolean is false\n               else false\n             end) as first\n      from pg_logical_slot_peek_changes(slot_name, upto, max_changes, variadic opts)\n           with ordinality as p(lsn, xid, data, ord)\n      group by p.xid\n    ) g;\n\n  -- Nothing for the caller, but the slot still has to move past what the peek covered.\n  if total = 0 then\n    perform pg_replication_slot_advance(slot_name, upto);\n    return;\n  end if;\n\n  if xids is not null then\n    -- Taken after the peek is materialized, so a writer that was still in flight during\n    -- decoding is guaranteed to show up here.\n    snapshot := pg_current_snapshot();\n\n    -- A commit record reaches the WAL before the writer leaves the proc array, so a change\n    -- can be decoded while its row is invisible. apply_rls would resolve a policy against a\n    -- row it cannot see and authorize it for nobody, while the read consumed it regardless.\n    --\n    -- xip lists transactions running when the snapshot was taken. It does not cover a writer\n    -- whose xid sits at or beyond xmax, which never appears there, so the horizon is checked\n    -- too. age() counts backwards from the current xid and so compares correctly across\n    -- wraparound.\n    select coalesce(array_agg(running.x::xid), array[]::xid[])\n      into running_xids\n      from pg_snapshot_xip(snapshot) running(x);\n    xmax_age := age(pg_snapshot_xmax(snapshot)::xid);\n\n    select min(u.s) into cut\n      from unnest(xids, starts) as u(x, s)\n      where u.x = any(running_xids) or age(u.x) <= xmax_age;\n  end if;\n\n  -- The read stops right after the commit that brings its count to upto_nchanges, so the\n  -- count of changes in front of the first unsettled transaction stops it just before that\n  -- transaction.\n  if cut is null then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, max_changes, variadic opts) p;\n  elsif cut > 1 then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, (cut - 1)::int, variadic opts) p;\n  end if;\nend;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.settled_changes(slot_name name, max_changes integer, VARIADIC opts text[])\n RETURNS TABLE(lsn pg_lsn, xid xid, data text)\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  upto pg_lsn;\n  total bigint;\n  xids xid[];\n  starts bigint[];\n  snapshot pg_snapshot;\n  running_xids xid[];\n  xmax_age int;\n  cut bigint;\nbegin\n  -- Each statement in a volatile function takes its own snapshot, which is what lets the\n  -- check below see a writer that was still in flight when the peek ran. Under REPEATABLE\n  -- READ the snapshot never advances, so a deferred change would never be released.\n  if current_setting('transaction_isolation') <> 'read committed' then\n    raise exception 'realtime.settled_changes requires READ COMMITTED';\n  end if;\n\n  -- The peek and the read below cover the same WAL, so the read cannot reach a commit the\n  -- check never saw.\n  upto := pg_current_wal_flush_lsn();\n\n  -- One entry per transaction, in commit order: its xid and the position of its first\n  -- change. The peek uses the caller's own options, so max_changes counts exactly what the\n  -- read counts. A non-transactional logical message is emitted as soon as it is decoded,\n  -- tagged with the xid of whatever transaction wrote it, so it does not mark where that\n  -- transaction starts.\n  select coalesce(sum(g.n), 0),\n         array_agg(g.x order by g.first) filter (where g.first is not null),\n         array_agg(g.first order by g.first) filter (where g.first is not null)\n    into total, xids, starts\n    from (\n      select p.xid as x, count(*) as n,\n             min(p.ord) filter (where not case\n               when starts_with(p.data, '{\"action\":\"M\"') then (p.data::jsonb->>'transactional')::boolean is false\n               else false\n             end) as first\n      from pg_logical_slot_peek_changes(slot_name, upto, max_changes, variadic opts)\n           with ordinality as p(lsn, xid, data, ord)\n      group by p.xid\n    ) g;\n\n  -- Nothing for the caller, but the slot still has to move past what the peek covered.\n  if total = 0 then\n    perform pg_replication_slot_advance(slot_name, upto);\n    return;\n  end if;\n\n  if xids is not null then\n    -- Taken after the peek is materialized, so a writer that was still in flight during\n    -- decoding is guaranteed to show up here.\n    snapshot := pg_current_snapshot();\n\n    -- A commit record reaches the WAL before the writer leaves the proc array, so a change\n    -- can be decoded while its row is invisible. apply_rls would resolve a policy against a\n    -- row it cannot see and authorize it for nobody, while the read consumed it regardless.\n    --\n    -- xip lists transactions running when the snapshot was taken. It does not cover a writer\n    -- whose xid sits at or beyond xmax, which never appears there, so the horizon is checked\n    -- too. age() counts backwards from the current xid and so compares correctly across\n    -- wraparound.\n    select coalesce(array_agg(running.x::xid), array[]::xid[])\n      into running_xids\n      from pg_snapshot_xip(snapshot) running(x);\n    xmax_age := age(pg_snapshot_xmax(snapshot)::xid);\n\n    select min(u.s) into cut\n      from unnest(xids, starts) as u(x, s)\n      where u.x = any(running_xids) or age(u.x) <= xmax_age;\n  end if;\n\n  -- The read stops right after the commit that brings its count to upto_nchanges, so the\n  -- count of changes in front of the first unsettled transaction stops it just before that\n  -- transaction.\n  if cut is null then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, max_changes, variadic opts) p;\n  elsif cut > 1 then\n    return query\n      select p.* from pg_logical_slot_get_changes(slot_name, upto, (cut - 1)::int, variadic opts) p;\n  end if;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"8831c33c7f0b09958580c075cf9ff1ca35f987f7a69cb5b0dde6fc8a4b357c72","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.settled_changes(name, integer, text[])","definition_sha256":"574f144f757a65d82f5ccb991162f4de4bad4deafc9917f559c59aac4703ebcc","language":"plpgsql"},{"schema":"realtime","name":"subscription_check_filters","oid":17195,"args":"","argtypes":"","prosrc":"\ndeclare\n    col_names text[] = coalesce(\n            array_agg(a.attname order by a.attnum),\n            '{}'::text[]\n        )\n        from\n            pg_catalog.pg_attribute a\n        where\n            a.attrelid = new.entity\n            and a.attnum > 0\n            and not a.attisdropped\n            and pg_catalog.has_column_privilege(\n                (new.claims ->> 'role'),\n                a.attrelid,\n                a.attnum,\n                'SELECT'\n            );\n    filter realtime.user_defined_filter;\n    col_type regtype;\n    in_val jsonb;\n    selected_col text;\nbegin\n    for filter in select * from unnest(new.filters) loop\n        if not filter.column_name = any(col_names) then\n            raise exception 'invalid column for filter %', filter.column_name;\n        end if;\n\n        col_type = (\n            select atttypid::regtype\n            from pg_catalog.pg_attribute\n            where attrelid = new.entity\n                  and attname = filter.column_name\n        );\n        if col_type is null then\n            raise exception 'failed to lookup type for column %', filter.column_name;\n        end if;\n\n        if filter.op = 'in'::realtime.equality_op then\n            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);\n            if coalesce(jsonb_array_length(in_val), 0) > 100 then\n                raise exception 'too many values for `in` filter. Maximum 100';\n            end if;\n        elsif filter.op = 'is'::realtime.equality_op then\n            -- `is` requires a keyword RHS rather than a typed literal\n            if filter.value not in ('null', 'true', 'false', 'unknown') then\n                raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n            end if;\n            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean\n            -- operand. Reject the non-null keywords on non-boolean columns here so they\n            -- don't abort apply_rls at WAL time.\n            if filter.value <> 'null' and col_type <> 'boolean'::regtype then\n                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;\n            end if;\n        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then\n            -- like/ilike apply the text pattern operator (~~); reject column types that\n            -- have no such operator instead of failing at WAL time\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = '~~' and oprleft = col_type\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then\n            -- match/imatch apply the regex operators ~ / ~*; reject column types that have\n            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the\n            -- like/ilike guard above.\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end\n                  and oprleft = col_type\n                  and oprright = col_type\n                  and oprresult = 'boolean'::regtype\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n            -- validate the regex eagerly so a bad pattern is rejected here, not inside\n            -- apply_rls where it would abort the WAL stream for the entity\n            begin\n                perform '' ~ filter.value;\n            exception when others then\n                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;\n            end;\n        else\n            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type\n            perform realtime.cast(filter.value, col_type);\n        end if;\n    end loop;\n\n    if new.selected_columns is not null then\n        for selected_col in select * from unnest(new.selected_columns) loop\n            if not selected_col = any(col_names) then\n                raise exception 'invalid column for select %', selected_col;\n            end if;\n        end loop;\n    end if;\n\n    -- Apply consistent order to filters so the unique constraint can't be tricked by a\n    -- different filter order. negate is part of the sort key.\n    new.filters = coalesce(\n        array_agg(f order by f.column_name, f.op, f.value, f.negate),\n        '{}'\n    ) from unnest(new.filters) f;\n\n    -- Normalize selected_columns order so ARRAY['a','b'] and ARRAY['b','a'] are treated\n    -- as the same subscription group in apply_rls. Preserve an empty array as '{}'\n    -- (\"primary keys only\") so it stays distinct from NULL (\"all columns\"); array_agg\n    -- over an empty set would otherwise collapse '{}' back to NULL.\n    if new.selected_columns is not null then\n        new.selected_columns = coalesce(\n            (\n                select array_agg(c order by c)\n                from unnest(new.selected_columns) c\n            ),\n            '{}'::text[]\n        );\n    end if;\n\n    return new;\nend;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION realtime.subscription_check_filters()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\ndeclare\n    col_names text[] = coalesce(\n            array_agg(a.attname order by a.attnum),\n            '{}'::text[]\n        )\n        from\n            pg_catalog.pg_attribute a\n        where\n            a.attrelid = new.entity\n            and a.attnum > 0\n            and not a.attisdropped\n            and pg_catalog.has_column_privilege(\n                (new.claims ->> 'role'),\n                a.attrelid,\n                a.attnum,\n                'SELECT'\n            );\n    filter realtime.user_defined_filter;\n    col_type regtype;\n    in_val jsonb;\n    selected_col text;\nbegin\n    for filter in select * from unnest(new.filters) loop\n        if not filter.column_name = any(col_names) then\n            raise exception 'invalid column for filter %', filter.column_name;\n        end if;\n\n        col_type = (\n            select atttypid::regtype\n            from pg_catalog.pg_attribute\n            where attrelid = new.entity\n                  and attname = filter.column_name\n        );\n        if col_type is null then\n            raise exception 'failed to lookup type for column %', filter.column_name;\n        end if;\n\n        if filter.op = 'in'::realtime.equality_op then\n            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);\n            if coalesce(jsonb_array_length(in_val), 0) > 100 then\n                raise exception 'too many values for `in` filter. Maximum 100';\n            end if;\n        elsif filter.op = 'is'::realtime.equality_op then\n            -- `is` requires a keyword RHS rather than a typed literal\n            if filter.value not in ('null', 'true', 'false', 'unknown') then\n                raise exception 'invalid value for is filter: must be null, true, false, or unknown';\n            end if;\n            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean\n            -- operand. Reject the non-null keywords on non-boolean columns here so they\n            -- don't abort apply_rls at WAL time.\n            if filter.value <> 'null' and col_type <> 'boolean'::regtype then\n                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;\n            end if;\n        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then\n            -- like/ilike apply the text pattern operator (~~); reject column types that\n            -- have no such operator instead of failing at WAL time\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = '~~' and oprleft = col_type\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then\n            -- match/imatch apply the regex operators ~ / ~*; reject column types that have\n            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the\n            -- like/ilike guard above.\n            if not exists (\n                select 1 from pg_catalog.pg_operator\n                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end\n                  and oprleft = col_type\n                  and oprright = col_type\n                  and oprresult = 'boolean'::regtype\n            ) then\n                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;\n            end if;\n            -- validate the regex eagerly so a bad pattern is rejected here, not inside\n            -- apply_rls where it would abort the WAL stream for the entity\n            begin\n                perform '' ~ filter.value;\n            exception when others then\n                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;\n            end;\n        else\n            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type\n            perform realtime.cast(filter.value, col_type);\n        end if;\n    end loop;\n\n    if new.selected_columns is not null then\n        for selected_col in select * from unnest(new.selected_columns) loop\n            if not selected_col = any(col_names) then\n                raise exception 'invalid column for select %', selected_col;\n            end if;\n        end loop;\n    end if;\n\n    -- Apply consistent order to filters so the unique constraint can't be tricked by a\n    -- different filter order. negate is part of the sort key.\n    new.filters = coalesce(\n        array_agg(f order by f.column_name, f.op, f.value, f.negate),\n        '{}'\n    ) from unnest(new.filters) f;\n\n    -- Normalize selected_columns order so ARRAY['a','b'] and ARRAY['b','a'] are treated\n    -- as the same subscription group in apply_rls. Preserve an empty array as '{}'\n    -- (\"primary keys only\") so it stays distinct from NULL (\"all columns\"); array_agg\n    -- over an empty set would otherwise collapse '{}' back to NULL.\n    if new.selected_columns is not null then\n        new.selected_columns = coalesce(\n            (\n                select array_agg(c order by c)\n                from unnest(new.selected_columns) c\n            ),\n            '{}'::text[]\n        );\n    end if;\n\n    return new;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"79974663c32161650cc2bb42bf5f6fa3523554bc4f1e9ad6b8defdccc7b63c5d","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.subscription_check_filters()","definition_sha256":"04b7909911732cf6f7ec12a9ab687ef3e0c74f0000c5fc4210c69c612b714038","language":"plpgsql"},{"schema":"realtime","name":"to_regrole","oid":17230,"args":"role_name text","argtypes":"text","prosrc":" select role_name::regrole ","probin":null,"rettype":"regrole","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.to_regrole(role_name text)\n RETURNS regrole\n LANGUAGE sql\n IMMUTABLE\nAS $function$ select role_name::regrole $function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"56b4ab5fdff47d1806306cb1f8dde976e6f412cd65e0b8a9786ed845fa98be50","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.to_regrole(text)","definition_sha256":"5b8fa2a5c1bbcbcc5ad4f32d3f2f5ead185baa2d1e06be61e90b4d1f921b3213","language":"sql"},{"schema":"realtime","name":"topic","oid":17313,"args":"","argtypes":"","prosrc":"\nselect nullif(current_setting('realtime.topic', true), '')::text;\n","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.topic()\n RETURNS text\n LANGUAGE sql\n STABLE\nAS $function$\nselect nullif(current_setting('realtime.topic', true), '')::text;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"c83907d2f7796a83d56ecc6f0cd6634c2ff2a34b25ef7f441c4c87b4ef755f24","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.topic()","definition_sha256":"c8a1609e4a106628e2b3eb7cdaa1e94c974c7765af29ccaa12baf99ae56a24be","language":"sql"},{"schema":"realtime","name":"wal2json_escape_identifier","oid":30092,"args":"name text","argtypes":"text","prosrc":"\n  -- Prefix `\\`, `,`, `.`, and any whitespace with `\\`\n  SELECT regexp_replace(name, '([\\\\,.[:space:]])', '\\\\\\1', 'g')\n","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION realtime.wal2json_escape_identifier(name text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\nAS $function$\n  -- Prefix `\\`, `,`, `.`, and any whitespace with `\\`\n  SELECT regexp_replace(name, '([\\\\,.[:space:]])', '\\\\\\1', 'g')\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":true,"parallel":"u","kind":"f","owner":"supabase_realtime_admin","sha256":"ed6c1cf784fef3a2c75c35712d12c59d2f0580b11205725e64481f8166279641","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"dashboard_user","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_realtime_admin","grantor":"supabase_realtime_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"realtime.wal2json_escape_identifier(text)","definition_sha256":"70417679bcf36d499a8332bd52246a185f52e53ea7e4c78e3b7d5891d73a81a0","language":"sql"},{"schema":"storage","name":"allow_any_operation","oid":27164,"args":"expected_operations text[]","argtypes":"text[]","prosrc":"\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT CASE\n      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n      ELSE raw_operation\n    END AS current_operation\n    FROM current_operation\n  )\n  SELECT EXISTS (\n    SELECT 1\n    FROM normalized n\n    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation\n    WHERE expected_operation IS NOT NULL\n      AND expected_operation <> ''\n      AND n.current_operation = CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END\n  );\n","probin":null,"rettype":"boolean","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION storage.allow_any_operation(expected_operations text[])\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT CASE\n      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n      ELSE raw_operation\n    END AS current_operation\n    FROM current_operation\n  )\n  SELECT EXISTS (\n    SELECT 1\n    FROM normalized n\n    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation\n    WHERE expected_operation IS NOT NULL\n      AND expected_operation <> ''\n      AND n.current_operation = CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END\n  );\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"c54409510ad2ecf68bd6b7da4a526f2d51ecba75d4ff6529dc6f1cc3a72774d6","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.allow_any_operation(text[])","definition_sha256":"a4ae3c8d1258ced584d91fed4bf7a9b0729937dd07cfe7d5fe45b2808a12b966","language":"sql"},{"schema":"storage","name":"allow_only_operation","oid":27163,"args":"expected_operation text","argtypes":"text","prosrc":"\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT\n      CASE\n        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n        ELSE raw_operation\n      END AS current_operation,\n      CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END AS requested_operation\n    FROM current_operation\n  )\n  SELECT CASE\n    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE\n    ELSE COALESCE(current_operation = requested_operation, FALSE)\n  END\n  FROM normalized;\n","probin":null,"rettype":"boolean","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION storage.allow_only_operation(expected_operation text)\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT\n      CASE\n        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)\n        ELSE raw_operation\n      END AS current_operation,\n      CASE\n        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END AS requested_operation\n    FROM current_operation\n  )\n  SELECT CASE\n    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE\n    ELSE COALESCE(current_operation = requested_operation, FALSE)\n  END\n  FROM normalized;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"45624f7fa4501401c00432192fe2edc9f6120c8ba03bd32b3337af3d638ed585","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.allow_only_operation(text)","definition_sha256":"a12f88ff4e00a9a63c24a93ea5b120e790be63a3555e840656c6525ff6dc0a85","language":"sql"},{"schema":"storage","name":"can_insert_object","oid":17396,"args":"bucketid text, name text, owner uuid, metadata jsonb","argtypes":"text, text, uuid, jsonb","prosrc":"\nBEGIN\n  INSERT INTO \"storage\".\"objects\" (\"bucket_id\", \"name\", \"owner\", \"metadata\") VALUES (bucketid, name, owner, metadata);\n  -- hack to rollback the successful insert\n  RAISE sqlstate 'PT200' using\n  message = 'ROLLBACK',\n  detail = 'rollback successful insert';\nEND\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  INSERT INTO \"storage\".\"objects\" (\"bucket_id\", \"name\", \"owner\", \"metadata\") VALUES (bucketid, name, owner, metadata);\n  -- hack to rollback the successful insert\n  RAISE sqlstate 'PT200' using\n  message = 'ROLLBACK',\n  detail = 'rollback successful insert';\nEND\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"5dcf529b998963363ab10076847d59c75ab5375a9c985de1257de5a092e8cce5","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.can_insert_object(text, text, uuid, jsonb)","definition_sha256":"d6a14645c2a2a394b759f3fb6bbbe5b67cceb6b8c4229a3e7e6c27e1f98c25cf","language":"plpgsql"},{"schema":"storage","name":"delete_lifecycle_objects","oid":31165,"args":"object_ids uuid[]","argtypes":"uuid[]","prosrc":"\nDECLARE\n    object_id uuid;\n    deleted_row storage.objects%ROWTYPE;\n    deleted_ids uuid[];\n    deleted_markers boolean[];\n    deleted_metadata jsonb[];\n    bulk_deleted boolean := false;\nBEGIN\n    -- Surface pre-existing deferred violations instead of treating them as blocked rows.\n    SET CONSTRAINTS ALL IMMEDIATE;\n    PERFORM set_config('storage.allow_delete_query', 'true', true);\n\n    -- One subxact keeps the subxid cache from overflowing; rows return only once it commits.\n    BEGIN\n        WITH deleted AS (\n            DELETE FROM storage.objects AS object_row\n              WHERE object_row.id = ANY(object_ids) AND object_row.archived_at IS NOT NULL\n              RETURNING object_row.id, object_row.is_delete_marker, object_row.metadata\n        )\n        SELECT array_agg(deleted.id), array_agg(deleted.is_delete_marker), array_agg(deleted.metadata)\n          INTO deleted_ids, deleted_markers, deleted_metadata\n          FROM deleted;\n        bulk_deleted := true;\n    EXCEPTION\n        WHEN OTHERS THEN\n            -- User triggers may use insufficient_privilege to block a row.\n            IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN\n                RAISE;\n            END IF;\n    END;\n    IF bulk_deleted THEN\n        RETURN QUERY SELECT * FROM unnest(deleted_ids, deleted_markers, deleted_metadata);\n        RETURN;\n    END IF;\n\n    FOREACH object_id IN ARRAY object_ids LOOP\n        BEGIN\n            DELETE FROM storage.objects AS object_row\n              WHERE object_row.id = object_id AND object_row.archived_at IS NOT NULL\n              RETURNING object_row.* INTO deleted_row;\n            IF FOUND THEN\n                id := deleted_row.id;\n                is_delete_marker := deleted_row.is_delete_marker;\n                metadata := deleted_row.metadata;\n                RETURN NEXT;\n            END IF;\n        EXCEPTION\n            WHEN OTHERS THEN\n                IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN\n                    RAISE;\n                END IF;\n        END;\n    END LOOP;\nEND;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.delete_lifecycle_objects(object_ids uuid[])\n RETURNS TABLE(id uuid, is_delete_marker boolean, metadata jsonb)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    object_id uuid;\n    deleted_row storage.objects%ROWTYPE;\n    deleted_ids uuid[];\n    deleted_markers boolean[];\n    deleted_metadata jsonb[];\n    bulk_deleted boolean := false;\nBEGIN\n    -- Surface pre-existing deferred violations instead of treating them as blocked rows.\n    SET CONSTRAINTS ALL IMMEDIATE;\n    PERFORM set_config('storage.allow_delete_query', 'true', true);\n\n    -- One subxact keeps the subxid cache from overflowing; rows return only once it commits.\n    BEGIN\n        WITH deleted AS (\n            DELETE FROM storage.objects AS object_row\n              WHERE object_row.id = ANY(object_ids) AND object_row.archived_at IS NOT NULL\n              RETURNING object_row.id, object_row.is_delete_marker, object_row.metadata\n        )\n        SELECT array_agg(deleted.id), array_agg(deleted.is_delete_marker), array_agg(deleted.metadata)\n          INTO deleted_ids, deleted_markers, deleted_metadata\n          FROM deleted;\n        bulk_deleted := true;\n    EXCEPTION\n        WHEN OTHERS THEN\n            -- User triggers may use insufficient_privilege to block a row.\n            IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN\n                RAISE;\n            END IF;\n    END;\n    IF bulk_deleted THEN\n        RETURN QUERY SELECT * FROM unnest(deleted_ids, deleted_markers, deleted_metadata);\n        RETURN;\n    END IF;\n\n    FOREACH object_id IN ARRAY object_ids LOOP\n        BEGIN\n            DELETE FROM storage.objects AS object_row\n              WHERE object_row.id = object_id AND object_row.archived_at IS NOT NULL\n              RETURNING object_row.* INTO deleted_row;\n            IF FOUND THEN\n                id := deleted_row.id;\n                is_delete_marker := deleted_row.is_delete_marker;\n                metadata := deleted_row.metadata;\n                RETURN NEXT;\n            END IF;\n        EXCEPTION\n            WHEN OTHERS THEN\n                IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN\n                    RAISE;\n                END IF;\n        END;\n    END LOOP;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"08efc3d2139136160d1bd2d03b2ef61c9550afa62b5580e194b899cf160fbd8f","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"service_role","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.delete_lifecycle_objects(uuid[])","definition_sha256":"9d7bbab2a82a1c05603f8b21ce4d6be6e360cd0b5c5051906d917367a7c8b3ff","language":"plpgsql"},{"schema":"storage","name":"enforce_bucket_lifecycle_service_role","oid":30943,"args":"","argtypes":"","prosrc":"\nBEGIN\n  IF current_user::text IS DISTINCT FROM TG_ARGV[0] THEN\n    -- Keep this check AFTER caller RLS accepts the proposed row. The API\n    -- recognizes this exact signal after rolling back its permission probe.\n    RAISE EXCEPTION 'bucket control columns may only be changed by the configured storage service role'\n      USING ERRCODE = 'PST01',\n            SCHEMA = TG_TABLE_SCHEMA,\n            TABLE = TG_TABLE_NAME,\n            CONSTRAINT = TG_NAME;\n  END IF;\n\n  RETURN NULL;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.enforce_bucket_lifecycle_service_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF current_user::text IS DISTINCT FROM TG_ARGV[0] THEN\n    -- Keep this check AFTER caller RLS accepts the proposed row. The API\n    -- recognizes this exact signal after rolling back its permission probe.\n    RAISE EXCEPTION 'bucket control columns may only be changed by the configured storage service role'\n      USING ERRCODE = 'PST01',\n            SCHEMA = TG_TABLE_SCHEMA,\n            TABLE = TG_TABLE_NAME,\n            CONSTRAINT = TG_NAME;\n  END IF;\n\n  RETURN NULL;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"ca7f86c32124fc169647a3981ae27536e840480f9c2e027052a7cb241e1c8660","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.enforce_bucket_lifecycle_service_role()","definition_sha256":"fdd55e982e6d2a9faad74280b7dd80bf8c069f34243eea6036759ea6a58607b7","language":"plpgsql"},{"schema":"storage","name":"enforce_bucket_name_length","oid":17452,"args":"","argtypes":"","prosrc":"\nbegin\n    if length(new.name) > 100 then\n        raise exception 'bucket name \"%\" is too long (% characters). Max is 100.', new.name, length(new.name);\n    end if;\n    return new;\nend;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n    if length(new.name) > 100 then\n        raise exception 'bucket name \"%\" is too long (% characters). Max is 100.', new.name, length(new.name);\n    end if;\n    return new;\nend;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"d74080b4723b1dd1d9fed40ff69d0ddeccb3b2cff0270cb5341bdf1331a5305e","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.enforce_bucket_name_length()","definition_sha256":"bf9dcf9beab8062d27f9f6f5db850fac0c22423d6d62d31a3fe9622b1244336e","language":"plpgsql"},{"schema":"storage","name":"enforce_versioning_status_transition","oid":31088,"args":"","argtypes":"","prosrc":"\nBEGIN\n    IF NEW.versioning_status = OLD.versioning_status THEN\n        RETURN NEW;\n    END IF;\n\n    IF NEW.versioning_status = 'DISABLED' OR\n       (OLD.versioning_status = 'DISABLED' AND NEW.versioning_status = 'SUSPENDED') THEN\n        RAISE EXCEPTION 'Cannot transition bucket versioning status from % to %',\n            OLD.versioning_status, NEW.versioning_status;\n    END IF;\n\n    RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.enforce_versioning_status_transition()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF NEW.versioning_status = OLD.versioning_status THEN\n        RETURN NEW;\n    END IF;\n\n    IF NEW.versioning_status = 'DISABLED' OR\n       (OLD.versioning_status = 'DISABLED' AND NEW.versioning_status = 'SUSPENDED') THEN\n        RAISE EXCEPTION 'Cannot transition bucket versioning status from % to %',\n            OLD.versioning_status, NEW.versioning_status;\n    END IF;\n\n    RETURN NEW;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"7acc27abc9a7b7d0a54fe179f98c5297d34424207a635684c5ddaaa6597baf9e","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.enforce_versioning_status_transition()","definition_sha256":"fcd699a13272ce769d3a94322d3a150562ea8c6fd191018e025f67815776fff5","language":"plpgsql"},{"schema":"storage","name":"extension","oid":17371,"args":"name text","argtypes":"text","prosrc":"\nDECLARE\n    _parts text[];\n    _filename text;\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Get the last path segment (the actual filename)\n    SELECT _parts[array_length(_parts, 1)] INTO _filename;\n    -- Extract extension: reverse, split on '.', then reverse again\n    RETURN reverse(split_part(reverse(_filename), '.', 1));\nEND\n","probin":null,"rettype":"text","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.extension(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\n    _filename text;\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Get the last path segment (the actual filename)\n    SELECT _parts[array_length(_parts, 1)] INTO _filename;\n    -- Extract extension: reverse, split on '.', then reverse again\n    RETURN reverse(split_part(reverse(_filename), '.', 1));\nEND\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"abf26536e5ecb9bee4b0b469066a2dc65e6c8f6f87f1a57111fac8e3451e3173","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.extension(text)","definition_sha256":"839c088c388a275fdfd10d7d909f12b55e643c8ba8a2c6ef674b62c641113b94","language":"plpgsql"},{"schema":"storage","name":"filename","oid":17370,"args":"name text","argtypes":"text","prosrc":"\nDECLARE\n    _parts text[];\nBEGIN\n    SELECT string_to_array(name, '/') INTO _parts;\n    RETURN _parts[array_length(_parts, 1)];\nEND\n","probin":null,"rettype":"text","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.filename(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    SELECT string_to_array(name, '/') INTO _parts;\n    RETURN _parts[array_length(_parts, 1)];\nEND\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"5681c1616a04907be58b574647e7e8e139b1e69ae93096963b8c8739221fc45d","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.filename(text)","definition_sha256":"6616e7416f58bfe6bcb2a58f1da44477d79e1383430a958dd6b2b854668817f0","language":"plpgsql"},{"schema":"storage","name":"foldername","oid":17369,"args":"name text","argtypes":"text","prosrc":"\nDECLARE\n    _parts text[];\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Return everything except the last segment\n    RETURN _parts[1 : array_length(_parts,1) - 1];\nEND\n","probin":null,"rettype":"text[]","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.foldername(name text)\n RETURNS text[]\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, '/') INTO _parts;\n    -- Return everything except the last segment\n    RETURN _parts[1 : array_length(_parts,1) - 1];\nEND\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"384486b1018b018371dd88bba71bab03d817763a53b39efa157d527d4813d5bf","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.foldername(text)","definition_sha256":"a673a01626cb42e9eb507eb18e4cb038ce5db1da875a22e254df2ebb597bd2bc","language":"plpgsql"},{"schema":"storage","name":"get_common_prefix","oid":17508,"args":"p_key text, p_prefix text, p_delimiter text","argtypes":"text, text, text","prosrc":"\nSELECT CASE\n    WHEN p_delimiter <> ''\n         AND position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0\n    THEN left(\n        p_key,\n        length(p_prefix)\n            + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1))\n            + length(p_delimiter) - 1\n    )\n    ELSE NULL\nEND;\n","probin":null,"rettype":"text","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\nSELECT CASE\n    WHEN p_delimiter <> ''\n         AND position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0\n    THEN left(\n        p_key,\n        length(p_prefix)\n            + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1))\n            + length(p_delimiter) - 1\n    )\n    ELSE NULL\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"f448f711cf96ce249a0c5538864551736207df28be6d819da7b33a971ced2c88","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.get_common_prefix(text, text, text)","definition_sha256":"62810fa1178c7e748df4393fca51900b36841187fcbcfa79740d45ea54b4357d","language":"sql"},{"schema":"storage","name":"get_size_by_bucket","oid":30955,"args":"noncurrent_versions text, delete_markers text","argtypes":"text, text","prosrc":"\nBEGIN\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'include');\n    delete_markers := COALESCE(delete_markers, 'include');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'include';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'include';\n    END IF;\n\n    return query\n        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id\n        from \"storage\".objects as obj\n        where (noncurrent_versions != 'exclude' OR obj.archived_at IS NULL)\n          and (noncurrent_versions != 'only' OR obj.archived_at IS NOT NULL)\n          and (delete_markers != 'exclude' OR NOT obj.is_delete_marker)\n          and (delete_markers != 'only' OR obj.is_delete_marker)\n        group by obj.bucket_id;\nEND\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.get_size_by_bucket(noncurrent_versions text DEFAULT 'include'::text, delete_markers text DEFAULT 'include'::text)\n RETURNS TABLE(size bigint, bucket_id text)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'include');\n    delete_markers := COALESCE(delete_markers, 'include');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'include';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'include';\n    END IF;\n\n    return query\n        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id\n        from \"storage\".objects as obj\n        where (noncurrent_versions != 'exclude' OR obj.archived_at IS NULL)\n          and (noncurrent_versions != 'only' OR obj.archived_at IS NOT NULL)\n          and (delete_markers != 'exclude' OR NOT obj.is_delete_marker)\n          and (delete_markers != 'only' OR obj.is_delete_marker)\n        group by obj.bucket_id;\nEND\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"6951e3cf56a231f7f3af0cfa1abadcac736a02e88a11a1df75395da4a23b5429","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.get_size_by_bucket(text, text)","definition_sha256":"25ec89ec6e8b55554c0403487a7f83f9331d13b3a01d1f5e44d56857cec8476e","language":"plpgsql"},{"schema":"storage","name":"list_multipart_uploads_with_delimiter","oid":30947,"args":"bucket_id text, prefix_param text, delimiter_param text, max_keys integer, next_key_token text, next_upload_token text, raw_prefix_param text","argtypes":"text, text, text, integer, text, text, text","prosrc":"\nWITH candidates AS (\n    SELECT\n        upload.key AS object_key,\n        CASE\n            WHEN position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0\n            THEN left(\n                upload.key,\n                length(coalesce($7, $2))\n                    + position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1))\n                    + length($3) - 1\n            )\n            ELSE upload.key\n        END AS result_key,\n        upload.id,\n        upload.created_at,\n        position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0 AS is_common_prefix\n    FROM storage.s3_multipart_uploads AS upload\n    WHERE upload.bucket_id = $1\n      AND upload.key COLLATE \"C\" LIKE $2 || '%'\n), filtered AS (\n    SELECT candidate.*\n    FROM candidates AS candidate\n    WHERE $5 = ''\n       OR candidate.result_key COLLATE \"C\" > $5\n       OR (\n           candidate.result_key COLLATE \"C\" = $5\n           AND NOT candidate.is_common_prefix\n           AND $6 <> ''\n           -- A completed or aborted marker repeats the remaining same-key uploads.\n           AND COALESCE(\n               (candidate.created_at, candidate.id COLLATE \"C\") > (\n                   SELECT marker.created_at, marker.id COLLATE \"C\"\n                   FROM storage.s3_multipart_uploads AS marker\n                   WHERE marker.bucket_id = $1\n                     AND marker.key COLLATE \"C\" = $5\n                     AND marker.id = $6\n               ),\n               TRUE\n           )\n       )\n), ranked AS (\n    SELECT\n        filtered.*,\n        row_number() OVER (\n            PARTITION BY filtered.result_key COLLATE \"C\"\n            ORDER BY filtered.created_at, filtered.id COLLATE \"C\"\n        ) AS prefix_rank\n    FROM filtered\n)\nSELECT ranked.result_key, ranked.id, ranked.created_at\nFROM ranked\nWHERE NOT ranked.is_common_prefix OR ranked.prefix_rank = 1\nORDER BY ranked.result_key COLLATE \"C\", ranked.created_at, ranked.id COLLATE \"C\"\nLIMIT $4;\n","probin":null,"rettype":"record","language_oid":"14","definition":"CREATE OR REPLACE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text, raw_prefix_param text DEFAULT NULL::text)\n RETURNS TABLE(key text, id text, created_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\nWITH candidates AS (\n    SELECT\n        upload.key AS object_key,\n        CASE\n            WHEN position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0\n            THEN left(\n                upload.key,\n                length(coalesce($7, $2))\n                    + position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1))\n                    + length($3) - 1\n            )\n            ELSE upload.key\n        END AS result_key,\n        upload.id,\n        upload.created_at,\n        position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0 AS is_common_prefix\n    FROM storage.s3_multipart_uploads AS upload\n    WHERE upload.bucket_id = $1\n      AND upload.key COLLATE \"C\" LIKE $2 || '%'\n), filtered AS (\n    SELECT candidate.*\n    FROM candidates AS candidate\n    WHERE $5 = ''\n       OR candidate.result_key COLLATE \"C\" > $5\n       OR (\n           candidate.result_key COLLATE \"C\" = $5\n           AND NOT candidate.is_common_prefix\n           AND $6 <> ''\n           -- A completed or aborted marker repeats the remaining same-key uploads.\n           AND COALESCE(\n               (candidate.created_at, candidate.id COLLATE \"C\") > (\n                   SELECT marker.created_at, marker.id COLLATE \"C\"\n                   FROM storage.s3_multipart_uploads AS marker\n                   WHERE marker.bucket_id = $1\n                     AND marker.key COLLATE \"C\" = $5\n                     AND marker.id = $6\n               ),\n               TRUE\n           )\n       )\n), ranked AS (\n    SELECT\n        filtered.*,\n        row_number() OVER (\n            PARTITION BY filtered.result_key COLLATE \"C\"\n            ORDER BY filtered.created_at, filtered.id COLLATE \"C\"\n        ) AS prefix_rank\n    FROM filtered\n)\nSELECT ranked.result_key, ranked.id, ranked.created_at\nFROM ranked\nWHERE NOT ranked.is_common_prefix OR ranked.prefix_rank = 1\nORDER BY ranked.result_key COLLATE \"C\", ranked.created_at, ranked.id COLLATE \"C\"\nLIMIT $4;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"3a258743d6e4e45c5b59733d3f787a5e5cc65c89eaa691d6962434a42fe54563","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.list_multipart_uploads_with_delimiter(text, text, text, integer, text, text, text)","definition_sha256":"80bf7eb30e8b8b54536a0fbcc34f0da11310c375d56d358ca591d9e675e1e30e","language":"sql"},{"schema":"storage","name":"list_objects_with_delimiter","oid":30948,"args":"_bucket_id text, prefix_param text, delimiter_param text, max_keys integer, start_after text, next_token text, sort_order text, noncurrent_versions text, delete_markers text, next_token_archived_at timestamp with time zone, next_token_version text","argtypes":"text, text, text, integer, text, text, text, text, text, timestamp with time zone, text","prosrc":"\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n\n    -- Configuration\n    v_is_asc BOOLEAN;\n    v_prefix TEXT;\n    v_start TEXT;\n    v_start_relative TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n\n    -- true when noncurrent_versions can return >1 row per name; keeps them\n    -- ordered most-recent-first and lets pagination resume mid-key\n    v_multi_row BOOLEAN;\n    v_name_order TEXT;\n    v_exact_range_predicate TEXT;\n    v_strict_range_predicate TEXT;\n    v_inclusive_range_predicate TEXT;\n\n    -- Seek state for the current name. archived_at is normalized to JavaScript's\n    -- millisecond precision and version breaks ties within the same millisecond.\n    -- Current rows use 'infinity'; NULL means no tiebreak has been established.\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_cursor_is_folder BOOLEAN;\n    v_count INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_batch_query_strict TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';\n    v_prefix := coalesce(prefix_param, '');\n    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;\n    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n    v_name_order := CASE WHEN v_is_asc THEN 'ASC' ELSE 'DESC' END;\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE \"C\")\n    IF v_prefix = '' THEN\n        v_upper_bound := NULL;\n    ELSE\n        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);\n    END IF;\n\n    -- Keep caller-provided cursors inside the requested prefix range.\n    IF v_start <> '' AND v_upper_bound IS NOT NULL THEN\n        IF v_is_asc THEN\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                v_start := '';\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                RETURN;\n            END IF;\n        ELSE\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                RETURN;\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                v_start := '';\n            END IF;\n        END IF;\n    END IF;\n\n    v_start_relative := substring(v_start FROM length(v_prefix) + 1);\n\n    -- Direction affects only the indexed name range and its ordering. Cursor\n    -- state transitions and within-key version ordering stay shared.\n    IF v_is_asc THEN\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" > $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" >= $2';\n        IF v_upper_bound IS NOT NULL THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" < $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n        END IF;\n    ELSE\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" < $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" < $2';\n        IF v_prefix <> '' THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" >= $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n        END IF;\n    END IF;\n\n    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)\n    -- The multi-row order matches the externally serialized cursor exactly:\n    -- archived_at at millisecond precision, then version as the final tiebreak.\n    --\n    -- When v_multi_row, the seek is a keyset tuple comparison (\"name > $2 OR\n    -- (name = $2 AND tiebreak)\") - Postgres won't split that OR into indexable\n    -- form (confirmed even with fully literal values), so as one WHERE clause\n    -- it forces a full bucket scan filtered row-by-row. Splitting it into two\n    -- independently-indexable branches (exact name match with the tiebreak\n    -- filter, vs. strictly-past names) combined with UNION ALL lets each\n    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT\n    -- re-merges them into the same page the single query used to produce.\n    IF v_multi_row THEN\n        v_batch_query := format(\n            $sql$\n            SELECT *\n            FROM (\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND o.name COLLATE \"C\" = $2\n                      AND %s\n                      AND NOT $7::boolean\n                      AND (\n                          $5::timestamptz IS NULL\n                          OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < $5\n                          OR (\n                              COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = $5\n                              AND COALESCE(o.version, '') > $6\n                          )\n                      )\n                      %s\n                    ORDER BY\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n                UNION ALL\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND %s\n                      %s\n                    ORDER BY\n                        o.name COLLATE \"C\" %s,\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n            ) sub\n            ORDER BY\n                sub.name COLLATE \"C\" %s,\n                COALESCE(date_trunc('milliseconds', sub.archived_at), 'infinity'::timestamptz) DESC,\n                COALESCE(sub.version, '') ASC\n            LIMIT $4\n            $sql$,\n            v_exact_range_predicate,\n            v_version_filter,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order,\n            v_name_order\n        );\n    ELSE\n        v_batch_query := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_inclusive_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n\n        -- Strict counterpart of the query above: used once the single-row\n        -- ASC batch advance (below) has left v_next_seek pointing at the\n        -- last row already emitted, so an inclusive predicate would\n        -- re-match it forever. Only single-row mode ever sets strict mode,\n        -- so this variant is never needed when v_multi_row.\n        v_batch_query_strict := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n    END IF;\n\n    -- The static peek predicates cannot use the partial delete-marker index\n    -- once PL/pgSQL switches to a generic plan because whether\n    -- is_delete_marker is required remains parameter-dependent. Reuse the\n    -- already-specialized batch query with a one-row limit for this sparse\n    -- filter so the plan sees a literal `o.is_delete_marker` predicate.\n    IF delete_markers = 'only' THEN\n        v_delete_marker_peek_query :=\n            'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        IF NOT v_multi_row THEN\n            v_delete_marker_peek_query_strict :=\n                'SELECT marker_page.name FROM (' || v_batch_query_strict || ') marker_page LIMIT 1';\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- SEEK INITIALIZATION: Determine starting position\n    -- ========================================================================\n    IF v_start = '' THEN\n        IF v_is_asc THEN\n            v_next_seek := v_prefix;\n        ELSE\n            -- DESC without cursor performs one specialized initial seek so\n            -- partial current-version and delete-marker indexes remain available.\n            EXECUTE format(\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE \"C\" DESC LIMIT 1',\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND o.name COLLATE \"C\" >= $2 AND o.name COLLATE \"C\" < $3'\n                    ELSE ''\n                END,\n                v_version_filter\n            )\n            INTO v_next_seek\n            USING _bucket_id, v_prefix, v_upper_bound;\n\n            IF v_next_seek IS NOT NULL THEN\n                v_next_seek := v_next_seek || delimiter_param;\n            ELSE\n                RETURN;\n            END IF;\n        END IF;\n    ELSE\n        -- Folder continuation tokens retain their trailing delimiter. A\n        -- delimiter-less startAfter is always a literal key boundary.\n        v_cursor_is_folder := delimiter_param <> ''\n            AND v_start_relative <> ''\n            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;\n\n        IF v_cursor_is_folder THEN\n            v_next_seek := CASE\n                WHEN right(v_start, length(delimiter_param)) = delimiter_param\n                    THEN v_start\n                ELSE v_start || delimiter_param\n            END;\n            IF v_is_asc THEN\n                v_next_seek := left(v_next_seek, -1)\n                    || chr(ascii(right(v_next_seek, 1)) + 1);\n            END IF;\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- leaf object: when v_multi_row, stay on v_start with the\n            -- caller-supplied tiebreak so a page boundary mid-key resumes\n            -- that key's remaining rows instead of skipping them. Truncate\n            -- to milliseconds like every other v_next_seek_at assignment -\n            -- harmless today since object.ts's cursor always round-trips\n            -- through JS Date first, but this shouldn't rely on that.\n            IF v_multi_row THEN\n                v_next_seek := v_start;\n                v_next_seek_at := date_trunc('milliseconds', next_token_archived_at);\n                v_next_seek_version := coalesce(next_token_version, '');\n                v_next_seek_strict := coalesce(next_token, '') = '';\n            ELSIF v_is_asc THEN\n                v_next_seek := v_start;\n                v_next_seek_strict := true;\n            ELSE\n                v_next_seek := v_start;\n            END IF;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= max_keys;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n\n        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)\n        -- v_multi_row is branched here (rather than folded into the WHERE\n        -- clause as a bound parameter) so each concrete query keeps an\n        -- unconditional seek predicate - once PL/pgSQL switches to its\n        -- cached generic plan (after 5 calls), a parameter-gated\n        -- \"(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)\"\n        -- predicate stops the planner from using name as an index\n        -- condition at all, degrading every subsequent peek to a full\n        -- index scan filtered row-by-row instead of a bounded range scan.\n        -- v_multi_row's seek predicate is a keyset tuple comparison\n        -- (\"name > x OR (name = x AND tiebreak)\") - Postgres does not\n        -- split this OR into indexable form even with fully literal\n        -- values, so it falls back to a full scan filtered row-by-row.\n        -- Splitting it into two independently-indexable branches (exact\n        -- name match with the tiebreak filter, vs. strictly-past name)\n        -- combined with UNION ALL lets each branch keep name as a real\n        -- index condition; the outer ORDER BY/LIMIT picks whichever of\n        -- the (at most 2) rows sorts first.\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING _bucket_id, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,\n                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;\n        ELSIF v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" < v_upper_bound\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek AND o.name COLLATE \"C\" < v_upper_bound\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" >= v_prefix\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek AND o.name COLLATE \"C\" >= v_prefix\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        ELSE\n            -- Single-row mode is always noncurrent_versions='exclude'. Keep\n            -- this predicate literal so generic plans use the current index.\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.name COLLATE \"C\" >= v_prefix\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Emit and skip to next folder (no heap access needed)\n            name := v_common_prefix;\n            id := NULL;\n            updated_at := NULL;\n            created_at := NULL;\n            last_accessed_at := NULL;\n            metadata := NULL;\n            version := NULL;\n            archived_at := NULL;\n            is_delete_marker := NULL;\n            is_versioned := NULL;\n            RETURN NEXT;\n            v_count := v_count + 1;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := left(v_common_prefix, -1)\n                    || chr(ascii(right(v_common_prefix, 1)) + 1);\n            ELSE\n                v_next_seek := v_common_prefix;\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END\n                USING _bucket_id, v_next_seek,\n                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,\n                v_next_seek_strict\n            LOOP\n                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN v_current.name\n                        ELSE v_current.name || delimiter_param\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Emit file\n                name := v_current.name;\n                id := v_current.id;\n                updated_at := v_current.updated_at;\n                created_at := v_current.created_at;\n                last_accessed_at := v_current.last_accessed_at;\n                metadata := v_current.metadata;\n                version := v_current.version;\n                archived_at := v_current.archived_at;\n                is_delete_marker := v_current.is_delete_marker;\n                is_versioned := v_current.is_versioned;\n                RETURN NEXT;\n                v_count := v_count + 1;\n\n                -- when v_multi_row, stay on this name and record its\n                -- archived_at as the new tiebreak so remaining rows for the\n                -- same key are picked up before moving to the next name\n                IF v_multi_row THEN\n                    v_next_seek := v_current.name;\n                    v_next_seek_at := COALESCE(date_trunc('milliseconds', v_current.archived_at), 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                    v_next_seek_strict := false;\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor\n                    -- would skip a real key like `name || '!'` (or any\n                    -- character sorting below the delimiter), which sorts\n                    -- between `name` and `name || delimiter`. Track the real\n                    -- name and mark the next comparison strict instead.\n                    v_next_seek := v_current.name;\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := v_current.name;\n                END IF;\n\n                EXIT WHEN v_count >= max_keys;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.list_objects_with_delimiter made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''::text)\n RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n\n    -- Configuration\n    v_is_asc BOOLEAN;\n    v_prefix TEXT;\n    v_start TEXT;\n    v_start_relative TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n\n    -- true when noncurrent_versions can return >1 row per name; keeps them\n    -- ordered most-recent-first and lets pagination resume mid-key\n    v_multi_row BOOLEAN;\n    v_name_order TEXT;\n    v_exact_range_predicate TEXT;\n    v_strict_range_predicate TEXT;\n    v_inclusive_range_predicate TEXT;\n\n    -- Seek state for the current name. archived_at is normalized to JavaScript's\n    -- millisecond precision and version breaks ties within the same millisecond.\n    -- Current rows use 'infinity'; NULL means no tiebreak has been established.\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_cursor_is_folder BOOLEAN;\n    v_count INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_batch_query_strict TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';\n    v_prefix := coalesce(prefix_param, '');\n    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;\n    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n    v_name_order := CASE WHEN v_is_asc THEN 'ASC' ELSE 'DESC' END;\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE \"C\")\n    IF v_prefix = '' THEN\n        v_upper_bound := NULL;\n    ELSE\n        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);\n    END IF;\n\n    -- Keep caller-provided cursors inside the requested prefix range.\n    IF v_start <> '' AND v_upper_bound IS NOT NULL THEN\n        IF v_is_asc THEN\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                v_start := '';\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                RETURN;\n            END IF;\n        ELSE\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                RETURN;\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                v_start := '';\n            END IF;\n        END IF;\n    END IF;\n\n    v_start_relative := substring(v_start FROM length(v_prefix) + 1);\n\n    -- Direction affects only the indexed name range and its ordering. Cursor\n    -- state transitions and within-key version ordering stay shared.\n    IF v_is_asc THEN\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" > $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" >= $2';\n        IF v_upper_bound IS NOT NULL THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" < $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" < $3';\n        END IF;\n    ELSE\n        v_exact_range_predicate := 'TRUE';\n        v_strict_range_predicate := 'o.name COLLATE \"C\" < $2';\n        v_inclusive_range_predicate := 'o.name COLLATE \"C\" < $2';\n        IF v_prefix <> '' THEN\n            v_exact_range_predicate := 'o.name COLLATE \"C\" >= $3';\n            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE \"C\" >= $3';\n        END IF;\n    END IF;\n\n    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)\n    -- The multi-row order matches the externally serialized cursor exactly:\n    -- archived_at at millisecond precision, then version as the final tiebreak.\n    --\n    -- When v_multi_row, the seek is a keyset tuple comparison (\"name > $2 OR\n    -- (name = $2 AND tiebreak)\") - Postgres won't split that OR into indexable\n    -- form (confirmed even with fully literal values), so as one WHERE clause\n    -- it forces a full bucket scan filtered row-by-row. Splitting it into two\n    -- independently-indexable branches (exact name match with the tiebreak\n    -- filter, vs. strictly-past names) combined with UNION ALL lets each\n    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT\n    -- re-merges them into the same page the single query used to produce.\n    IF v_multi_row THEN\n        v_batch_query := format(\n            $sql$\n            SELECT *\n            FROM (\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND o.name COLLATE \"C\" = $2\n                      AND %s\n                      AND NOT $7::boolean\n                      AND (\n                          $5::timestamptz IS NULL\n                          OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < $5\n                          OR (\n                              COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = $5\n                              AND COALESCE(o.version, '') > $6\n                          )\n                      )\n                      %s\n                    ORDER BY\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n                UNION ALL\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND %s\n                      %s\n                    ORDER BY\n                        o.name COLLATE \"C\" %s,\n                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,\n                        COALESCE(o.version, '') ASC\n                    LIMIT $4\n                )\n            ) sub\n            ORDER BY\n                sub.name COLLATE \"C\" %s,\n                COALESCE(date_trunc('milliseconds', sub.archived_at), 'infinity'::timestamptz) DESC,\n                COALESCE(sub.version, '') ASC\n            LIMIT $4\n            $sql$,\n            v_exact_range_predicate,\n            v_version_filter,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order,\n            v_name_order\n        );\n    ELSE\n        v_batch_query := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_inclusive_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n\n        -- Strict counterpart of the query above: used once the single-row\n        -- ASC batch advance (below) has left v_next_seek pointing at the\n        -- last row already emitted, so an inclusive predicate would\n        -- re-match it forever. Only single-row mode ever sets strict mode,\n        -- so this variant is never needed when v_multi_row.\n        v_batch_query_strict := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n    END IF;\n\n    -- The static peek predicates cannot use the partial delete-marker index\n    -- once PL/pgSQL switches to a generic plan because whether\n    -- is_delete_marker is required remains parameter-dependent. Reuse the\n    -- already-specialized batch query with a one-row limit for this sparse\n    -- filter so the plan sees a literal `o.is_delete_marker` predicate.\n    IF delete_markers = 'only' THEN\n        v_delete_marker_peek_query :=\n            'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        IF NOT v_multi_row THEN\n            v_delete_marker_peek_query_strict :=\n                'SELECT marker_page.name FROM (' || v_batch_query_strict || ') marker_page LIMIT 1';\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- SEEK INITIALIZATION: Determine starting position\n    -- ========================================================================\n    IF v_start = '' THEN\n        IF v_is_asc THEN\n            v_next_seek := v_prefix;\n        ELSE\n            -- DESC without cursor performs one specialized initial seek so\n            -- partial current-version and delete-marker indexes remain available.\n            EXECUTE format(\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE \"C\" DESC LIMIT 1',\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND o.name COLLATE \"C\" >= $2 AND o.name COLLATE \"C\" < $3'\n                    ELSE ''\n                END,\n                v_version_filter\n            )\n            INTO v_next_seek\n            USING _bucket_id, v_prefix, v_upper_bound;\n\n            IF v_next_seek IS NOT NULL THEN\n                v_next_seek := v_next_seek || delimiter_param;\n            ELSE\n                RETURN;\n            END IF;\n        END IF;\n    ELSE\n        -- Folder continuation tokens retain their trailing delimiter. A\n        -- delimiter-less startAfter is always a literal key boundary.\n        v_cursor_is_folder := delimiter_param <> ''\n            AND v_start_relative <> ''\n            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;\n\n        IF v_cursor_is_folder THEN\n            v_next_seek := CASE\n                WHEN right(v_start, length(delimiter_param)) = delimiter_param\n                    THEN v_start\n                ELSE v_start || delimiter_param\n            END;\n            IF v_is_asc THEN\n                v_next_seek := left(v_next_seek, -1)\n                    || chr(ascii(right(v_next_seek, 1)) + 1);\n            END IF;\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- leaf object: when v_multi_row, stay on v_start with the\n            -- caller-supplied tiebreak so a page boundary mid-key resumes\n            -- that key's remaining rows instead of skipping them. Truncate\n            -- to milliseconds like every other v_next_seek_at assignment -\n            -- harmless today since object.ts's cursor always round-trips\n            -- through JS Date first, but this shouldn't rely on that.\n            IF v_multi_row THEN\n                v_next_seek := v_start;\n                v_next_seek_at := date_trunc('milliseconds', next_token_archived_at);\n                v_next_seek_version := coalesce(next_token_version, '');\n                v_next_seek_strict := coalesce(next_token, '') = '';\n            ELSIF v_is_asc THEN\n                v_next_seek := v_start;\n                v_next_seek_strict := true;\n            ELSE\n                v_next_seek := v_start;\n            END IF;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= max_keys;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n\n        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)\n        -- v_multi_row is branched here (rather than folded into the WHERE\n        -- clause as a bound parameter) so each concrete query keeps an\n        -- unconditional seek predicate - once PL/pgSQL switches to its\n        -- cached generic plan (after 5 calls), a parameter-gated\n        -- \"(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)\"\n        -- predicate stops the planner from using name as an index\n        -- condition at all, degrading every subsequent peek to a full\n        -- index scan filtered row-by-row instead of a bounded range scan.\n        -- v_multi_row's seek predicate is a keyset tuple comparison\n        -- (\"name > x OR (name = x AND tiebreak)\") - Postgres does not\n        -- split this OR into indexable form even with fully literal\n        -- values, so it falls back to a full scan filtered row-by-row.\n        -- Splitting it into two independently-indexable branches (exact\n        -- name match with the tiebreak filter, vs. strictly-past name)\n        -- combined with UNION ALL lets each branch keep name as a real\n        -- index condition; the outer ORDER BY/LIMIT picks whichever of\n        -- the (at most 2) rows sorts first.\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING _bucket_id, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,\n                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;\n        ELSIF v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" < v_upper_bound\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek AND o.name COLLATE \"C\" < v_upper_bound\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" >= v_prefix\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek AND o.name COLLATE \"C\" >= v_prefix\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '') > v_next_seek_version))\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek\n                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                           AND (delete_markers != 'only' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        ELSE\n            -- Single-row mode is always noncurrent_versions='exclude'. Keep\n            -- this predicate literal so generic plans use the current index.\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.name COLLATE \"C\" >= v_prefix\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                      AND (delete_markers != 'only' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Emit and skip to next folder (no heap access needed)\n            name := v_common_prefix;\n            id := NULL;\n            updated_at := NULL;\n            created_at := NULL;\n            last_accessed_at := NULL;\n            metadata := NULL;\n            version := NULL;\n            archived_at := NULL;\n            is_delete_marker := NULL;\n            is_versioned := NULL;\n            RETURN NEXT;\n            v_count := v_count + 1;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := left(v_common_prefix, -1)\n                    || chr(ascii(right(v_common_prefix, 1)) + 1);\n            ELSE\n                v_next_seek := v_common_prefix;\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END\n                USING _bucket_id, v_next_seek,\n                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,\n                v_next_seek_strict\n            LOOP\n                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN v_current.name\n                        ELSE v_current.name || delimiter_param\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Emit file\n                name := v_current.name;\n                id := v_current.id;\n                updated_at := v_current.updated_at;\n                created_at := v_current.created_at;\n                last_accessed_at := v_current.last_accessed_at;\n                metadata := v_current.metadata;\n                version := v_current.version;\n                archived_at := v_current.archived_at;\n                is_delete_marker := v_current.is_delete_marker;\n                is_versioned := v_current.is_versioned;\n                RETURN NEXT;\n                v_count := v_count + 1;\n\n                -- when v_multi_row, stay on this name and record its\n                -- archived_at as the new tiebreak so remaining rows for the\n                -- same key are picked up before moving to the next name\n                IF v_multi_row THEN\n                    v_next_seek := v_current.name;\n                    v_next_seek_at := COALESCE(date_trunc('milliseconds', v_current.archived_at), 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                    v_next_seek_strict := false;\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor\n                    -- would skip a real key like `name || '!'` (or any\n                    -- character sorting below the delimiter), which sorts\n                    -- between `name` and `name || delimiter`. Track the real\n                    -- name and mark the next comparison strict instead.\n                    v_next_seek := v_current.name;\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := v_current.name;\n                END IF;\n\n                EXIT WHEN v_count >= max_keys;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.list_objects_with_delimiter made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"1241c63b3d7c1c343331d7d0b0f17dc5b389aff8a1782c0aa4bcf7aa3dcad36b","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.list_objects_with_delimiter(text, text, text, integer, text, text, text, text, text, timestamp with time zone, text)","definition_sha256":"2ea5b0041a685b122bc06e975e186c7b8bb6159c4561ff1e82c9ee142230a30e","language":"plpgsql"},{"schema":"storage","name":"operation","oid":17451,"args":"","argtypes":"","prosrc":"\nBEGIN\n    RETURN current_setting('storage.operation', true);\nEND;\n","probin":null,"rettype":"text","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.operation()\n RETURNS text\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN current_setting('storage.operation', true);\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"b211a4c4b376b7bd1c50cc5fd2876824c7b639717e6e0d6484482411bebc34af","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.operation()","definition_sha256":"45b3c213bf286ff7601da09fd91d246339d8c79e0bd573bfb6984d806841fcde","language":"plpgsql"},{"schema":"storage","name":"protect_active_lifecycle_states","oid":31159,"args":"","argtypes":"","prosrc":"\nBEGIN\n    IF EXISTS (\n        SELECT 1 FROM storage.bucket_lifecycle_states\n        WHERE bucket_id = OLD.id\n          AND NOT (\n              continuation IS NULL\n              OR (continuation @> '{\"continuationVersion\": 1}' AND continuation #> '{batch,inFlight}' IS NULL)\n          )\n    ) THEN\n        RAISE EXCEPTION 'update or delete on table \"buckets\" violates foreign key constraint \"bucket_lifecycle_states_bucket_id_fkey\" on table \"bucket_lifecycle_states\"'\n            USING ERRCODE = 'foreign_key_violation',\n                  DETAIL = format('Key (id)=(%s) is still referenced from table \"bucket_lifecycle_states\".', OLD.id),\n                  SCHEMA = 'storage',\n                  TABLE = 'bucket_lifecycle_states',\n                  CONSTRAINT = 'bucket_lifecycle_states_bucket_id_fkey';\n    END IF;\n    RETURN OLD;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.protect_active_lifecycle_states()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n    IF EXISTS (\n        SELECT 1 FROM storage.bucket_lifecycle_states\n        WHERE bucket_id = OLD.id\n          AND NOT (\n              continuation IS NULL\n              OR (continuation @> '{\"continuationVersion\": 1}' AND continuation #> '{batch,inFlight}' IS NULL)\n          )\n    ) THEN\n        RAISE EXCEPTION 'update or delete on table \"buckets\" violates foreign key constraint \"bucket_lifecycle_states_bucket_id_fkey\" on table \"bucket_lifecycle_states\"'\n            USING ERRCODE = 'foreign_key_violation',\n                  DETAIL = format('Key (id)=(%s) is still referenced from table \"bucket_lifecycle_states\".', OLD.id),\n                  SCHEMA = 'storage',\n                  TABLE = 'bucket_lifecycle_states',\n                  CONSTRAINT = 'bucket_lifecycle_states_bucket_id_fkey';\n    END IF;\n    RETURN OLD;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"f962913bc87cb9f787718170356950b5befe8a18717e083e830b39b0e58655b6","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.protect_active_lifecycle_states()","definition_sha256":"4fac38099dbf93ff30f9221abe6cb65aa40559fd529142eea567fbeb17333d82","language":"plpgsql"},{"schema":"storage","name":"protect_bucket_control_columns","oid":30942,"args":"","argtypes":"","prosrc":"\nDECLARE\n  configuration_changed boolean;\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.lifecycle_configuration IS NOT NULL\n       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN\n      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN\n        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'\n          USING ERRCODE = '42501',\n                HINT = format(\n                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',\n                  TG_ARGV[0]\n                );\n      END IF;\n    END IF;\n\n    RETURN NEW;\n  END IF;\n\n  configuration_changed =\n    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;\n\n  IF NOT configuration_changed THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN\n    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'\n      USING ERRCODE = '0A000';\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     AND NEW.lifecycle_configuration_generation IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     OR NEW.lifecycle_configuration_generation IS NULL\n     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration\n     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN\n    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'\n      USING ERRCODE = '22023';\n  END IF;\n\n  RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  configuration_changed boolean;\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.lifecycle_configuration IS NOT NULL\n       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN\n      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN\n        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'\n          USING ERRCODE = '42501',\n                HINT = format(\n                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',\n                  TG_ARGV[0]\n                );\n      END IF;\n    END IF;\n\n    RETURN NEW;\n  END IF;\n\n  configuration_changed =\n    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;\n\n  IF NOT configuration_changed THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN\n    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'\n      USING ERRCODE = '0A000';\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     AND NEW.lifecycle_configuration_generation IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     OR NEW.lifecycle_configuration_generation IS NULL\n     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration\n     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN\n    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'\n      USING ERRCODE = '22023';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"68b84b1d19ed68f59a863c923492901315ae283e260230cf56bb8266f540b16e","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.protect_bucket_control_columns()","definition_sha256":"dac4257ed931d18bac0cbbc3135d0c75a36aae55309059d2913ed5e6792fa8de","language":"plpgsql"},{"schema":"storage","name":"protect_delete","oid":17515,"args":"","argtypes":"","prosrc":"\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"8c757b3898456c92b28f30e15cdeadb43ff4522c0b9f0526100da3a34b174236","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.protect_delete()","definition_sha256":"60b634ed07bf3c08749b31168c62d598f2a9d10f8cef4ee8251bde93909cd30b","language":"plpgsql"},{"schema":"storage","name":"reconcile_lifecycle_state","oid":31161,"args":"target_bucket_id text, policy_changed boolean","argtypes":"text, boolean","prosrc":"\nDECLARE\n    bucket storage.buckets%ROWTYPE;\n    active boolean;\n    idle boolean;\n    state_generation uuid;\nBEGIN\n    SELECT * INTO bucket FROM storage.buckets WHERE id = target_bucket_id FOR NO KEY UPDATE;\n    IF NOT FOUND THEN\n        RETURN;\n    END IF;\n\n    SELECT continuation IS NULL OR (\n               continuation @> '{\"continuationVersion\": 1}'\n               AND continuation #> '{batch,inFlight}' IS NULL\n           ), generation\n    INTO idle, state_generation\n    FROM storage.bucket_lifecycle_states\n    WHERE bucket_id = target_bucket_id\n    FOR UPDATE;\n\n    IF bucket.lifecycle_configuration IS NULL THEN\n        DELETE FROM storage.bucket_lifecycle_states\n        WHERE bucket_id = target_bucket_id\n          AND idle IS TRUE;\n\n        UPDATE storage.bucket_lifecycle_states\n        SET next_run_at = clock_timestamp(), updated_at = clock_timestamp()\n        WHERE bucket_id = target_bucket_id\n          AND idle IS NOT TRUE;\n        RETURN;\n    END IF;\n\n    active := bucket.versioning_status <> 'DISABLED'\n        AND bucket.lifecycle_configuration @> '{\"rules\":[{\"status\":\"Enabled\"}]}'::jsonb;\n\n    -- The state row records the generation it was reconciled with so callers need not detect\n    -- policy changes. Rows without a recorded generation keep their work.\n    policy_changed := policy_changed OR (\n        state_generation IS NOT NULL AND state_generation <> bucket.lifecycle_configuration_generation\n    );\n\n    INSERT INTO storage.bucket_lifecycle_states AS state (bucket_id, generation, next_run_at)\n    VALUES (bucket.id, bucket.lifecycle_configuration_generation, CASE WHEN active THEN clock_timestamp() END)\n    ON CONFLICT (bucket_id) DO UPDATE\n    SET next_run_at = CASE\n            WHEN policy_changed THEN\n                CASE WHEN active OR idle IS NOT TRUE THEN clock_timestamp() END\n            ELSE EXCLUDED.next_run_at\n        END,\n        generation = EXCLUDED.generation,\n        claim_id = CASE WHEN policy_changed AND idle IS TRUE\n                        THEN NULL ELSE state.claim_id END,\n        claim_until = CASE WHEN policy_changed AND idle IS TRUE\n                           THEN NULL ELSE state.claim_until END,\n        continuation = CASE WHEN policy_changed AND idle IS TRUE\n                            THEN NULL ELSE state.continuation END,\n        failure_count = CASE WHEN policy_changed AND idle IS TRUE\n                             THEN 0 ELSE state.failure_count END,\n        last_error = CASE WHEN policy_changed AND idle IS TRUE\n                          THEN NULL ELSE state.last_error END,\n        updated_at = clock_timestamp()\n    WHERE policy_changed OR (state.next_run_at IS NULL AND EXCLUDED.next_run_at IS NOT NULL);\nEND;\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.reconcile_lifecycle_state(target_bucket_id text, policy_changed boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n    bucket storage.buckets%ROWTYPE;\n    active boolean;\n    idle boolean;\n    state_generation uuid;\nBEGIN\n    SELECT * INTO bucket FROM storage.buckets WHERE id = target_bucket_id FOR NO KEY UPDATE;\n    IF NOT FOUND THEN\n        RETURN;\n    END IF;\n\n    SELECT continuation IS NULL OR (\n               continuation @> '{\"continuationVersion\": 1}'\n               AND continuation #> '{batch,inFlight}' IS NULL\n           ), generation\n    INTO idle, state_generation\n    FROM storage.bucket_lifecycle_states\n    WHERE bucket_id = target_bucket_id\n    FOR UPDATE;\n\n    IF bucket.lifecycle_configuration IS NULL THEN\n        DELETE FROM storage.bucket_lifecycle_states\n        WHERE bucket_id = target_bucket_id\n          AND idle IS TRUE;\n\n        UPDATE storage.bucket_lifecycle_states\n        SET next_run_at = clock_timestamp(), updated_at = clock_timestamp()\n        WHERE bucket_id = target_bucket_id\n          AND idle IS NOT TRUE;\n        RETURN;\n    END IF;\n\n    active := bucket.versioning_status <> 'DISABLED'\n        AND bucket.lifecycle_configuration @> '{\"rules\":[{\"status\":\"Enabled\"}]}'::jsonb;\n\n    -- The state row records the generation it was reconciled with so callers need not detect\n    -- policy changes. Rows without a recorded generation keep their work.\n    policy_changed := policy_changed OR (\n        state_generation IS NOT NULL AND state_generation <> bucket.lifecycle_configuration_generation\n    );\n\n    INSERT INTO storage.bucket_lifecycle_states AS state (bucket_id, generation, next_run_at)\n    VALUES (bucket.id, bucket.lifecycle_configuration_generation, CASE WHEN active THEN clock_timestamp() END)\n    ON CONFLICT (bucket_id) DO UPDATE\n    SET next_run_at = CASE\n            WHEN policy_changed THEN\n                CASE WHEN active OR idle IS NOT TRUE THEN clock_timestamp() END\n            ELSE EXCLUDED.next_run_at\n        END,\n        generation = EXCLUDED.generation,\n        claim_id = CASE WHEN policy_changed AND idle IS TRUE\n                        THEN NULL ELSE state.claim_id END,\n        claim_until = CASE WHEN policy_changed AND idle IS TRUE\n                           THEN NULL ELSE state.claim_until END,\n        continuation = CASE WHEN policy_changed AND idle IS TRUE\n                            THEN NULL ELSE state.continuation END,\n        failure_count = CASE WHEN policy_changed AND idle IS TRUE\n                             THEN 0 ELSE state.failure_count END,\n        last_error = CASE WHEN policy_changed AND idle IS TRUE\n                          THEN NULL ELSE state.last_error END,\n        updated_at = clock_timestamp()\n    WHERE policy_changed OR (state.next_run_at IS NULL AND EXCLUDED.next_run_at IS NOT NULL);\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"c6e34d62e9ae9ada01458faa6c0374dd2ffdd60051e79c066b27de3e87362208","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"service_role","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.reconcile_lifecycle_state(text, boolean)","definition_sha256":"2b5169238709dcbfa8c1ddc8f0421b6420f14c4f4516fefc5d32d138eb336e10","language":"plpgsql"},{"schema":"storage","name":"search","oid":30950,"args":"prefix text, bucketname text, limits integer, levels integer, offsets integer, search text, sortcolumn text, sortorder text, noncurrent_versions text, delete_markers text","argtypes":"text, text, integer, integer, integer, text, text, text, text, text","prosrc":"\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n    v_delimiter CONSTANT TEXT := '/';\n\n    -- Configuration\n    v_limit INT;\n    v_prefix TEXT;\n    v_prefix_lower TEXT;\n    v_prefix_len INT;\n    v_prefix_start INT;\n    v_combined_levels INT;\n    v_is_asc BOOLEAN;\n    v_order_by TEXT;\n    v_sort_order TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n    v_multi_row BOOLEAN;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\n    -- Seek state\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_count INT := 0;\n    v_skipped INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n    v_previous_skipped INT;\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n    v_prefix := coalesce(prefix, '') || coalesce(search, '');\n    v_prefix_lower := lower(v_prefix);\n    v_prefix_len := length(coalesce(prefix, ''));\n    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);\n    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);\n    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';\n    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Validate sort column\n    CASE lower(coalesce(sortcolumn, 'name'))\n        WHEN 'name' THEN v_order_by := 'name';\n        WHEN 'updated_at' THEN v_order_by := 'updated_at';\n        WHEN 'created_at' THEN v_order_by := 'created_at';\n        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';\n        ELSE v_order_by := 'name';\n    END CASE;\n\n    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;\n\n    -- ========================================================================\n    -- NON-NAME SORTING: Use path_tokens approach\n    -- ========================================================================\n    IF v_order_by != 'name' THEN\n        RETURN QUERY EXECUTE format(\n            $sql$\n            WITH folders AS (\n                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder\n                FROM storage.objects\n                WHERE objects.name ILIKE $3 || '%%'\n                  AND bucket_id = $4\n                  AND array_length(objects.path_tokens, 1) <> $2\n                  AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n                  AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n                  AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n                  AND ($8 != 'only' OR objects.is_delete_marker)\n                GROUP BY folder\n                ORDER BY folder %s\n            )\n            (SELECT folder AS \"name\",\n                   NULL::uuid AS id,\n                   NULL::timestamptz AS updated_at,\n                   NULL::timestamptz AS created_at,\n                   NULL::timestamptz AS last_accessed_at,\n                   NULL::jsonb AS metadata,\n                   NULL::text AS version,\n                   NULL::timestamptz AS archived_at,\n                   NULL::boolean AS is_delete_marker,\n                   NULL::boolean AS is_versioned FROM folders)\n            UNION ALL\n            (SELECT array_to_string(path_tokens[$1:$2], '/') AS \"name\",\n                   id, updated_at, created_at, last_accessed_at, metadata,\n                   version, archived_at, is_delete_marker, is_versioned\n             FROM storage.objects\n             WHERE objects.name ILIKE $3 || '%%'\n               AND bucket_id = $4\n               AND array_length(objects.path_tokens, 1) = $2\n               AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n               AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n               AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n               AND ($8 != 'only' OR objects.is_delete_marker)\n             -- name, then version, as tiebreaks so two versions of the same\n             -- key tying on the sort column still sort deterministically\n             ORDER BY %I %s, name COLLATE \"C\" %s, COALESCE(version, '') %s)\n            LIMIT $5 OFFSET $6\n            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order\n        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;\n        RETURN;\n    END IF;\n\n    -- ========================================================================\n    -- NAME SORTING: Hybrid skip-scan with batch optimization\n    -- ========================================================================\n\n    -- Calculate upper bound for prefix filtering\n    IF v_prefix_lower = '' THEN\n        v_upper_bound := NULL;\n    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);\n    ELSE\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);\n    END IF;\n\n    -- Build a resume-safe batch query. The exact-name branch returns remaining\n    -- versions after the current (archived_at, version) boundary; the strict\n    -- name branch returns subsequent keys. UNION ALL keeps both predicates\n    -- independently indexable.\n    IF v_is_asc THEN\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2 AND lower(o.name) COLLATE \"C\" < $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    ELSE\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2 AND lower(o.name) COLLATE \"C\" >= $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    END IF;\n\n    -- Keep the delete-marker predicate literal so the cached generic\n    -- plan can use idx_objects_delete_markers during the main-loop peek.\n    IF delete_markers = 'only' THEN\n        IF v_multi_row THEN\n            v_delete_marker_peek_query :=\n                'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        ELSIF v_is_asc THEN\n            -- Two separate literal query strings, not one gated by a bound\n            -- boolean: folding \"$n AND op1 OR NOT $n AND op2\" into a single\n            -- query defeats the generic plan's ability to push either\n            -- comparison into the index. Branching in PL/pgSQL control flow\n            -- instead keeps each query's index condition intact.\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" >= $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n            -- Strict variant: used once the single-row ASC batch advance\n            -- (below) has left v_next_seek pointing at the last row already\n            -- emitted, so a plain >= would re-match it forever.\n            v_delete_marker_peek_query_strict :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" > $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n        ELSE\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" < $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" >= $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1';\n        END IF;\n    END IF;\n\n    -- Initialize seek position\n    IF v_is_asc THEN\n        v_next_seek := v_prefix_lower;\n    ELSE\n        -- DESC performs one specialized initial seek so partial current-version\n        -- and delete-marker indexes remain available.\n        EXECUTE format(\n            'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1',\n            CASE WHEN v_upper_bound IS NOT NULL\n                THEN ' AND lower(o.name) COLLATE \"C\" >= $2 AND lower(o.name) COLLATE \"C\" < $3'\n                ELSE ''\n            END,\n            v_version_filter\n        )\n        INTO v_peek_name\n        USING bucketname, v_prefix_lower, v_upper_bound;\n\n        IF v_peek_name IS NOT NULL THEN\n            v_next_seek := lower(v_peek_name) || v_delimiter;\n        ELSE\n            RETURN;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and\n    -- the delete-marker-only path\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= v_limit;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n        v_previous_skipped := v_skipped;\n\n        -- STEP 1: PEEK\n        v_peek_name := NULL;\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,\n                    1, v_next_seek_at, v_next_seek_version;\n        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN\n            SELECT o.name INTO v_peek_name\n            FROM storage.objects o\n            WHERE o.bucket_id = bucketname\n              AND lower(o.name) COLLATE \"C\" = v_next_seek\n              AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at\n                   OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at\n                       AND COALESCE(o.version, '') > v_next_seek_version))\n              AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n              AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n              AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n              AND (delete_markers != 'only' OR o.is_delete_marker)\n            ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,\n                     COALESCE(o.version, '') ASC\n            LIMIT 1;\n\n            -- The current key is exhausted. Clear its version boundary and\n            -- make the following ASC name peek strict. Appending '/' is not a\n            -- valid lexical successor because keys ending in characters such\n            -- as '!' sort between the exhausted name and name || '/'.\n            IF v_peek_name IS NULL THEN\n                IF v_is_asc THEN\n                    v_next_seek_strict := true;\n                END IF;\n                v_next_seek_at := NULL;\n                v_next_seek_version := '';\n            END IF;\n        END IF;\n\n        -- Single-row mode is always noncurrent_versions='exclude'. Keep the\n        -- current-row predicate literal so generic plans use the current index.\n        IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN\n            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_next_seek_strict THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN\n            IF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- If the peek landed on a different key than we were tracking, any\n        -- version boundary belongs to the OLD key and must not leak into the\n        -- new one - e.g. the deleteMarkers='only' peek doesn't know or care\n        -- whether it's continuing the same key or jumping to a new one, so\n        -- it never clears these itself.\n        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        END IF;\n\n        -- The peek is authoritative for the next key to process. This is\n        -- especially important after exhausting a multi-version key: the\n        -- version boundary has been cleared, so executing the batch against\n        -- a stale v_next_seek would replay every version of that old key.\n        v_next_seek := lower(v_peek_name);\n        v_next_seek_strict := false;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Handle offset, emit if needed, skip to next folder\n            IF v_skipped < offsets THEN\n                v_skipped := v_skipped + 1;\n            ELSE\n                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);\n                id := NULL;\n                updated_at := NULL;\n                created_at := NULL;\n                last_accessed_at := NULL;\n                metadata := NULL;\n                version := NULL;\n                archived_at := NULL;\n                is_delete_marker := NULL;\n                is_versioned := NULL;\n                RETURN NEXT;\n                v_count := v_count + 1;\n            END IF;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);\n            ELSE\n                v_next_seek := lower(v_common_prefix);\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE v_batch_query\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,\n                    v_next_seek_at, v_next_seek_version\n            LOOP\n                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too - it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN lower(v_current.name)\n                        ELSE lower(v_current.name) || v_delimiter\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Handle offset skipping\n                IF v_skipped < offsets THEN\n                    v_skipped := v_skipped + 1;\n                ELSE\n                    -- Emit file\n                    name := substring(v_current.name from v_prefix_len + 1);\n                    id := v_current.id;\n                    updated_at := v_current.updated_at;\n                    created_at := v_current.created_at;\n                    last_accessed_at := v_current.last_accessed_at;\n                    metadata := v_current.metadata;\n                    version := v_current.version;\n                    archived_at := v_current.archived_at;\n                    is_delete_marker := v_current.is_delete_marker;\n                    is_versioned := v_current.is_versioned;\n                    RETURN NEXT;\n                    v_count := v_count + 1;\n                END IF;\n\n                -- Multi-row mode must remain on this key until all of its\n                -- versions have crossed the internal batch boundary.\n                IF v_multi_row THEN\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor would\n                    -- skip a real key like `name || '!'` (or any character\n                    -- sorting below the delimiter), which sorts between `name`\n                    -- and `name || delimiter`. Track the real name and mark the\n                    -- next comparison strict instead - same fix as the\n                    -- exhausted-key case above.\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := lower(v_current.name);\n                END IF;\n\n                EXIT WHEN v_count >= v_limit;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_skipped = v_previous_skipped\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text)\n RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n    v_delimiter CONSTANT TEXT := '/';\n\n    -- Configuration\n    v_limit INT;\n    v_prefix TEXT;\n    v_prefix_lower TEXT;\n    v_prefix_len INT;\n    v_prefix_start INT;\n    v_combined_levels INT;\n    v_is_asc BOOLEAN;\n    v_order_by TEXT;\n    v_sort_order TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n    v_multi_row BOOLEAN;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\n    -- Seek state\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_count INT := 0;\n    v_skipped INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n    v_previous_skipped INT;\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n    v_prefix := coalesce(prefix, '') || coalesce(search, '');\n    v_prefix_lower := lower(v_prefix);\n    v_prefix_len := length(coalesce(prefix, ''));\n    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);\n    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);\n    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';\n    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN ('only', 'include');\n\n    v_version_filter := '';\n    IF noncurrent_versions = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';\n    ELSIF noncurrent_versions = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';\n    END IF;\n    IF delete_markers = 'exclude' THEN\n        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';\n    ELSIF delete_markers = 'only' THEN\n        v_version_filter := v_version_filter || ' AND o.is_delete_marker';\n    END IF;\n\n    -- Validate sort column\n    CASE lower(coalesce(sortcolumn, 'name'))\n        WHEN 'name' THEN v_order_by := 'name';\n        WHEN 'updated_at' THEN v_order_by := 'updated_at';\n        WHEN 'created_at' THEN v_order_by := 'created_at';\n        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';\n        ELSE v_order_by := 'name';\n    END CASE;\n\n    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;\n\n    -- ========================================================================\n    -- NON-NAME SORTING: Use path_tokens approach\n    -- ========================================================================\n    IF v_order_by != 'name' THEN\n        RETURN QUERY EXECUTE format(\n            $sql$\n            WITH folders AS (\n                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder\n                FROM storage.objects\n                WHERE objects.name ILIKE $3 || '%%'\n                  AND bucket_id = $4\n                  AND array_length(objects.path_tokens, 1) <> $2\n                  AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n                  AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n                  AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n                  AND ($8 != 'only' OR objects.is_delete_marker)\n                GROUP BY folder\n                ORDER BY folder %s\n            )\n            (SELECT folder AS \"name\",\n                   NULL::uuid AS id,\n                   NULL::timestamptz AS updated_at,\n                   NULL::timestamptz AS created_at,\n                   NULL::timestamptz AS last_accessed_at,\n                   NULL::jsonb AS metadata,\n                   NULL::text AS version,\n                   NULL::timestamptz AS archived_at,\n                   NULL::boolean AS is_delete_marker,\n                   NULL::boolean AS is_versioned FROM folders)\n            UNION ALL\n            (SELECT array_to_string(path_tokens[$1:$2], '/') AS \"name\",\n                   id, updated_at, created_at, last_accessed_at, metadata,\n                   version, archived_at, is_delete_marker, is_versioned\n             FROM storage.objects\n             WHERE objects.name ILIKE $3 || '%%'\n               AND bucket_id = $4\n               AND array_length(objects.path_tokens, 1) = $2\n               AND ($7 != 'exclude' OR objects.archived_at IS NULL)\n               AND ($7 != 'only' OR objects.archived_at IS NOT NULL)\n               AND ($8 != 'exclude' OR NOT objects.is_delete_marker)\n               AND ($8 != 'only' OR objects.is_delete_marker)\n             -- name, then version, as tiebreaks so two versions of the same\n             -- key tying on the sort column still sort deterministically\n             ORDER BY %I %s, name COLLATE \"C\" %s, COALESCE(version, '') %s)\n            LIMIT $5 OFFSET $6\n            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order\n        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;\n        RETURN;\n    END IF;\n\n    -- ========================================================================\n    -- NAME SORTING: Hybrid skip-scan with batch optimization\n    -- ========================================================================\n\n    -- Calculate upper bound for prefix filtering\n    IF v_prefix_lower = '' THEN\n        v_upper_bound := NULL;\n    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);\n    ELSE\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);\n    END IF;\n\n    -- Build a resume-safe batch query. The exact-name branch returns remaining\n    -- versions after the current (archived_at, version) boundary; the strict\n    -- name branch returns subsequent keys. UNION ALL keeps both predicates\n    -- independently indexable.\n    IF v_is_asc THEN\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2 AND lower(o.name) COLLATE \"C\" < $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    ELSE\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2 AND lower(o.name) COLLATE \"C\" >= $3' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        ELSE\n            v_batch_query := 'SELECT * FROM (' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||\n                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||\n                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||\n                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2' || v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||\n                ') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';\n        END IF;\n    END IF;\n\n    -- Keep the delete-marker predicate literal so the cached generic\n    -- plan can use idx_objects_delete_markers during the main-loop peek.\n    IF delete_markers = 'only' THEN\n        IF v_multi_row THEN\n            v_delete_marker_peek_query :=\n                'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';\n        ELSIF v_is_asc THEN\n            -- Two separate literal query strings, not one gated by a bound\n            -- boolean: folding \"$n AND op1 OR NOT $n AND op2\" into a single\n            -- query defeats the generic plan's ability to push either\n            -- comparison into the index. Branching in PL/pgSQL control flow\n            -- instead keeps each query's index condition intact.\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" >= $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n            -- Strict variant: used once the single-row ASC batch advance\n            -- (below) has left v_next_seek pointing at the last row already\n            -- emitted, so a plain >= would re-match it forever.\n            v_delete_marker_peek_query_strict :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" > $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" < $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1';\n        ELSE\n            v_delete_marker_peek_query :=\n                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||\n                'AND lower(o.name) COLLATE \"C\" < $2' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN ' AND lower(o.name) COLLATE \"C\" >= $3'\n                    ELSE ''\n                END ||\n                v_version_filter ||\n                ' ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1';\n        END IF;\n    END IF;\n\n    -- Initialize seek position\n    IF v_is_asc THEN\n        v_next_seek := v_prefix_lower;\n    ELSE\n        -- DESC performs one specialized initial seek so partial current-version\n        -- and delete-marker indexes remain available.\n        EXECUTE format(\n            'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1',\n            CASE WHEN v_upper_bound IS NOT NULL\n                THEN ' AND lower(o.name) COLLATE \"C\" >= $2 AND lower(o.name) COLLATE \"C\" < $3'\n                ELSE ''\n            END,\n            v_version_filter\n        )\n        INTO v_peek_name\n        USING bucketname, v_prefix_lower, v_upper_bound;\n\n        IF v_peek_name IS NOT NULL THEN\n            v_next_seek := lower(v_peek_name) || v_delimiter;\n        ELSE\n            RETURN;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and\n    -- the delete-marker-only path\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= v_limit;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n        v_previous_skipped := v_skipped;\n\n        -- STEP 1: PEEK\n        v_peek_name := NULL;\n        IF delete_markers = 'only' THEN\n            EXECUTE CASE WHEN v_next_seek_strict\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,\n                    1, v_next_seek_at, v_next_seek_version;\n        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN\n            SELECT o.name INTO v_peek_name\n            FROM storage.objects o\n            WHERE o.bucket_id = bucketname\n              AND lower(o.name) COLLATE \"C\" = v_next_seek\n              AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at\n                   OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at\n                       AND COALESCE(o.version, '') > v_next_seek_version))\n              AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n              AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n              AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n              AND (delete_markers != 'only' OR o.is_delete_marker)\n            ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,\n                     COALESCE(o.version, '') ASC\n            LIMIT 1;\n\n            -- The current key is exhausted. Clear its version boundary and\n            -- make the following ASC name peek strict. Appending '/' is not a\n            -- valid lexical successor because keys ending in characters such\n            -- as '!' sort between the exhausted name and name || '/'.\n            IF v_peek_name IS NULL THEN\n                IF v_is_asc THEN\n                    v_next_seek_strict := true;\n                END IF;\n                v_next_seek_at := NULL;\n                v_next_seek_version := '';\n            END IF;\n        END IF;\n\n        -- Single-row mode is always noncurrent_versions='exclude'. Keep the\n        -- current-row predicate literal so generic plans use the current index.\n        IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN\n            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_next_seek_strict THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN\n            IF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)\n                  AND (delete_markers != 'only' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- If the peek landed on a different key than we were tracking, any\n        -- version boundary belongs to the OLD key and must not leak into the\n        -- new one - e.g. the deleteMarkers='only' peek doesn't know or care\n        -- whether it's continuing the same key or jumping to a new one, so\n        -- it never clears these itself.\n        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        END IF;\n\n        -- The peek is authoritative for the next key to process. This is\n        -- especially important after exhausting a multi-version key: the\n        -- version boundary has been cleared, so executing the batch against\n        -- a stale v_next_seek would replay every version of that old key.\n        v_next_seek := lower(v_peek_name);\n        v_next_seek_strict := false;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Handle offset, emit if needed, skip to next folder\n            IF v_skipped < offsets THEN\n                v_skipped := v_skipped + 1;\n            ELSE\n                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);\n                id := NULL;\n                updated_at := NULL;\n                created_at := NULL;\n                last_accessed_at := NULL;\n                metadata := NULL;\n                version := NULL;\n                archived_at := NULL;\n                is_delete_marker := NULL;\n                is_versioned := NULL;\n                RETURN NEXT;\n                v_count := v_count + 1;\n            END IF;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);\n            ELSE\n                v_next_seek := lower(v_common_prefix);\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '';\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE v_batch_query\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,\n                    v_next_seek_at, v_next_seek_version\n            LOOP\n                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too - it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row's own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN lower(v_current.name)\n                        ELSE lower(v_current.name) || v_delimiter\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Handle offset skipping\n                IF v_skipped < offsets THEN\n                    v_skipped := v_skipped + 1;\n                ELSE\n                    -- Emit file\n                    name := substring(v_current.name from v_prefix_len + 1);\n                    id := v_current.id;\n                    updated_at := v_current.updated_at;\n                    created_at := v_current.created_at;\n                    last_accessed_at := v_current.last_accessed_at;\n                    metadata := v_current.metadata;\n                    version := v_current.version;\n                    archived_at := v_current.archived_at;\n                    is_delete_marker := v_current.is_delete_marker;\n                    is_versioned := v_current.is_versioned;\n                    RETURN NEXT;\n                    v_count := v_count + 1;\n                END IF;\n\n                -- Multi-row mode must remain on this key until all of its\n                -- versions have crossed the internal batch boundary.\n                IF v_multi_row THEN\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '');\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor would\n                    -- skip a real key like `name || '!'` (or any character\n                    -- sorting below the delimiter), which sorts between `name`\n                    -- and `name || delimiter`. Track the real name and mark the\n                    -- next comparison strict instead - same fix as the\n                    -- exhausted-key case above.\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := lower(v_current.name);\n                END IF;\n\n                EXIT WHEN v_count >= v_limit;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_skipped = v_previous_skipped\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"15e6bb855cbece49800ecb9cb34c9c7deda0c285f0666972e119badd096b8ef1","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.search(text, text, integer, integer, integer, text, text, text, text, text)","definition_sha256":"554f4855e4490792b6c854ba68e622f39f004515d092e7409b0167a44b4acc99","language":"plpgsql"},{"schema":"storage","name":"search_by_timestamp","oid":30952,"args":"p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text, delete_markers text, p_start_after_version text","argtypes":"text, text, integer, integer, text, text, text, text, text, text, text","prosrc":"\nDECLARE\n    v_cursor_op text;\n    v_query text;\n    v_prefix text;\n    v_prefix_pattern text;\n    v_sort_order text;\n    v_sort_column text;\n    v_version_tiebreak text;\nBEGIN\n    v_prefix := coalesce(p_prefix, '');\n    -- Keep the raw prefix for common-prefix calculations and escape only LIKE metacharacters.\n    v_prefix_pattern := replace(v_prefix, chr(92), chr(92) || chr(92));\n    v_prefix_pattern := replace(v_prefix_pattern, '%', chr(92) || '%');\n    v_prefix_pattern := replace(v_prefix_pattern, '_', chr(92) || '_');\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    -- $9 is only populated in multi-row mode; it's always '' otherwise, so\n    -- only use each row's real version as a tiebreak in multi-row mode.\n    v_version_tiebreak := CASE WHEN noncurrent_versions IN ('only', 'include') THEN 'COALESCE(version, '''')' ELSE '''''' END;\n\n    -- Defense-in-depth: this function is independently reachable and must\n    -- not trust p_sort_order/p_sort_column to already be validated by a\n    -- caller. Normalize to the same strict allow-list storage.search_v2\n    -- uses before interpolating anything into dynamic SQL below.\n    v_sort_order := lower(coalesce(p_sort_order, 'asc'));\n    IF v_sort_order NOT IN ('asc', 'desc') THEN\n        v_sort_order := 'asc';\n    END IF;\n\n    v_sort_column := lower(coalesce(p_sort_column, 'updated_at'));\n    IF v_sort_column NOT IN ('updated_at', 'created_at') THEN\n        v_sort_column := 'updated_at';\n    END IF;\n\n    IF v_sort_order = 'asc' THEN\n        v_cursor_op := '>';\n    ELSE\n        v_cursor_op := '<';\n    END IF;\n\n    v_query := format($sql$\n        WITH raw_objects AS (\n            SELECT\n                o.name AS obj_name,\n                o.id AS obj_id,\n                o.updated_at AS obj_updated_at,\n                o.created_at AS obj_created_at,\n                o.last_accessed_at AS obj_last_accessed_at,\n                o.metadata AS obj_metadata,\n                o.version AS obj_version,\n                o.archived_at AS obj_archived_at,\n                o.is_delete_marker AS obj_is_delete_marker,\n                o.is_versioned AS obj_is_versioned,\n                storage.get_common_prefix(o.name, $1, '/') AS common_prefix\n            FROM storage.objects o\n            WHERE o.bucket_id = $2\n              AND o.name COLLATE \"C\" LIKE $10 || '%%'\n              AND ($7 != 'exclude' OR o.archived_at IS NULL)\n              AND ($7 != 'only' OR o.archived_at IS NOT NULL)\n              AND ($8 != 'exclude' OR NOT o.is_delete_marker)\n              AND ($8 != 'only' OR o.is_delete_marker)\n        ),\n        -- Aggregate common prefixes (folders)\n        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior\n        aggregated_prefixes AS (\n            SELECT\n                common_prefix AS name,\n                NULL::uuid AS id,\n                MIN(obj_created_at) AS updated_at,\n                MIN(obj_created_at) AS created_at,\n                NULL::timestamptz AS last_accessed_at,\n                NULL::jsonb AS metadata,\n                NULL::text AS version,\n                NULL::timestamptz AS archived_at,\n                NULL::boolean AS is_delete_marker,\n                NULL::boolean AS is_versioned,\n                TRUE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NOT NULL\n            GROUP BY common_prefix\n        ),\n        leaf_objects AS (\n            SELECT\n                obj_name AS name,\n                obj_id AS id,\n                obj_updated_at AS updated_at,\n                obj_created_at AS created_at,\n                obj_last_accessed_at AS last_accessed_at,\n                obj_metadata AS metadata,\n                obj_version AS version,\n                obj_archived_at AS archived_at,\n                obj_is_delete_marker AS is_delete_marker,\n                obj_is_versioned AS is_versioned,\n                FALSE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NULL\n        ),\n        combined AS (\n            SELECT * FROM aggregated_prefixes\n            UNION ALL\n            SELECT * FROM leaf_objects\n        ),\n        filtered AS (\n            SELECT *\n            FROM combined\n            WHERE (\n                $5 = ''\n                OR ROW(\n                    COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz),\n                    name COLLATE \"C\",\n                    %s\n                ) %s ROW(\n                    -- truncated the same way as the stored value above\n                    date_trunc('milliseconds', COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz)),\n                    $5,\n                    $9\n                )\n            )\n        )\n        SELECT\n            split_part(name, '/', $3) AS key,\n            name,\n            id,\n            updated_at,\n            created_at,\n            last_accessed_at,\n            metadata,\n            version,\n            archived_at,\n            is_delete_marker,\n            is_versioned\n        FROM filtered\n        ORDER BY\n            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,\n            name COLLATE \"C\" %s,\n            COALESCE(version, '') %s\n        LIMIT $4\n    $sql$,\n        v_sort_column,\n        v_version_tiebreak,\n        v_cursor_op,\n        v_sort_column,\n        v_sort_order,\n        v_sort_order,\n        v_sort_order\n    );\n\n    -- version is the third tiebreak component for two versions of the same\n    -- key tying on both timestamp and name (see filtered CTE / ORDER BY above)\n    RETURN QUERY EXECUTE v_query\n    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after, noncurrent_versions, delete_markers, coalesce(p_start_after_version, ''), v_prefix_pattern;\nEND;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, p_start_after_version text DEFAULT ''::text)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_cursor_op text;\n    v_query text;\n    v_prefix text;\n    v_prefix_pattern text;\n    v_sort_order text;\n    v_sort_column text;\n    v_version_tiebreak text;\nBEGIN\n    v_prefix := coalesce(p_prefix, '');\n    -- Keep the raw prefix for common-prefix calculations and escape only LIKE metacharacters.\n    v_prefix_pattern := replace(v_prefix, chr(92), chr(92) || chr(92));\n    v_prefix_pattern := replace(v_prefix_pattern, '%', chr(92) || '%');\n    v_prefix_pattern := replace(v_prefix_pattern, '_', chr(92) || '_');\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');\n    delete_markers := COALESCE(delete_markers, 'exclude');\n    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN\n        noncurrent_versions := 'exclude';\n    END IF;\n    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN\n        delete_markers := 'exclude';\n    END IF;\n\n    -- $9 is only populated in multi-row mode; it's always '' otherwise, so\n    -- only use each row's real version as a tiebreak in multi-row mode.\n    v_version_tiebreak := CASE WHEN noncurrent_versions IN ('only', 'include') THEN 'COALESCE(version, '''')' ELSE '''''' END;\n\n    -- Defense-in-depth: this function is independently reachable and must\n    -- not trust p_sort_order/p_sort_column to already be validated by a\n    -- caller. Normalize to the same strict allow-list storage.search_v2\n    -- uses before interpolating anything into dynamic SQL below.\n    v_sort_order := lower(coalesce(p_sort_order, 'asc'));\n    IF v_sort_order NOT IN ('asc', 'desc') THEN\n        v_sort_order := 'asc';\n    END IF;\n\n    v_sort_column := lower(coalesce(p_sort_column, 'updated_at'));\n    IF v_sort_column NOT IN ('updated_at', 'created_at') THEN\n        v_sort_column := 'updated_at';\n    END IF;\n\n    IF v_sort_order = 'asc' THEN\n        v_cursor_op := '>';\n    ELSE\n        v_cursor_op := '<';\n    END IF;\n\n    v_query := format($sql$\n        WITH raw_objects AS (\n            SELECT\n                o.name AS obj_name,\n                o.id AS obj_id,\n                o.updated_at AS obj_updated_at,\n                o.created_at AS obj_created_at,\n                o.last_accessed_at AS obj_last_accessed_at,\n                o.metadata AS obj_metadata,\n                o.version AS obj_version,\n                o.archived_at AS obj_archived_at,\n                o.is_delete_marker AS obj_is_delete_marker,\n                o.is_versioned AS obj_is_versioned,\n                storage.get_common_prefix(o.name, $1, '/') AS common_prefix\n            FROM storage.objects o\n            WHERE o.bucket_id = $2\n              AND o.name COLLATE \"C\" LIKE $10 || '%%'\n              AND ($7 != 'exclude' OR o.archived_at IS NULL)\n              AND ($7 != 'only' OR o.archived_at IS NOT NULL)\n              AND ($8 != 'exclude' OR NOT o.is_delete_marker)\n              AND ($8 != 'only' OR o.is_delete_marker)\n        ),\n        -- Aggregate common prefixes (folders)\n        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior\n        aggregated_prefixes AS (\n            SELECT\n                common_prefix AS name,\n                NULL::uuid AS id,\n                MIN(obj_created_at) AS updated_at,\n                MIN(obj_created_at) AS created_at,\n                NULL::timestamptz AS last_accessed_at,\n                NULL::jsonb AS metadata,\n                NULL::text AS version,\n                NULL::timestamptz AS archived_at,\n                NULL::boolean AS is_delete_marker,\n                NULL::boolean AS is_versioned,\n                TRUE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NOT NULL\n            GROUP BY common_prefix\n        ),\n        leaf_objects AS (\n            SELECT\n                obj_name AS name,\n                obj_id AS id,\n                obj_updated_at AS updated_at,\n                obj_created_at AS created_at,\n                obj_last_accessed_at AS last_accessed_at,\n                obj_metadata AS metadata,\n                obj_version AS version,\n                obj_archived_at AS archived_at,\n                obj_is_delete_marker AS is_delete_marker,\n                obj_is_versioned AS is_versioned,\n                FALSE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NULL\n        ),\n        combined AS (\n            SELECT * FROM aggregated_prefixes\n            UNION ALL\n            SELECT * FROM leaf_objects\n        ),\n        filtered AS (\n            SELECT *\n            FROM combined\n            WHERE (\n                $5 = ''\n                OR ROW(\n                    COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz),\n                    name COLLATE \"C\",\n                    %s\n                ) %s ROW(\n                    -- truncated the same way as the stored value above\n                    date_trunc('milliseconds', COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz)),\n                    $5,\n                    $9\n                )\n            )\n        )\n        SELECT\n            split_part(name, '/', $3) AS key,\n            name,\n            id,\n            updated_at,\n            created_at,\n            last_accessed_at,\n            metadata,\n            version,\n            archived_at,\n            is_delete_marker,\n            is_versioned\n        FROM filtered\n        ORDER BY\n            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,\n            name COLLATE \"C\" %s,\n            COALESCE(version, '') %s\n        LIMIT $4\n    $sql$,\n        v_sort_column,\n        v_version_tiebreak,\n        v_cursor_op,\n        v_sort_column,\n        v_sort_order,\n        v_sort_order,\n        v_sort_order\n    );\n\n    -- version is the third tiebreak component for two versions of the same\n    -- key tying on both timestamp and name (see filtered CTE / ORDER BY above)\n    RETURN QUERY EXECUTE v_query\n    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after, noncurrent_versions, delete_markers, coalesce(p_start_after_version, ''), v_prefix_pattern;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"cf5f814301318a86a2d90d2e4921cf243f73f6f0f9feb3589d8f99bfe14a862a","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.search_by_timestamp(text, text, integer, integer, text, text, text, text, text, text, text)","definition_sha256":"00035e14f49a1cd28b87d80e0aefde8e4bf1fb91fe4f8facbcb6001c27f8849b","language":"plpgsql"},{"schema":"storage","name":"search_v2","oid":30954,"args":"prefix text, bucket_name text, limits integer, levels integer, start_after text, sort_order text, sort_column text, sort_column_after text, noncurrent_versions text, delete_markers text, start_after_archived_at timestamp with time zone, start_after_version text, start_after_is_continuation boolean","argtypes":"text, text, integer, integer, text, text, text, text, text, text, timestamp with time zone, text, boolean","prosrc":"\nDECLARE\n    v_sort_col text;\n    v_sort_ord text;\n    v_limit int;\nBEGIN\n    -- Cap limit to maximum of 1500 records\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n\n    -- Validate and normalize sort_order\n    v_sort_ord := lower(coalesce(sort_order, 'asc'));\n    IF v_sort_ord NOT IN ('asc', 'desc') THEN\n        v_sort_ord := 'asc';\n    END IF;\n\n    -- Validate and normalize sort_column\n    v_sort_col := lower(coalesce(sort_column, 'name'));\n    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN\n        v_sort_col := 'name';\n    END IF;\n\n    -- Route to appropriate implementation\n    IF v_sort_col = 'name' THEN\n        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))\n        RETURN QUERY\n        SELECT\n            split_part(l.name, '/', levels) AS key,\n            l.name AS name,\n            l.id,\n            l.updated_at,\n            l.created_at,\n            l.last_accessed_at,\n            l.metadata,\n            l.version,\n            l.archived_at,\n            l.is_delete_marker,\n            l.is_versioned\n        FROM storage.list_objects_with_delimiter(\n            bucket_name,\n            coalesce(prefix, ''),\n            '/',\n            v_limit,\n            CASE WHEN start_after_is_continuation THEN '' ELSE start_after END,\n            CASE WHEN start_after_is_continuation THEN start_after ELSE '' END,\n            v_sort_ord,\n            noncurrent_versions,\n            delete_markers,\n            start_after_archived_at,\n            start_after_version\n        ) l;\n    ELSE\n        -- Use aggregation approach for timestamp sorting\n        -- Not efficient for large datasets but supports correct pagination\n        RETURN QUERY SELECT * FROM storage.search_by_timestamp(\n            prefix, bucket_name, v_limit, levels, start_after,\n            v_sort_ord, v_sort_col, sort_column_after,\n            noncurrent_versions, delete_markers, start_after_version\n        );\n    END IF;\nEND;\n","probin":null,"rettype":"record","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, start_after_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, start_after_version text DEFAULT ''::text, start_after_is_continuation boolean DEFAULT false)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_sort_col text;\n    v_sort_ord text;\n    v_limit int;\nBEGIN\n    -- Cap limit to maximum of 1500 records\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n\n    -- Validate and normalize sort_order\n    v_sort_ord := lower(coalesce(sort_order, 'asc'));\n    IF v_sort_ord NOT IN ('asc', 'desc') THEN\n        v_sort_ord := 'asc';\n    END IF;\n\n    -- Validate and normalize sort_column\n    v_sort_col := lower(coalesce(sort_column, 'name'));\n    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN\n        v_sort_col := 'name';\n    END IF;\n\n    -- Route to appropriate implementation\n    IF v_sort_col = 'name' THEN\n        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))\n        RETURN QUERY\n        SELECT\n            split_part(l.name, '/', levels) AS key,\n            l.name AS name,\n            l.id,\n            l.updated_at,\n            l.created_at,\n            l.last_accessed_at,\n            l.metadata,\n            l.version,\n            l.archived_at,\n            l.is_delete_marker,\n            l.is_versioned\n        FROM storage.list_objects_with_delimiter(\n            bucket_name,\n            coalesce(prefix, ''),\n            '/',\n            v_limit,\n            CASE WHEN start_after_is_continuation THEN '' ELSE start_after END,\n            CASE WHEN start_after_is_continuation THEN start_after ELSE '' END,\n            v_sort_ord,\n            noncurrent_versions,\n            delete_markers,\n            start_after_archived_at,\n            start_after_version\n        ) l;\n    ELSE\n        -- Use aggregation approach for timestamp sorting\n        -- Not efficient for large datasets but supports correct pagination\n        RETURN QUERY SELECT * FROM storage.search_by_timestamp(\n            prefix, bucket_name, v_limit, levels, start_after,\n            v_sort_ord, v_sort_col, sort_column_after,\n            noncurrent_versions, delete_markers, start_after_version\n        );\n    END IF;\nEND;\n$function$\n","config":null,"secdef":false,"volatility":"s","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"4c81bcc1c9e36a01c74d4be89fdffd4532a05718dd89442979ce125cd58e0bca","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.search_v2(text, text, integer, integer, text, text, text, text, text, text, timestamp with time zone, text, boolean)","definition_sha256":"cd96303762e94fbd02f84a408a09af8019d15c33b2df537bdf1909da8561bcaf","language":"plpgsql"},{"schema":"storage","name":"update_updated_at_column","oid":17386,"args":"","argtypes":"","prosrc":"\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n$function$\n","config":null,"secdef":false,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_storage_admin","sha256":"1e0582c796d58810ca3d1066e97ce7f4a5d55e4174b8185ff8aebe14e61f424f","service_exec":true,"anon_exec":true,"authenticated_exec":true,"acl":[{"grantee":"PUBLIC","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_storage_admin","grantor":"supabase_storage_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"storage.update_updated_at_column()","definition_sha256":"5b3d8ac75beaf9d1532159c055aa927297f5611ad2ea82c27dbadf76887bb25e","language":"plpgsql"},{"schema":"storage","name":"wake_lifecycle_state","oid":31162,"args":"","argtypes":"","prosrc":"\nBEGIN\n    IF TG_OP = 'INSERT' AND NEW.lifecycle_configuration IS NULL THEN\n        RETURN NEW;\n    END IF;\n\n    PERFORM storage.reconcile_lifecycle_state(NEW.id, false);\n    RETURN NEW;\nEND;\n","probin":null,"rettype":"trigger","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION storage.wake_lifecycle_state()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n    IF TG_OP = 'INSERT' AND NEW.lifecycle_configuration IS NULL THEN\n        RETURN NEW;\n    END IF;\n\n    PERFORM storage.reconcile_lifecycle_state(NEW.id, false);\n    RETURN NEW;\nEND;\n$function$\n","config":["search_path=pg_catalog"],"secdef":true,"volatility