dditional bytea, key_id bigint, context bytea, nonce bytea","argtypes":"bytea, bytea, bigint, bytea, bytea","prosrc":"pgsodium_crypto_aead_det_encrypt_by_id","probin":"$libdir/supabase_vault","rettype":"bytea","language_oid":"13","definition":"CREATE OR REPLACE FUNCTION vault._crypto_aead_det_encrypt(message bytea, additional bytea, key_id bigint, context bytea DEFAULT '\\x7067736f6469756d'::bytea, nonce bytea DEFAULT NULL::bytea)\n RETURNS bytea\n LANGUAGE c\n IMMUTABLE\nAS '$libdir/supabase_vault', $function$pgsodium_crypto_aead_det_encrypt_by_id$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"4dde8a46fdca8ecea67e9bb14a80bba952ba3dce449ecbb79d0ad4f4c504278a","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"vault._crypto_aead_det_encrypt(bytea, bytea, bigint, bytea, bytea)","definition_sha256":"da607717a8cb0982a0b8b6147a69e27fdb5cb3ef44a2b7a3fdeec8fa34480276","language":"c"},{"schema":"vault","name":"_crypto_aead_det_noncegen","oid":16611,"args":"","argtypes":"","prosrc":"pgsodium_crypto_aead_det_noncegen","probin":"$libdir/supabase_vault","rettype":"bytea","language_oid":"13","definition":"CREATE OR REPLACE FUNCTION vault._crypto_aead_det_noncegen()\n RETURNS bytea\n LANGUAGE c\n IMMUTABLE\nAS '$libdir/supabase_vault', $function$pgsodium_crypto_aead_det_noncegen$function$\n","config":null,"secdef":false,"volatility":"i","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"1007669048d04f203da25abe94cda995c7f0f2b0c85d3cc42b1e2e2e09593377","service_exec":false,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"vault._crypto_aead_det_noncegen()","definition_sha256":"22fca6138a62c794ea1cf948d699eddd4a949a382d60301b9123e7364f4e4f1b","language":"c"},{"schema":"vault","name":"create_secret","oid":16629,"args":"new_secret text, new_name text, new_description text, new_key_id uuid","argtypes":"text, text, text, uuid","prosrc":"\nDECLARE\n  rec record;\nBEGIN\n  INSERT INTO vault.secrets (secret, name, description)\n  VALUES (\n    new_secret,\n    new_name,\n    new_description\n  )\n  RETURNING * INTO rec;\n  UPDATE vault.secrets s\n  SET secret = encode(vault._crypto_aead_det_encrypt(\n    message := convert_to(rec.secret, 'utf8'),\n    additional := convert_to(s.id::text, 'utf8'),\n    key_id := 0,\n    context := 'pgsodium'::bytea,\n    nonce := rec.nonce\n  ), 'base64')\n  WHERE id = rec.id;\n  RETURN rec.id;\nEND\n","probin":null,"rettype":"uuid","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION vault.create_secret(new_secret text, new_name text DEFAULT NULL::text, new_description text DEFAULT ''::text, new_key_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE\n  rec record;\nBEGIN\n  INSERT INTO vault.secrets (secret, name, description)\n  VALUES (\n    new_secret,\n    new_name,\n    new_description\n  )\n  RETURNING * INTO rec;\n  UPDATE vault.secrets s\n  SET secret = encode(vault._crypto_aead_det_encrypt(\n    message := convert_to(rec.secret, 'utf8'),\n    additional := convert_to(s.id::text, 'utf8'),\n    key_id := 0,\n    context := 'pgsodium'::bytea,\n    nonce := rec.nonce\n  ), 'base64')\n  WHERE id = rec.id;\n  RETURN rec.id;\nEND\n$function$\n","config":["search_path=\"\""],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"45c3edf8140259654aee1807a4ffe9d7afbe55d39676572cf608e79f5bb9d8ed","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"supabase_admin","grantable":true,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"vault.create_secret(text, text, text, uuid)","definition_sha256":"cd921f1ec31bb6cfd83dde4b41ad2fbe4e5fa331858743de0cea635926c8c1d0","language":"plpgsql"},{"schema":"vault","name":"update_secret","oid":16630,"args":"secret_id uuid, new_secret text, new_name text, new_description text, new_key_id uuid","argtypes":"uuid, text, text, text, uuid","prosrc":"\nDECLARE\n  decrypted_secret text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = secret_id);\nBEGIN\n  UPDATE vault.secrets s\n  SET\n    secret = CASE WHEN new_secret IS NULL THEN s.secret\n                  ELSE encode(vault._crypto_aead_det_encrypt(\n                    message := convert_to(new_secret, 'utf8'),\n                    additional := convert_to(s.id::text, 'utf8'),\n                    key_id := 0,\n                    context := 'pgsodium'::bytea,\n                    nonce := s.nonce\n                  ), 'base64') END,\n    name = coalesce(new_name, s.name),\n    description = coalesce(new_description, s.description),\n    updated_at = now()\n  WHERE s.id = secret_id;\nEND\n","probin":null,"rettype":"void","language_oid":"13619","definition":"CREATE OR REPLACE FUNCTION vault.update_secret(secret_id uuid, new_secret text DEFAULT NULL::text, new_name text DEFAULT NULL::text, new_description text DEFAULT NULL::text, new_key_id uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE\n  decrypted_secret text := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = secret_id);\nBEGIN\n  UPDATE vault.secrets s\n  SET\n    secret = CASE WHEN new_secret IS NULL THEN s.secret\n                  ELSE encode(vault._crypto_aead_det_encrypt(\n                    message := convert_to(new_secret, 'utf8'),\n                    additional := convert_to(s.id::text, 'utf8'),\n                    key_id := 0,\n                    context := 'pgsodium'::bytea,\n                    nonce := s.nonce\n                  ), 'base64') END,\n    name = coalesce(new_name, s.name),\n    description = coalesce(new_description, s.description),\n    updated_at = now()\n  WHERE s.id = secret_id;\nEND\n$function$\n","config":["search_path=\"\""],"secdef":true,"volatility":"v","leakproof":false,"strict":false,"parallel":"u","kind":"f","owner":"supabase_admin","sha256":"26037d4292c5a86ea1ef932dd3286e628aacb2473f09e349636ef92d3b1afd04","service_exec":true,"anon_exec":false,"authenticated_exec":false,"acl":[{"grantee":"postgres","grantor":"supabase_admin","grantable":true,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"supabase_admin","grantor":"supabase_admin","grantable":false,"privilege":"EXECUTE"}],"signature":"vault.update_secret(uuid, text, text, text, uuid)","definition_sha256":"9ab4c94a4ed480064303a497a6132ba2318cdc5899477a8354916da0481754c5","language":"plpgsql"}]$extrascompose$::jsonb) LIMIT 70 LOOP
 SELECT p.oid,p.prosrc,p.proconfig,p.prosecdef,p.proowner,p.proacl,p.prokind,p.probin,p.prorettype,p.proargtypes,p.provolatile,p.proleakproof,p.proisstrict,p.proparallel,l.lanname,(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'grantable',a.is_grantable,'privilege',a.privilege_type) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a LIMIT 1) acl INTO actual FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(e->>'signature') LIMIT 1;
 IF NOT FOUND OR actual.prosrc IS DISTINCT FROM e->>'prosrc' OR pg_get_functiondef(actual.oid) IS DISTINCT FROM e->>'definition'
 OR encode(extensions.digest(actual.prosrc,'sha256'),'hex') IS DISTINCT FROM e->>'sha256'
 OR encode(extensions.digest(pg_get_functiondef(actual.oid),'sha256'),'hex') IS DISTINCT FROM e->>'definition_sha256'
 OR coalesce(to_jsonb(actual.proconfig),'null'::jsonb) IS DISTINCT FROM e->'config' OR actual.prosecdef IS DISTINCT FROM (e->>'secdef')::boolean
 OR pg_get_userbyid(actual.proowner) IS DISTINCT FROM e->>'owner' OR actual.acl IS DISTINCT FROM e->'acl'
 OR actual.prokind::text IS DISTINCT FROM e->>'kind' OR actual.lanname IS DISTINCT FROM e->>'language' OR actual.probin IS DISTINCT FROM e->>'probin'
 OR format_type(actual.prorettype,NULL) IS DISTINCT FROM e->>'rettype' OR oidvectortypes(actual.proargtypes) IS DISTINCT FROM e->>'argtypes'
 OR actual.provolatile::text IS DISTINCT FROM e->>'volatility' OR actual.proleakproof IS DISTINCT FROM (e->>'leakproof')::boolean
 OR actual.proisstrict IS DISTINCT FROM (e->>'strict')::boolean OR actual.proparallel::text IS DISTINCT FROM e->>'parallel'
 OR has_function_privilege('anon',actual.oid,'EXECUTE') IS DISTINCT FROM (e->>'anon_exec')::boolean
 OR has_function_privilege('authenticated',actual.oid,'EXECUTE') IS DISTINCT FROM (e->>'authenticated_exec')::boolean
 OR has_function_privilege('service_role',actual.oid,'EXECUTE') IS DISTINCT FROM (e->>'service_exec')::boolean
 THEN RAISE EXCEPTION 'COMPOSE STATIC70 exact drift %',e->>'signature' USING ERRCODE='55000'; END IF;
 END LOOP; END IF;
